window.BOOK_INDEX = {"version":"v3.0","total":425,"updated":"2026-11-08","chapters":[{"id":"ch5","no":5,"name":"教材与专著","count":102},{"id":"ch6","no":6,"name":"官方文档与竞赛规则","count":60},{"id":"ch7","no":7,"name":"在线平台与题库","count":52},{"id":"ch8","no":8,"name":"集训队论文与专题讲义","count":57},{"id":"ch9","no":9,"name":"历年真题与题解","count":79},{"id":"ch10","no":10,"name":"课程与视频","count":37},{"id":"ch11","no":11,"name":"工具与环境","count":24},{"id":"ch12","no":12,"name":"社区与期刊","count":14}],"levels":["通用","CSP-J","CSP-S","NOIP","省选","NOI","IOI"],"uses":["入门自修","体系学习","专题突破","赛前冲刺","教练备课","查漏补缺","实战训练"],"effects":["速查","深耕","实战","方法论"],"items":[{"no":1,"t":"48 课搞定信息学奥赛：C++ 趣味编程","sub":"","kind":"教材","auth":"","pub":"人民邮电出版社","year":"2025","lv":["CSP-J"],"use":["入门自修","教练备课"],"fx":["深耕"],"how":"纸质书（336 页，ISBN 9787115679116）","url":"https://www.tenlong.com.tw/products/9787115679116","note":"李超（B 站与公众号 ID @bigbigli）著，人民邮电出版社 2025 年 9 月第 1 版，336 页，ISBN 9787115679116，官方定位为 8 岁以上、面向 CSP-J/S 的零基础备赛书。它的差异点不在内容深浅，而在「课表化」：全书 10 章切成 48 课，每课固定为知识讲解、实例讲解、练习三段，一次课 1—2 小时可讲完，教练可以直接当社团课的教案用，不必自己拆课时。10 章依次是顺序结构（输出、变量、实数、除法与求余、强制类型转换、字符与 ASCII、复合运算）、选择结构（单/双/嵌套/多分支/switch）、循环结构（for、求和求积、while、break/continue、嵌套）、数组与字符串（一维二维数组、字符数组与常用操作）、排序（选择、冒泡及优化、插入、计数及其去重计数变体）、基础算法（暴力枚举、递推、函数与参数传递、结构体及排序、递归与汉诺塔、二分查找）、数学（因数与公倍数、辗转相除、质数与埃氏筛）、模拟（一维/二维数组模拟、日期模拟、字符串模拟）、算法进阶（贪心与证明、DFS、BFS、记忆化搜索到 DP）、数据结构（栈、队列、链表与指针、树与二叉树遍历、图的存储、Floyd 与 Dijkstra），附录给「信息学奥赛成长指南」。取舍很清楚：语言部分讲到结构体成员函数、排序比较器这一层，足够写 CSP-J 第二轮前两题；算法部分停在 BFS/DP 入门与最短路，覆盖 CSP-J 第 3—4 题常见模型。局限必须写清：全书没有树状数组、线段树、字符串算法（KMP/哈希）、网络流，DP 只到记忆化与线性，对 CSP-S 与 NOIP 明显不够；例题以课内练习为主，缺少整套限时模拟，需另配真题（见本目录历年真题与题解一章）；属零基础教材，已有语法基础者会嫌前 20 课冗余。","ch":5},{"no":2,"t":"C++编程与信息学竞赛数学思维","sub":"","kind":"教材","auth":"","pub":"北京大学出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","体系学习"],"fx":["深耕"],"how":"纸质书（配课件与教学视频）","url":"https://item.winxuan.com/1204380298","note":"王桂平、简星、耿霄、李周著，2026 年 6 月第 1 版，ISBN 9787301370063，306 页、482 千字，定价 89 元，中图法 TP312.8C++ / TP301.6。作者王桂平是重庆交通大学计算机系副教授，2003 年起带队参加 ACM/ICPC、天梯赛、蓝桥杯，另著有《信息学竞赛教程（初级）》《C++ 趣味编程及算法入门》——后者的思路在这本书里被推到竞赛端。全书 12 章：变量及输入输出、用单位正方形与单位立方体理解数学问题、基本运算的理解、数列问题、递推及递推问题求解、一维和二维数表、方向位置与直角坐标系、网格坐标系及网格问题、初等几何问题、初等数论问题、集合论基础、组合数学初探，含 200 余道微实例、130 余道编程实例与 300 余幅自绘图表。它真正稀缺的地方不是覆盖面（这些知识点任何一本入门书都有），而是讲法：把「乘法分配律」画成单位正方形拼长方形、把「勾股数」画成正方形面积、把网格题画成坐标系，用图形替代公式来建立直觉。这恰好补上了国内信奥教材的短板——绝大多数教材默认读者已经具备初中数学的抽象能力，一上来就写递推式，而小学高年级起步的学员卡在「为什么这个递推是对的」这一步。局限：数学深度止于初等数论（同余、gcd）与组合初探，没有生成函数、没有群论、没有线性代数，不能当数学专题书用；例题以自编微实例为主，缺少 CSP 真题的难度梯度；「用正方形理解乘法」这类讲法对高中生显得幼稚，成年自学者会觉得啰嗦。适合的对象是小学高年级到初一的自学者、以及带低龄班的教练——后者可直接借用书里的图示做课件。","ch":5},{"no":3,"t":"CCF CSP 例题解析与实战技巧：编程基础","sub":"","kind":"教材","auth":"","pub":"机械工业出版社（中国计算机学会 组编）","year":"2026","lv":["CSP-J","CSP-S"],"use":["入门自修","查漏补缺"],"fx":["实战","速查"],"how":"纸质书（59 元，165 页）","url":"https://ebooks.cmpbook.com/detail?id=30183","note":"朱青、朴乘志编著，中国计算机学会组编，总主编张孝（中国人民大学信息学院副院长），2026 年 8 月第 1 版，ISBN 978-7-111-81458-0，165 页 59 元。属「CCF CSP 认证辅导丛书」，全套三册按认证题目顺序分册：本册对第 1—2 题、工程实现对第 3 题、算法应用对第 4 题。全书 6 章——绪论、循环（对应第 1 题），排序、数学基础（对应第 2 题的子任务），序列查询与维护、动态规划（对应第 2 题的满分解法），真题范围 2014—2024。价值在于它把「第 2 题怎么从暴力拿到满分」拆成了可复用的三段：先写对（循环与模拟的边界）、再写快（把重复扫描换成前缀和/排序/差分）、最后写稳（边界、溢出、多组数据）。这三段与 CSP-J 后两题、CSP-S 前两题的训练点同源，适合作为「会语法但总在第 2 题丢分」的补漏材料。局限有三：出版社与 CCF 都明确这套丛书面向高校学生与职场人士、不面向中小学生，题面背景是认证式而非竞赛式；内容止于第 2 题，不含树、图、DP 优化；例题难度低于 NOIP 提高组后两题，指望它冲省选是一厢情愿。","ch":5},{"no":4,"t":"CCF CSP 第一轮认证一本通（第 2 版）","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","赛前冲刺"],"fx":["速查","实战"],"how":"纸质书","url":"https://www.tup.tsinghua.edu.cn/bookscenter/book_10454001.html","note":"丁向民编著，2026 年 8 月第 2 版第 1 次印刷，ISBN 9787302724575，16 开 249 页、39.4 万字，定价 79.9 元，中图法 TP311-49。结构八章：前四章按选择题考点分块（计算机基础知识、程序设计基础、基本数据结构、离散数学与组合数学），每节固定三段式「基本知识介绍—典型习题解析—知识点巩固」；后四章专攻阅读程序题与完善程序题。第 2 版与前版最大的差别不在加题而在配比：作者在前言里给出 2019—2024 六年选择题逐知识点出题数的统计表，据此压缩了基本常识、系统结构、软件系统这些多年不考的内容，把占比上升的第 2 章 C++ 语言基础扩写，删减第 4 章应用数学，等于按真题频次重排篇幅。时效性上还有一层背景：CSP-J/S 大纲 2021 年发布，2023、2025 年两次修订，本书对齐 2025 年修订版，这是它相对旧版与多数同类的优势所在。用法：先用前四章的「知识点巩固」按块补漏，再用后四章做程序阅读与填空的专项训练，最后整卷计时验收。局限：只覆盖第一轮笔试，不含上机；例题以真题改编为主，原创题比例偏低；无配套在线题库，答案与解析都在书内。","ch":5},{"no":5,"t":"CCF GESP 直通车：C++ 六级七级精讲精练","sub":"","kind":"教材","auth":"","pub":"复旦大学出版社","year":"2026","lv":["CSP-J"],"use":["入门自修","查漏补缺"],"fx":["深耕","速查"],"how":"纸质书","url":"http://www.cnbip.cn/BaseInfo/BookInfo.aspx?id=202291928","note":"沈根成编著，2026 年 8 月第 1 版，ISBN 9787309188530，169 页、26cm，定价 98 元，中图法 TP312.8。“CCF GESP 直通车”系列的第四本，按 GESP 六级、七级的 C++ 考试大纲编写，全书七部分：类与面向对象、抽象数据类型（栈、队列及其容器适配器）、树与遍历（二叉树、哈夫曼树与哈夫曼编码、DFS/BFS）、一维动态规划（背包、最长上升子序列）、高级数学库函数与哈希表、二维动态规划（最长公共子序列、石子合并等区间 DP）、初级图论（图的表示与存储、遍历及应用）。它在知识阶梯上的位置很明确：六级七级正好卡在“语法学完、复赛刚起步”，对应本书 22—26 章的入口段，比《CCF 信息学奥赛入门篇》深一层，又够不到《提高篇》的线段树、网络流。局限要说清楚：169 页摊七个专题，每块只到“能写出模板”，复杂度推导与优化基本没有；字符串算法、树状数组与线段树、网络流一概不涉及；例题以考级题型为主，竞赛真题比例低；GESP 是 CCF 的等级认证而非竞赛本身，拿它冲 CSP-J 一等奖还得另配真题卷与模拟卷（见真题卷与模拟卷两本）。适合的对象是自学的中小学生和带入门班的教练——每部分末尾的延伸阅读可以当课堂补充材料。","ch":5},{"no":6,"t":"CCF 中学生计算机程序设计","sub":"入门篇","kind":"教材","auth":"中国计算机学会 组编","pub":"科学普及出版社","year":"2016","lv":["CSP-J"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"https://www.noi.cn/","note":"主办方自己出的教材，与大纲覆盖面高度一致，适合作为第一本系统读本。","ch":5},{"no":7,"t":"CCF 中学生计算机程序设计","sub":"基础篇","kind":"教材","auth":"陈颖、邱桂香、朱全民 主编","pub":"科学普及出版社","year":"2017","lv":["CSP-J","CSP-S"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书","url":"https://www.noi.cn/","note":"承接入门篇，把数组、函数、结构体与基础算法补齐，语法体系最稳。","ch":5},{"no":8,"t":"CCF 信息学奥赛基础篇","sub":"","kind":"教材","auth":"","pub":"机械工业出版社（中国计算机学会组编）","year":"2025","lv":["CSP-J","CSP-S"],"use":["体系学习","教练备课"],"fx":["深耕"],"how":"纸质书","url":"https://ebooks.cmpbook.com/detail?id=28087","note":"朱全民主编、江涛编，2025 年 8 月第 1 版，ISBN 978-7-111-78233-9，99 元。官方「CCF 全国青少年信息学奥林匹克竞赛教程」丛书第二册，覆盖 NOI 大纲中难度系数 3—4 及少量 5 的知识点，正好补上《入门篇》（1—2）与《提高篇》（5—8）之间的空档。全书四章：C++ 程序设计进阶（二维与多维数组、常用数学函数、指针、结构体与联合体、STL 算法函数）、数据结构及其应用、算法设计、数学运用。每节按「情境导航—问题抽象—知识探究—实践应用—总结提升」五段展开，附录给出知识点与大纲条目的对应表。适用场景：学完语法、能写循环但不会建图建模的 CSP-J 冲一等学生；教练也可直接当校本教材，因为每节都能对回大纲编号。","ch":5},{"no":9,"t":"Cracking the Coding Interview","sub":"","kind":"教材","auth":"Gayle Laakmann McDowell","pub":"CareerCup","year":"2008","lv":["CSP-J","CSP-S"],"use":["入门自修","查漏补缺"],"fx":["实战"],"how":"纸质书","url":"","note":"入门友好，讲清「面试官想看什么」。对 OI 帮助有限，但适合刚开始写代码时建立手感。","ch":5},{"no":10,"t":"Think Like a Programmer","sub":"","kind":"教材","auth":"V. Anton Spraul","pub":"No Starch Press","year":"2012","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["方法论"],"how":"纸质 / 电子书","url":"","note":"教「怎么把问题拆成可编码的步骤」，而不是教语法。初学者最缺的正是这一层。","ch":5},{"no":11,"t":"中学生计算机程序算法入门：例题精析与训练","sub":"","kind":"教材","auth":"","pub":"科学出版社","year":"2025","lv":["CSP-J"],"use":["入门自修","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://book.douban.com/isbn/9787030802309/","note":"陈锋编著，2025 年 1 月第 1 版，ISBN 9787030802309，B5 开、330 页、32.7 万字，定价 58 元。全书 8 章，例题全部取自 AtCoder Beginner Contest（ABC201B、ABC242B、ABC231B、ABC219C、ABC203C、ABC208C、ABC228C、ABC240B、ABC260B、ABC272C、ABC273C、ABC323B/C 等），章末习题亦为同源真题，覆盖排序、算法设计策略、枚举、模拟、二分、贪心、搜索、基础数据结构、动态规划、数论、组合数学，并专讲 STL 的高效用法。它真正的差异点是题源：国内入门书多用洛谷/一本通题库，这本书直接用 AtCoder 的 ABC 题，题面短、数据弱、判题即时，初学者可以在学完一节后立刻在线提交拿到反馈，不必等中文 OJ 的题面翻译，也不会被「题面比算法难读」卡住。定位要讲清：难度天花板明确停在 CSP-J 第一轮与复赛前两题，没有图论算法（最短路、生成树、连通性一概没有）、没有高级数据结构、没有字符串算法；330 页 8 章配 58 元定价，意味着单题讲解偏简，多为「题意—思路—代码」三段，不适合当唯一教材。适合小学高年级到初一的自学者、以及带低龄班的教练做课后作业册（题号可直接定位到 AtCoder，布置与验收都省事）。已学完语法、能独立写搜索与简单 DP 的选手跳过即可。","ch":5},{"no":12,"t":"信奥逐梦之路：家长陪伴与升学规划全阶段指南","sub":"","kind":"专著","auth":"","pub":"人民邮电出版社","year":"2026","lv":["CSP-J","CSP-S","NOIP"],"use":["教练备课","体系学习"],"fx":["方法论"],"how":"纸质书（192 页，59.80 元）","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=4989075","note":"王津著，2026 年 2 月第 1 版，ISBN 9787115690357，16 开 192 页、228 千字，定价 59.80 元，中图法 TP311.1-62，读者范围官方标注为「参加信奥竞赛孩子的家长」。作者是梦熊信奥联盟创始人，团队为全国百余所信息学竞赛强校提供教研服务。这不是算法教材，而是全库目前唯一一本专门处理「赛事体系与长期规划」的专著：第一章先把 NOI、NOIP、CSP-J/S、GESP 四条线的区别、衔接与各自适用学段拆开，再讲参赛适配性、C++ 学习必要性、课程与训练方案、学训常见误区、竞赛与文化课的时间平衡，最后收录 10 位 NOI 金银牌得主的成长回忆录，并提出 3T 分层培养 + 5M 闭环训练的阶段目标表。它的实际读者是家长与低年级教练：多数家庭的第一处失分不在算法，而在把「CSP 评级」当成「NOIP 获奖」、把 GESP 当成 CSP 前置、或在小学阶段误判报名资格（参见本目录《关于参加 CSP-J/S 认证需符合年龄条件的公告》），这本书提供的是一张能把政策、时间投入与阶段目标对齐的地图。教练可取其章节框架开家长会或做社团入门宣讲。局限必须写清：全书不含算法讲解与代码，不能替代任何教材；「升学优势」「特殊招生渠道」等内容与当年各省政策强绑定，2026 年之后须与 CCF 及本地教育部门最新文件核对；作者本身运营赛训平台，机构筛选、课程选择等章节含商业视角，涉及「保过奖」「速成班」的判断虽直指行业乱象，仍应结合 CCF《关于 NOI 相关权益的声明》自行复核。","ch":5},{"no":13,"t":"信息学奥赛1：114道题零基础吃透C++与算法基础","sub":"","kind":"教材","auth":"","pub":"北京大学出版社","year":"2026","lv":["CSP-J"],"use":["入门自修","实战训练"],"fx":["实战"],"how":"纸质书（配视频教程）","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=5046086","note":"王健伟著，2026 年 3 月第 1 版，ISBN 9787301370056，388 页、26cm，中图法 TP311.1。这是王氏三册系列的第 1 册——第 2 册是《信息学奥赛2：121 道题零基础吃透高级算法与数据结构》（DP 与四类结构），第 3 册是《信息学奥赛3：历年真题解析与拉分解题思维训练》（近十年 CSP-J 真题），三册合起来正好是从语法到真题的一条线，此前库里只收了后两册，这一册补上入门端。内容按 16 章分两块：第 1—7 章是 C++ 语言基础（环境搭建、基础语法、数组、函数、编译预处理、结构体、scanf/cout/cin 与命名空间、string、二/八/十/十六进制互转、位运算），第 8—16 章全是刷题，按八类题型推进——排序、递推、递归、搜索与回溯、高精度、贪心、分治、广度优先搜索，共 114 道经典例题，每题配代码与讲解，另附视频教程。定位要说清：它的天花板就是 CSP-J 第一轮与复赛前两题，动态规划、图论、树状数组一概不涉及，覆盖范围比《CCF 信息学奥赛入门篇》略窄但题量更密；「114 道题」这个规模的真正价值是题单完整、题型不重不漏，适合零基础学员按章过关，也适合教练拿它当入门班的作业册。不适合的人群也很明确：已经能独立写搜索与简单 DP 的选手用它只会浪费时间；想系统学算法体系应直接上《算法竞赛进阶指南》或《CCF 信息学奥赛基础篇》。","ch":5},{"no":14,"t":"信息学奥赛2：121道题零基础吃透高级算法与数据结构","sub":"","kind":"教材","auth":"","pub":"北京大学出版社","year":"2026","lv":["CSP-J"],"use":["专题突破","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://www.gxjcy.cn/web/tmDetails?jiaocaiId=1033179","note":"王健伟著，2026 年 4 月第 1 版，ISBN 9787301372326，系列三册中的第 2 册。前半讲动态规划（网格路径、序列、背包、区间、分割、编辑距离、计数），后半讲栈、队列、树、图四类结构，共 121 道题配视频讲解。定位明确指向 CSP-J 的 DP 与数据结构分水岭，适合在基础语法过关后集中攻难点。","ch":5},{"no":15,"t":"信息学奥赛一本通","sub":"C++ 版","kind":"教材","auth":"董永建、黄新军 等","pub":"科学技术文献出版社","year":"2013","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书 + 在线题库","url":"","note":"国内中学教学用得最多的入门教材，配套题库与视频齐全，最适合零基础自学。","ch":5},{"no":16,"t":"信息学奥赛一本通","sub":"初赛篇","kind":"教材","auth":"董永建 等","pub":"南京大学出版社","year":"2019","lv":["CSP-J","CSP-S"],"use":["赛前冲刺"],"fx":["速查","实战"],"how":"纸质书","url":"","note":"专攻第一轮笔试：计算机基础、阅读程序、完善程序，是国内少见的初赛专项书。","ch":5},{"no":17,"t":"信息学奥赛初赛全解","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","赛前冲刺"],"fx":["实战","速查"],"how":"纸质书","url":"http://www.ceeol.cn/bookshow.asp?id=3228843","note":"马强主编，2026 年 8 月第 1 版，ISBN 9787302721734，16 开 164 页，定价 79 元，中图法 TP311.1-44。作者 2007 年起做信息学奥赛教学，先后任教于北京十一学校、人大附中朝阳学校、首师大附中，后任信息学教研负责人，曾参与设计 CCF GESP 考试大纲。全书三部分七章：第 1—5 章按初赛考点分块——计算机基础知识、C++ 语法、数据结构、数学（含排列组合与复杂度估算）、算法，每块配专题练习；第 6 章是 CSP-J 与 CSP-S 各一份模拟卷，附答案与思路解析；第 7 章是近几年真题的逐题解析。与同作者 2024 年的《信息学奥赛导学·初赛篇》（ISBN 9787302673231）是两条线：导学篇按讲义顺序铺知识点，本书按题型分块、以题带点，做题密度更高。定位必须说清：只覆盖第一轮笔试（选择、判断、程序阅读、程序填空），不含任何上机实现，替代不了复赛教材；模拟卷的难度标定出自作者个人判断，跨省横向比较时要打折。适合初赛前六到八周做查漏补缺：先做一套卷定位失分模块，再回对应章节补，最后用真题章验收。","ch":5},{"no":18,"t":"信息学奥赛大通关·入门篇（上下册）","sub":"","kind":"教材","auth":"","pub":"华南理工大学出版社","year":"2026","lv":["CSP-J"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"https://hg.cb.scut.edu.cn/bookCenter/15215.html","note":"王晓鹏、周弋林编著，2026 年 4 月第 1 版，ISBN 978-7-5623-8150-1，504 页，全 2 册定价 89 元。王晓鹏为广州大学附属中学信息学主教练、NOI 金牌教练，该书由广州市教育局协同育人重点项目资助。八个单元从「从计算机到信息学奥赛」起，经顺序、分支、循环、数组、字符串、自定义函数与结构体，收在 C++ 标准模板库，另附普及组真题选讲。写法上每个单元先给思维导图搭框架，语法与算法建模同步引入，并对通用题给「一题多解」对比。适合小学高年级至初一、有教练或家长带读的起步阶段；对已过语法、只缺算法的读者边际价值有限。","ch":5},{"no":19,"t":"信息学奥赛打通关 · 入门篇（全 2 册）","sub":"","kind":"教材","auth":"","pub":"华南理工大学出版社","year":"2026","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书（全 2 册，490 页）","url":"https://thep.com.tw/book/1819533","note":"王晓鹏、周弋林著，2026 年 4 月第 1 版，ISBN 9787562381501，全 2 册共 490 页。作者王晓鹏是广州大学附属中学信息学主教练、NOI 金牌教练，近四年带出 5 人次进入广东省队、NOI 1 金 2 银 2 铜。上册按「从计算机到信息学奥赛—顺序结构—分支结构—循环结构」四个单元展开，每课固定四段：思维导图导入、知识点、牛刀小试、拓展阅读，下册续接后续单元。它与市面上多数入门书的两点差异值得注意：一是「比特时空观」「数位与进位基础」这类内容被前置到第一单元，把「数据在机器里怎么存」讲在语法之前，后面讲溢出、取模、位运算时就不需要再补课；二是明确写了「一题多解」——同一道题给出不同算法思路与代码策略的对比，这对入门阶段形成「解法可迁移」的意识比多做十道题更有用。适合小学高年级到初一、由教练或家长带读的起步阶段，也适合作为校内社团课的分层教材。局限：定位是零基础，算法部分只到枚举、模拟、简单排序与递推，不覆盖 DP 与图论；书名虽含「竞赛」，但深度对应 CSP-J 第一轮与第二轮前两题，不能替代提高组教材。","ch":5},{"no":20,"t":"信息学奥赛课课通","sub":"","kind":"教材","auth":"林厚从","pub":"南京大学出版社","year":"2019","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"按课时切分的教材，一节一个小知识点配一道练习。适合学校把它当正课教材用，节奏比一本通更松。","ch":5},{"no":21,"t":"信息学竞赛教程（初级）","sub":"","kind":"教材","auth":"","pub":"北京大学出版社","year":"2025","lv":["CSP-J","CSP-S"],"use":["体系学习","教练备课"],"fx":["深耕"],"how":"纸质书","url":"https://book.douban.com/isbn/9787301364277/","note":"王桂平、周祖松、万毅、陈胤戬编著，2025 年 10 月第 1 版，ISBN 9787301364277，449 页，定价 99 元。特点是「按大纲分层」：依据 CCF《NOI 系列竞赛大纲》把知识点按难度切成初级、中级、高级三层，各对应一册、每册 40 章，初级册覆盖基础算法、进制转换、位运算、编码问题、数列问题、高精度、字符串处理、时间日期、数据结构、排序、搜索、动态规划、数论、组合数学、图论共 15 个专题。每章固定「理论 + 实践」两段：先讲算法思想与数学依据，再用经典竞赛题落到实现，配 120 个案例解析、500 余道实战题与 300 段视频讲解。对教练的实际价值在于课时可切分——40 章正好对应一个学年 40 周，不必自己重排《进阶指南》的章节顺序。局限要说清：初级册深度只到 CSP-J 全部加 CSP-S 前半，提高段仍需接《算法竞赛进阶指南》或 CCF 提高篇；作者团队以重庆育才、重庆一中教练为主，例题偏西南地区训练风格。","ch":5},{"no":22,"t":"啊哈！算法","sub":"","kind":"教材","auth":"纪磊（啊哈磊）","pub":"人民邮电出版社","year":"2014","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书","url":"","note":"用插图和故事讲算法，零基础建立直觉最快的一本。深度有限，作用是「破冰」而非「学完」。","ch":5},{"no":23,"t":"我的第一本算法书","sub":"","kind":"教材","auth":"石田保辉、宫崎修一","pub":"人民邮电出版社","year":"2018","lv":["CSP-J"],"use":["入门自修"],"fx":["速查"],"how":"纸质书","url":"","note":"全彩步骤图讲 7 种数据结构与 26 个算法，适合当作视觉化的预习材料。","ch":5},{"no":24,"t":"我的第一本算法竞赛启蒙书","sub":"","kind":"教材","auth":"","pub":"科学出版社","year":"2026","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书","url":"https://www.aijiaocai.com/textbook/details?textbook_id=14247161","note":"钟旸、陈茁、罗云珂著，2026 年 6 月第 1 版，ISBN 9787030838193。面向零基础青少年，按「语言基础—算法与数学思维—数据结构与图论入门」三梯度展开，特点是先从数学原理引出算法再落到代码，并配线上评测。适合小学高年级至初一、家长或教练带读的起步阶段。","ch":5},{"no":25,"t":"深入浅出程序设计竞赛","sub":"基础篇","kind":"教材","auth":"洛谷学术组、汪楚奇","pub":"高等教育出版社","year":"2020","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书","url":"https://www.luogu.com.cn/","note":"每章开头有思维导图，近 400 道例题全部可在洛谷提交，边读边判题，反馈闭环最短。","ch":5},{"no":26,"t":"用 AI 决胜信息学奥赛：C++ 编程基础","sub":"","kind":"教材","auth":"","pub":"电子工业出版社","year":"2026","lv":["CSP-J"],"use":["入门自修","查漏补缺"],"fx":["方法论"],"how":"纸质书","url":"https://www.hxedu.com.cn/hxedu/hg/book/bookInfo.html?code=TP523200","note":"王俊杰著，2026 年 3 月第 1 版，ISBN 9787121523205，16 开 420 页，定价 99 元。作者为北大、北理工双硕士，曾任海淀区高中信息技术教师与字节、腾讯、百度研发，现做 AI 教育，身份组合正好对上这本书的两条主线。全书三篇：认识篇讲信息学奥赛的赛事阶梯（CSP-J/S—NOIP—省选—NOI—IOI）与学习路径；能力篇是全书重心，讲提示词的设计要素与模板、常用 AI 工具的具体用法，把「让 AI 解释概念、审查边界条件、生成变式题、规范代码风格」拆成可复用的操作流程；实战篇才是 C++ 语法本体——二进制、数据类型、流程控制、函数、数组、指针、结构体，每节配提示词案例与测试题。定位要说清楚：它是「零基础语法 + AI 使用法」，不是算法书，动态规划、图论、数据结构一概不涉，因此只能作为第 22 章（语言与工程习惯）的辅助读物，不能替代任何一本竞赛教材。真正的看点在能力篇——AI 辅助学习的边界（不许直接抄答案、AI 会编错解、基本功必须自己练）写得比多数同类书清醒。局限：配套资源页标注「本书暂无资源」，无在线题库；提示词效果强依赖所用模型的版本，2026 年可用的模板到学生手里未必同样有效。","ch":5},{"no":27,"t":"算法与数学：数学思维与编程实践","sub":"","kind":"教材","auth":"","pub":"科学出版社","year":"2025","lv":["CSP-J","CSP-S"],"use":["查漏补缺","体系学习"],"fx":["深耕"],"how":"纸质书","url":"https://book.douban.com/isbn/9787030822437/","note":"米田优峻著，李曙、余岳译，2025 年 7 月第 1 版，ISBN 9787030822437，288 页，定价 98 元，中图法 TP301.6，原作名《問題解決のための「アルゴリズム×数学」が基礎からしっかり身につく本》。与同作者的《算法竞赛黄金法则》同期推出、出自同一译者团队，但两书分工不同：那本按「技巧」组织，这本按「数学」组织，把算法学习所需的中学到大学数学压成 9 个要点，再逐条落到二分查找、素性判定、欧几里得算法、蒙特卡罗方法、排序、动态规划、埃氏筛、图论算法上，配 200 余道例题习题与 30 道综合测试题。价值在于补的是「为什么这个算法成立」这一层：多数竞赛教材把递推关系、同余、期望、图论结构当工具直接给结论，本书反过来从数学结构推算法，适合已经能写模板、但一遇变形题就不知从何下手的 CSP-S 段读者。局限：不覆盖线段树、网络流、字符串、计算几何等专题，不能当唯一教材；翻译腔较重，部分术语与国内竞赛习惯叫法不同（如「蒙特卡罗方法」在竞赛语境里多称随机化算法）；例题以日本赛题（AtCoder、JOI）为主，与 CSP/NOIP 真题风格有差异，需自行迁移。","ch":5},{"no":28,"t":"算法图解","sub":"","kind":"教材","auth":"Aditya Bhargava","pub":"人民邮电出版社","year":"2017","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书 / 电子书","url":"","note":"图多字少，讲清二分、递归、动态规划的基本直觉。代码是 Python，不影响理解。","ch":5},{"no":29,"t":"算法竞赛从新手到高手","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"https://www.zxhsd.com/kgsm/ts/2026/05/22/6863300.shtml","note":"陈梦、姜慧慧编著，2026 年 6 月第 1 版，ISBN 9787302715795，共 9 章。路线是「先数据结构后算法」：数组、栈队列、树与二叉树、图（最短路、最小生成树、关键路径），再落到排序、贪心、DP 三类经典算法，每节配竞赛真题。特点是把复杂度分析和「算法分析在竞赛中的应用」提前到第 1 章讲，适合作为第一本系统教材——但深度止于 CSP-S 中段，冲省选需换书。","ch":5},{"no":30,"t":"算法竞赛入门到进阶","sub":"","kind":"教材","auth":"罗勇军、郭卫斌","pub":"清华大学出版社","year":"2019","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"覆盖面比紫书更平缓，从语法一路铺到进阶，适合作为「一本读到黑」的主线。","ch":5},{"no":31,"t":"算法竞赛入门经典","sub":"紫书（第 2 版）","kind":"教材","auth":"刘汝佳","pub":"清华大学出版社","year":"2014","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书 / 配套习题与解答","url":"","note":"中文圈发行量最大的竞赛教材。语言、算法、解题方法三位一体，缺点是例题偏难，第一遍别死磕。","ch":5},{"no":32,"t":"算法竞赛试炼场：洛谷300题精析","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["入门自修","实战训练"],"fx":["实战","深耕"],"how":"纸质书","url":"https://www.tup.com.cn/bookscenter/book_10967201.html","note":"罗勇军、汪楚奇（kkksc03）、陈哲（chen_zhe）合著，2026 年 9 月第 1 版。以洛谷 330 余道题为主线，按「语言入门—模拟枚举—基础算法—数据结构—搜索—数学—DP—图论」八篇递进，每题给出考点、思路与证明、代码，实质是补上「听懂知识点」到「考场能写」之间的题量桥梁。适合已学完语法、需要成体系刷题的 CSP-J/S 选手。","ch":5},{"no":33,"t":"算法竞赛黄金法则：提高算法和思考力的77项技巧","sub":"","kind":"教材","auth":"","pub":"科学出版社","year":"2025","lv":["CSP-J","CSP-S","NOIP"],"use":["体系学习","专题突破"],"fx":["深耕","方法论"],"how":"纸质书","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=4871153","note":"米田优峻著，朱全民译，2025 年 7 月第 1 版，ISBN 9787030820822，定价 128 元，中图法 TP311.1。作者即 AtCoder 上的 E869120，IOI 三届金牌（截至 2020 年），现就读东京大学；译者朱全民为中学正高级、特级教师，独立辅导学生获 IOI 金牌 6 枚、银牌 1 枚。全书十章：算法与时间复杂度、前缀和、二分查找、动态规划、数学问题、思维技巧、启发式、数据结构与查询处理、图算法、综合问题，共 77 个技巧、153 道原创例题、300 余幅全彩插图，书末附 20 道能力测试题。它真正的差异点不在覆盖面——这些知识点任何一本入门书都有——而在第 6 章「思维技巧」与第 7 章「启发式」：把「想奇偶性、算贡献、看上限、逆向、固定并枚举、重述问题、盯不变量」拆成可练习的条目，再补上贪心、局部搜索、模拟退火、集束搜索这套在多数国内教材里被跳过的「拿部分分」工具箱，正好对应 CSP-S 后两题与 NOIP 第三题的实战需求。定位要说清：深度止于提高组，线段树只到 RMQ/RSQ 两类，网络流只到 Dinic 与二分图匹配基础，LCT、树套树、生成函数一概没有，NOI 级读者会觉得浅；行文是日式教科书风格，插图密度高但公式推导少，习惯严谨证明的读者需另配资料。适合 CSP-J 转 CSP-S 的选手做「技巧自检」——按 77 条清单逐项打勾，缺哪条补哪条，比从头刷教材效率高。","ch":5},{"no":34,"t":"算法设计与分析（图解版）","sub":"","kind":"教材","auth":"","pub":"人民邮电出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["速查","深耕"],"how":"纸质书（302 页，ISBN 9787115692252）","url":"https://www.tenlong.com.tw/products/9787115692252","note":"陈小玉著，人民邮电出版社 2026 年 7 月第 1 版，302 页，ISBN 9787115692252。作者是高校副教授兼 ACM 教练、信息学奥赛教练（指导学生获 ACM 亚洲区金牌与蓝桥杯国际赛金牌），此前写过《算法训练营》系列，本书是同一作者面向课堂的「按策略组织」版本：不按数据结构分章，而按解题策略分章，全书 10 章依次是算法入门（复杂度、递推）、STL 常用容器与函数（vector/stack/queue/list/deque/priority_queue/map 与常用算法函数）、递归、贪心（含哈夫曼、Prim/Kruskal、Dijkstra/Floyd/Bellman-Ford/SPFA）、分治（二分查找的多种变体、二分答案、归并排序、复杂度求解的递推法与递归树）、动态规划（要素、爬楼梯、LIS、LCS 等）、回溯法、分支限界法、网络流算法、实用算法。它的差异点在「分支限界」这一章：国内 OI 教材普遍只讲回溯，把「限界函数 + 优先队列式扩展」当作 ACM 内容跳过，而 NOI 级搜索题里「最优解剪枝 + 优先扩展」正是 A*/IDA*（25.6）的前身，本书给了完整交代。写法是全图解 + 代码 + 例题，适合当「第一本按策略编排的教材」通读一遍建立全局观。局限：面向高校课程，例题多为教学例题而非真题，题量与难度都到不了 NOIP；网络流只到 Dinic 与最小费用流的基本形态，没有当前弧与多路增广的常数优化；分治一章的复杂度求解部分对竞赛帮助有限（考场直接用主定理结论即可）。定位：CSP-J 后期到 CSP-S 前期建立「策略—模型」映射的读物，之后仍需转 24—28 章的模板与真题。","ch":5},{"no":35,"t":"聪明人的游戏：信息学探秘（提高篇）","sub":"","kind":"教材","auth":"江涛、陈茂贤","pub":"机械工业出版社","year":"2018","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"以「问题—思路—程序」三段式展开，例题生活化。作者是竞赛教练，知道初学者会在哪里卡住。","ch":5},{"no":36,"t":"计算概论：C++ 编程与信息学竞赛入门","sub":"","kind":"教材","auth":"金靖","pub":"高等教育出版社","year":"2017","lv":["CSP-J"],"use":["入门自修"],"fx":["深耕"],"how":"纸质书","url":"","note":"把大学「计算概论」的框架压进竞赛入门：计算机组成、进制、程序结构、基础算法都有交代。基础打得比同类书厚。","ch":5},{"no":37,"t":"高效通关信息学竞赛·初赛篇（入门组）","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["CSP-J"],"use":["赛前冲刺","查漏补缺","入门自修"],"fx":["速查","实战"],"how":"纸质书","url":"https://wqbook.wqxuetang.com/book/3266087","note":"梁皓然、孙亮亮编著，2026 年 6 月第 1 版，ISBN 9787302715924，271 页，定价 89 元。市面上的算法书几乎都从「读懂题、写对代码」讲起，而 CSP-J 第一轮是 100 分笔试（计算机基础、进制与位运算、程序阅读、复杂度估算、填空），这一本补的正是这块空白：按题型切成单选题、程序阅读题、填空专项题三段分别讲，每类先做真题溯源再归纳高频考法，并逐条标注易错点；末附 10 套模拟赛及题解。三个用法：① 入门组考生在第一轮前 6—8 周按题型刷，比通读教材效率高得多——2026 年入门组全国线是 69.5/55.5/42，笔试不过就没有第二轮；② 教练直接拿它的题型分类做校内初赛讲座的提纲；③ 用 10 套模拟卷做赛前限时训练。局限要写清：只覆盖入门组，提高组第一轮仍需 CCF 笔试题库配合《提高篇》；271 页里 10 套卷占去大半，知识点讲解密度有限，不能当唯一教程，定位是「冲刺手册」而非「系统教材」。","ch":5},{"no":38,"t":"Algorithms Unlocked","sub":"","kind":"教材","auth":"Thomas H. Cormen","pub":"MIT Press","year":"2013","lv":["CSP-S","NOIP"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"CLRS 作者写的「轻量版」，无繁重证明，只讲直觉与过程。啃不动 CLRS 时的正确入口。","ch":5},{"no":39,"t":"Algorithms, 4th Edition（Sedgewick）","sub":"","kind":"教材","auth":"Robert Sedgewick, Kevin Wayne","pub":"Addison-Wesley","year":"2011","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书 / 配套网站免费","url":"https://algs4.cs.princeton.edu/home/","note":"普林斯顿教材，配全套可视化、课件、测试数据。图论与字符串部分尤其扎实。","ch":5},{"no":40,"t":"C++ Primer","sub":"第 5 版","kind":"教材","auth":"Stanley B. Lippman 等","pub":"电子工业出版社","year":"2013","lv":["CSP-S","NOIP"],"use":["查漏补缺"],"fx":["速查"],"how":"纸质书","url":"","note":"不是竞赛书，是语言工具书。STL 与模板那几章值得反复查。","ch":5},{"no":41,"t":"CCF CSP 例题解析与实战技巧：工程实现","sub":"","kind":"教材","auth":"","pub":"机械工业出版社（中国计算机学会 组编）","year":"2026","lv":["CSP-S"],"use":["专题突破","实战训练"],"fx":["实战","深耕"],"how":"纸质书（69 元）","url":"https://www.tenlong.com.tw/products/9787111810971","note":"张锦（湖南师范大学信息科学与工程学院院长）、罗元盛（长沙理工大学）编著，总主编张孝，2026 年 7 月第 1 版，ISBN 978-7-111-81097-1（13 位 9787111810971），定价 69 元；页数各渠道标注不一（196—232 页），以实物为准。与同系列的《编程基础》《算法应用》合为三册，本册专攻认证第 3 题——那道题的特点是「描述长、逻辑碎、纯算法不难但实现容易崩」，官方定位是突破 300 分瓶颈。全书 5 章：前 4 章分别是基础知识、栈和队列、树和图、通用算法框架，每章走「专项知识点 + 典型真题」的结构；第 5 章整章是模拟题。真题覆盖 2014—2022 年。对 OI 选手的实际用处不在认证本身，而在两件事：一是「从冗长描述里抽出核心状态」的建模训练，这正是 CSP-S 第二题与 NOI 前两题失分的主因；二是把栈、队列、树、图这四类结构写成「拿来就能改」的工程模板，而不是竞赛里那种压行写法。适合作为专题突破的材料，按章刷完再回洛谷对应题单。局限：不含第 4 题的算法内容（线段树、图论建模、DP 优化都在《算法应用》里）；题面是认证背景，与 OI 题风格有距离；出版方与 CCF 均声明该丛书不面向中小学生。","ch":5},{"no":42,"t":"CCF 中学生计算机程序设计","sub":"提高篇","kind":"教材","auth":"江涛、宋新波、朱全民 主编","pub":"科学普及出版社","year":"2018","lv":["CSP-S","NOIP"],"use":["体系学习","专题突破"],"fx":["深耕"],"how":"纸质书","url":"https://www.noi.cn/","note":"提高组主线教材，图论与动态规划的写法偏规范，适合立规矩。","ch":5},{"no":43,"t":"CCF 信息学奥赛提高篇","sub":"","kind":"教材","auth":"","pub":"机械工业出版社（CCF 组编）","year":"2026","lv":["CSP-S","NOIP"],"use":["体系学习","专题突破"],"fx":["深耕","方法论"],"how":"纸质书","url":"https://www.noi.cn/cbw/2026-08-18/924758.shtml","note":"朱全民主编，徐先友、汪星明、屈运华编写，2026 年 3 月第 1 版，ISBN 9787111803096。CCF 官方教程丛书第四册，官方口径覆盖 NOI 大纲难度系数 5—8 的知识点，正对 NOIP 与 CSP-S。内容按大纲条目组织：高级数据结构（线段树、树状数组、平衡树）、图论（最短路、网络流、二分图）、DP 进阶（树形、区间、数位）与数论组合。相比市面上按「算法名称」排的教材，它的价值在于章节与考纲一一对应，可用来查「我这个级别还缺哪块」。同为官方系列，《入门篇》面向 1—2 级，《专业篇》尚未出版。","ch":5},{"no":44,"t":"Competitive Programmer's Handbook","sub":"CPH","kind":"教材","auth":"Antti Laaksonen","pub":"自出版（免费 PDF）","year":"2017","lv":["CSP-S","NOIP"],"use":["体系学习","查漏补缺"],"fx":["速查","深耕"],"how":"官网免费下载","url":"https://cses.fi/book/book.pdf","note":"与 CSES 题库一一对应的免费英文书。篇幅短、密度高，英文阅读门槛低，强烈建议通读一遍。","ch":5},{"no":45,"t":"Competitive Programming in Python","sub":"","kind":"教材","auth":"Christoph Dürr、Jill-Jênn Vie","pub":"Cambridge","year":"2020","lv":["CSP-S"],"use":["入门自修"],"fx":["深耕"],"how":"纸质 / 电子书","url":"","note":"用 Python 讲竞赛算法，适合作为第二语言参考。NOI 体系仍以 C++ 为主。","ch":5},{"no":46,"t":"Elements of Programming Interviews","sub":"","kind":"教材","auth":"A. Aziz, T.-H. Lee, A. Prakash","pub":"EPI","year":"2012","lv":["CSP-S","NOIP"],"use":["查漏补缺"],"fx":["实战"],"how":"纸质书","url":"","note":"面试向但题解极细，尤其数组、字符串、哈希部分。用来补「工程化写法」和边界处理习惯。","ch":5},{"no":47,"t":"Guide to Competitive Programming","sub":"","kind":"教材","auth":"Antti Laaksonen","pub":"Springer","year":"2020","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"纸质 / 电子书","url":"","note":"CPH 的扩展学术版，多了证明与复杂度分析，适合想把「为什么」也弄明白的人。","ch":5},{"no":48,"t":"Guide to Competitive Programming","sub":"","kind":"教材","auth":"Antti Laaksonen","pub":"Springer","year":"2017","lv":["CSP-S","NOIP","省选"],"use":["体系学习","专题突破"],"fx":["实战"],"how":"纸质书 / 电子版","url":"","note":"CPH 的扩展版，加入更多例题与实现细节。比 CPH 更适合当「边学边做」的主线教材。","ch":5},{"no":49,"t":"信息学奥赛一本通 · 提高篇","sub":"","kind":"教材","auth":"黄新军、董永建","pub":"科学技术文献出版社","year":"2019","lv":["CSP-S","NOIP"],"use":["体系学习","专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"一本通的提高组分册。OI Wiki 的建议是「选择性阅读」——书里覆盖面广但深度不均，按专题挑着补更划算。","ch":5},{"no":50,"t":"信息学奥赛之数学一本通","sub":"","kind":"教材","auth":"林厚从","pub":"东南大学出版社","year":"2015","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"把竞赛里的数论、组合、概率集中讲一遍，数学薄弱者的补丁包。","ch":5},{"no":51,"t":"挑战程序设计竞赛","sub":"第 2 版","kind":"教材","auth":"秋叶拓哉、岩田阳一、北川宜稔","pub":"人民邮电出版社","year":"2013","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["实战"],"how":"纸质书","url":"","note":"日本 ACM 国家队的训练书，110 余道例题全部来自真实赛题，代码风格极干净。","ch":5},{"no":52,"t":"数据结构与算法分析","sub":"C 语言描述","kind":"教材","auth":"Mark Allen Weiss","pub":"机械工业出版社","year":"2016","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"复杂度分析讲得最扎实的一本。摊还分析那一章，能解释很多竞赛里的「为什么这么快」。","ch":5},{"no":53,"t":"数据结构（C++ 语言版）","sub":"第 3 版","kind":"专著","auth":"邓俊辉","pub":"清华大学出版社","year":"2020","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书 + 慕课","url":"https://www.xuetangx.com/","note":"把平衡树、堆、图讲透的中文教材，配清华慕课，适合打地基。","ch":5},{"no":54,"t":"程序设计竞赛进阶：算法与实践","sub":"","kind":"教材","auth":"","pub":"人民邮电出版社","year":"2026","lv":["CSP-S","NOIP","省选"],"use":["专题突破","实战训练"],"fx":["实战","深耕"],"how":"纸质书（346 页，ISBN 9787115694058）","url":"https://thep.com.tw/book/1814500","note":"邱秋著，人民邮电出版社 2026 年 6 月第 1 版，346 页。作者此前写过入门向的《算法竞赛入门到进阶》（清华大学出版社 2019 年，ISBN 9787302529156），本书不是那本的改版：出版社、篇幅与章节结构全部重做，落点从「入门」移到「进阶」，因此两本可以并存而不重复。全书五章，按「搜索—图—图算法—动态规划—网格」组织：第 1 章回溯法（八皇后、单向与双向搜索、剪枝、正方形剖分、关灯问题、15 数码）；第 2 章图和图遍历（邻接矩阵/边列表/前向星/链式前向星的取舍，BFS/DFS 应用清单含连通性、最短路、最长简单路、着色、LCA、割顶割边、强连通与半连通分支、2-SAT、直径、重心，末接拓扑排序）；第 3 章图算法（欧拉回路、中国邮递员、哈密顿回路、TSP、Prim/Kruskal 与次小生成树、Dijkstra/Bellman-Ford/Floyd 与传递闭包、差分约束、第 K 短路、Ford-Fulkerson→EK→Dinic→ISAP 与最小割、最小费用流、二分图匹配四种算法（网络流、匈牙利、Hopcroft-Karp、Gale-Shapley）与一般图 Edmonds、KM 加权完备匹配、支配集/点覆盖/独立集/最大团、最小路径覆盖与最小边覆盖、树上最小支配/覆盖/独立）；第 4 章动态规划（背包四变体、备忘录与松弛两种视角、集合型/区间型/图论型/概率型/非典型、五种优化：空间、状态、二进制、单调队列、斜率、四边形不等式，末接收子序列子串七题与贪心）；第 5 章把网格类问题单独成章（矩形网格、三角形网格、六边形网格、经纬度）。真正稀缺的是第 3 章的覆盖面：把 Hopcroft-Karp、Gale-Shapley、Edmonds 带花树、KM 与四类图上集合问题放在同一章并各自给出适用条件，这种「一张图配一张算法选择表」的编排在国内教材里少见，正好补上第 28 章各节的横向对照。局限：写法偏经典教材体例，网络流与匹配的实现细节不如现代模板紧凑（缺当前弧优化与多路增广的说明），考场直接抄需要自行加常数优化；第 5 章网格专题对 OI 选手边际价值一般；全书无配套在线题库与测试数据。","ch":5},{"no":55,"t":"算法导论（核心篇）（原书第 4 版）","sub":"","kind":"专著","auth":"","pub":"机械工业出版社","year":"2026","lv":["CSP-S","NOIP","省选","NOI"],"use":["教练备课","查漏补缺"],"fx":["深耕","方法论"],"how":"纸质书","url":"http://www.cmpedu.com/books/book/5610910.htm","note":"Thomas H. Cormen、Charles E. Leiserson、Ronald L. Rivest、Clifford Stein 著，王刚、苏明译，2026 年 5 月第 1 版，ISBN 978-7-111-80002-6，139 元，正文 543 页、907 千字，中图法 TP301.6，属「计算机科学丛书」。这一版中文版做了一次拆册：核心篇收原书第 1—25 章（基础知识、排序与顺序统计量、数据结构、高级设计与分析技术、高级数据结构、图算法六部分），同批另有《算法导论（扩展篇）（原书第 4 版）》（ISBN 978-7-111-80012-5，99 元）收第 26—35 章的专题（含多线程算法、矩阵运算、线性规划、FFT、数论算法、字符串匹配、计算几何、NP 完全性、近似算法）。与库里已有的第 3 版相比，4 版的变化集中在：用「归并排序」而非「插入排序」作第一种算法引入、新增「摊还分析」的独立处理、散列表改用「全域哈希 + 开放寻址」为主线、图算法里删掉了斐波那契堆的部分推导，这几点对竞赛选手影响不大；真正值钱的是它把「平均情况分析」「摊还界」「下界证明」这三套论证范式写透了——竞赛里判断「这个贪心为什么对」「这个势能函数怎么构造」，本质就是摊还分析。用法建议：不要通读。按 29 章（数论）、30 章（字符串匹配）、31 章（计算几何）的对应小节查证结论，或在写集训队论文、准备命题时引用其证明框架；书里的伪代码可直接对照本编第 22—31 章的实现。局限：与竞赛的距离仍然远——没有线段树合并、没有 LCT、没有后缀自动机、没有网络流的 Dinic 实现，NP 完全性那部分讲的是理论可归约性而非考场上的状压与搜索剪枝；印刷体量大、单价高，对 CSP-J/S 段选手性价比很低。","ch":5},{"no":56,"t":"算法思维训练：信奥大师的算法教与学秘籍","sub":"","kind":"专著","auth":"","pub":"人民邮电出版社（Michal Forišek、Monika Steinová 著）","year":"2025","lv":["CSP-S","NOIP","省选"],"use":["教练备课","体系学习"],"fx":["方法论"],"how":"纸质书（95 页，ISBN 9787115680044）","url":"https://www.tenlong.com.tw/products/9787115680044","note":"斯洛伐克 Michal Forišek 与瑞士 Monika Steinová 合著，人民邮电出版社 2025 年 9 月第 1 版，95 页。作者身份是这本书的全部理由：Forišek 是多届 IOI 科学委员会成员、IOI 命题人，并三届担任中欧信息学奥赛（CEOI）主要组织者——他写的不是「怎么解题」，而是「一个概念怎么被讲明白」。全书体例统一：每个主题分「概述—比喻—分析—经验—习题」五段，比喻是核心，用来把算法的结构映射到学生已有的直觉上；第 1 章专门讨论「比喻作为教学工具」的用法与风险（类比在什么环节成立、在什么环节必须撤掉），这在竞赛教材里几乎是空白。正文主题不多但都是硬骨头：图算法的整体框架、树中的最长路径（直径的两遍 DFS/树形 DP，以及「为什么两遍扫是对的」）、带障碍物的最短路（网格/几何障碍下的绕行）、线段之间的距离、环绕数（绕数的计算与用它判定点是否在多边形内、判定两线段是否相交）。对教练的实际用途是拿去改自己的讲义：同一批结论国内教材通常直接给证明与模板，这本书给的是「先给什么样的图、先问什么样的问题才能让学生自己把结论逼出来」，与 ISSEP 2026 论文集里 Hromkovič 的「基因苏格拉底法」是同一路数（见本目录 ISSEP 2026 条目）。局限必须写清：只有 95 页、5 个主题，不构成体系，不能当教材通读；没有一道 OI 真题，也不能替代题解；写作对象是「要上算法课的教师与师范生」，学生自己读会觉得抽象。定位建议：与《算法竞赛核心教程》这类体系书互补——体系书解决「教什么」，这本解决「怎么讲」。","ch":5},{"no":57,"t":"算法竞赛实战笔记","sub":"","kind":"教材","auth":"","pub":"电子工业出版社","year":"2024","lv":["CSP-S","NOIP"],"use":["体系学习","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://cbjj.phei.com.cn/module/goods/wssd_content_comment.jsp?bookid=64333","note":"梁博、李睿琦、娄兰编著，2024 年 1 月第 1 版，ISBN 9787121470127，16 开 244 页、34.1 万字，定价 78 元，中图法 TP301.6。作者梁博 2019 年起负责北大附中初中信息学奥赛教学，书里的题单与讲法直接来自这条教学线，所以体例与常见「知识点罗列型」教材不同：全书以洛谷题号为骨架，讲线性数据结构、基础算法、搜索、动态规划四块的「考场上怎么想到」，每个知识点先摆一道能暴露问题的例题，再从例题里抽方法，最后给同型题单。对已经过了语法关、却卡在「会模板不会选题」的 CSP-S/NOIP 段选手最有用——这个阶段缺的往往不是第五种线段树写法，而是「看到题判断该归到哪一类」的映射关系。定位要说清：它是教学笔记，不是手册，查模板不如《算法竞赛进阶指南》顺手；覆盖止于 DP 与基础数据结构，网络流、字符串、计算几何、数论进阶均未涉及，不能当唯一教材。另外出版于 2024 年初，题面与代码基于当时的洛谷题库，个别题号与难度标签此后有调整，按题号找题时以站内现状为准；配套评测依赖洛谷，无独立题库。","ch":5},{"no":58,"t":"算法竞赛核心教程：策略与算法深度解析","sub":"","kind":"教材","auth":"","pub":"科学出版社（Antti Laaksonen 著，陈锋 译）","year":"2025","lv":["CSP-S","NOIP","省选"],"use":["体系学习","专题突破"],"fx":["深耕","方法论"],"how":"纸质书（335 页，ISBN 9787030816443）","url":"https://www.tenlong.com.tw/products/9787030816443","note":"芬兰赫尔辛基大学 Antti Laaksonen 所著《Guide to Competitive Programming》第 2 版的中文译本，科学出版社 2025 年 3 月出版，335 页，陈锋译。原书是 CSES Problem Set 的官方配套读物，也是目前唯一一本「按 IOI 大纲组织、同时给出完整代码与复杂度分析」的竞赛教材，中文版的落地补上了国内读者长期只能读英文版的缺口。全书 18 章，顺序即学习顺序：编程技巧（递归、位运算）→ 算法效率（复杂度与代码优化）→ 排序与二分 → 数据结构（动态数组、集合结构、实验法测常数）→ 动态规划 → 图论算法（遍历、最短路、DAG、后继图、MST）→ 算法设计专题（位并行、均摊分析、查找最小值）→ 区间查询（稀疏表、线段树、树状数组）→ 树上算法（基本技术、树上查询、高级技术）→ 数学专题（数论、组合、矩阵、概率、博弈、FFT、猜公式）→ 高级图算法（强连通、完整路径、最大流、DFS 树、费用流）→ 计算几何 → 字符串（哈希、Z 算法、后缀数组、自动机）→ 附加主题（根号分治、线段树再探、Treaps、DP 优化、回溯、杂项）→ Python 在竞赛中的应用 → 如何准备 IOI → 算法竞赛的未来（含生成式 AI 一节）。三处别处少见的取舍值得注意：一是每章都给出对应的 CSES 题号，读完立刻有题可做，不必自己找配套；二是专门用一章讲「实验法」——用计时与计数实测常数、判断 O(n log n) 是否真能过，这正是第 23 章反复强调却少有教材落笔的方法论；三是把 Treaps、根号分治、DP 优化这类「只在论坛和博客里流传」的技巧收进了正文，条目化程度高于同类教材。局限：中文版比英文第 2 版晚约一年，个别表述沿用第 1 版的例子；全书篇幅只有 335 页，每个专题都给到「能上手」的深度而非「能打 NOI 压轴」的深度，联赛以上的题目仍需配集训队论文与专题讲义；代码为 C++ 简洁风格，未针对卡常优化。","ch":5},{"no":59,"t":"算法竞赛进阶指南","sub":"","kind":"教材","auth":"李煜东","pub":"河南电子音像出版社","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破","体系学习"],"fx":["深耕"],"how":"纸质书 / 配套代码仓库","url":"","note":"按专题组织，中文圈使用率最高的提高组教材。零基础不建议直接上，学完紫书再来。","ch":5},{"no":60,"t":"算法训练营：进阶篇（全彩版）","sub":"","kind":"教材","auth":"","pub":"电子工业出版社","year":"2025","lv":["CSP-S","NOIP","省选","NOI"],"use":["体系学习","专题突破"],"fx":["深耕","实战"],"how":"纸质书","url":"https://product.dangdang.com/11927255922.html","note":"陈小玉著，2025 年 4 月第 1 版，ISBN 9787121498848，16 开、279 页（部分书目记 288 页），定价 128 元，全彩印刷。它是 2021 年《算法训练营：海量图解+竞赛刷题（进阶篇）》的重绘重编版——图片全部重画配色、内容拆分重组，并新增了可持久化数据结构一章。全书 8 章：①分块算法与跳跃表；②AC 自动机与后缀数组（基数排序、SA 详解、SA 的应用）；③树上操作（树链剖分 + 线段树、点分治、边分治与「重建树」）；④复杂树（KD 树、左偏树、动态树 LCT、树套树）；⑤可持久化（线段树、字典树）；⑥网络流（EK、Dinic、ISAP、二分图匹配、最大流最小割、最小费用最大流）；⑦DP 进阶（背包进阶、树形 DP 进阶）；⑧复杂 DP（数位 DP、插头 DP、斜率优化、四边形不等式优化）。每个知识点后固定跟「训练 1 / 训练 2」两道题，属于「讲一段、写一段」的强绑定结构。差异点要说清：它的取材几乎逐条对上第 27、28、30 章的知识点清单，LCT、树套树、边分治、ISAP 这些在国产教材里常被跳过的项它都有，是少见的「按省选大纲铺满、而不是按作者熟悉度取捨」的进阶书。局限同样明确：279 页塞 8 个大专题，平均每专题 35 页，LCT 只到 access/makeroot/split/link/cut 的基本操作，不含虚子树维护与维护子树信息；树套树给的是线段树套平衡树与线段树套线段树，没有 BIT 套动态开点；可持久化只到线段树与字典树，没有可持久化并查集/平衡树；网络流讲了三种增广算法但没讲当前弧与容量缩放等常数优化。代码风格偏教学，用结构体 + 大量图解，常数不及竞赛模板，抄下来要自己压。定位：CSP-S 冲省选的选手拿它当「考点清单 + 题单」，读完一章立刻在该章两道训练题上验收；教练可取其章节顺序做专题课排程。已有《算法竞赛进阶指南》的读者不必重复购买，两书重叠度高，进阶指南的证明更严、这本的图更直观。","ch":5},{"no":61,"t":"算法设计与分析","sub":"","kind":"教材","auth":"王晓东","pub":"清华大学出版社","year":"2018","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"国内高校通用教材，分治、贪心、DP、回溯的框架清晰，理论作业多。","ch":5},{"no":62,"t":"算法设计与分析：以 ACM 大学生程序设计竞赛在线题库为例（第 2 版·微课版）","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2025","lv":["CSP-S","NOIP","省选"],"use":["体系学习","专题突破"],"fx":["实战","深耕"],"how":"纸质书（ISBN 9787302696490）","url":"https://www.tenlong.com.tw/products/9787302696490","note":"赵端阳著，清华大学出版社 2025 年 8 月第 2 版（第 1 版 2021 年，ISBN 9787302587255），浙江省「十二五」优秀教材、省「十三五」首批新形态教材，作者任大学生程序设计竞赛教练 15 年。体例是「结论 + 模板 + 原题」：11 章按算法策略推进（算法概述与复杂度 → 数据结构与 STL → 递归与分治 → 动态规划 → 贪心 → 回溯 → 分支限界 → 图的搜索 → 图论 → 数论 → 组合数学），每节后面直接挂原题，题源同时取自洛谷（P1182 数列分段、P1908 逆序对、P2016 战略游戏、P1352 没有上司的舞会、P2014 选课等）与 ZOJ/POJ/HDU，等于把「模板—真题」的对应关系写死在书里。真正稀缺的是第 9 章图论的密度：网络流从 Ford-Fulkerson 讲到 EK、ISAP、Dinic 三种实现并各自在同一道题（ZOJ1734 Power Network）上对比，再接到最小费用流（SPFA 增广）；二分图匹配给出匈牙利、Hopcroft-Karp、KM 三套并各配两题——这种「同一问题、三种实现、同一组数据」的排法，正好补上 28.6/28.15/28.16 各节之间的横向对照。第 11 章组合数学把母函数（普通型/指数型）、Stirling 数、Catalan 数、容斥与错排、鸽巢原理收在一章，与 29.3/29.10 呼应。局限：作为教材，某些实现比现行竞赛模板旧（缺当前弧优化的写法、费用流没有势能 Dijkstra 版本），考场直接用需自行加常数优化；分支限界一章偏课程作业取向；第 2 版主要补微课视频与部分例题，核心结构未大改，与第 1 版重合度高，已有旧版不必重买。","ch":5},{"no":63,"t":"算法（第 4 版）","sub":"","kind":"教材","auth":"Robert Sedgewick、Kevin Wayne","pub":"人民邮电出版社","year":"2012","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书","url":"","note":"普林斯顿的算法教材，图与排序讲得极好，配 Coursera 课程。代码是 Java，思路通用。","ch":5},{"no":64,"t":"计算思维训练——动态规划","sub":"","kind":"教材","auth":"","pub":"东南大学出版社","year":"2026","lv":["CSP-S","NOIP"],"use":["专题突破","教练备课"],"fx":["深耕","方法论"],"how":"纸质书","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=4992531","note":"史钋镭等著，2026 年 1 月第 1 版，ISBN 9787576625110，定价 56 元，中图法 TP311.1-49，读者对象标注为青少年，属东南大学出版社面向中学信息学教学的一条产品线。它的组织方式是「按模型切章、按优化收口」，而不是按难度递进：内容提要明确列出线性 DP、状态压缩 DP、区间 DP、树形 DP、背包 DP、数位 DP、插头 DP、计数 DP、动态 DP、概率 DP 十类模型，优化方法则点名线段树、单调队列、斜率优化三种，并对历年 CSP/NOIP 中的 DP 题做了分类归纳，每章配知识点讲解、例题与习题解析。这个组合在同类书里不常见——多数 DP 专题书只覆盖到背包、区间、树形、状压四类，插头 DP、动态 DP、概率 DP 通常散落在集训队论文或博客里，能被编进中学实训教材说明编写组按「考点清单」而非「教学舒适区」选材。选型提醒要写清楚：十类模型压缩在一本 56 元的册子里，单类的篇幅必然有限，插头 DP、动态 DP 这类重题更可能是「给框架 + 一两道例题」而不是完整体系，指望一本书打通动态 DP 的选手仍需配合 OI Wiki 与集训队论文；反过来，它的价值在横向覆盖与真题归类——拿它当「DP 考点地图」，逐章检查自己哪类模型没写过，比从头啃一本 800 页的大部头效率高。适用对象是已能独立写背包与树形 DP、准备把 DP 从「会写模板」推进到「认得模型」的 CSP-S/NOIP 选手；教练也可取其分类框架做专题课的排课依据。","ch":5},{"no":65,"t":"ACM 国际大学生程序设计竞赛系列 · 知识与入门","sub":"","kind":"教材","auth":"俞勇 主编","pub":"上海交通大学出版社","year":"2012","lv":["NOIP","省选"],"use":["体系学习","教练备课"],"fx":["深耕"],"how":"纸质书","url":"","note":"上交 ACM 队教材的第一册，讲题型分类与训练方法。面向 ICPC，但知识结构与省选高度重合。","ch":5},{"no":66,"t":"Algorithms（Dasgupta–Papadimitriou–Vazirani）","sub":"","kind":"教材","auth":"S. Dasgupta, C. Papadimitriou, U. Vazirani","pub":"McGraw-Hill","year":"2006","lv":["NOIP","省选","NOI"],"use":["体系学习"],"fx":["深耕"],"how":"免费（作者授权 PDF）","url":"https://people.eecs.berkeley.edu/~vazirani/algorithms/","note":"薄、狠、准。用 300 页讲完别人 1000 页的内容，适合已有基础后「重构知识框架」。","ch":5},{"no":67,"t":"Algorithms（Jeff Erickson）","sub":"","kind":"教材","auth":"Jeff Erickson","pub":"University of Illinois","year":"2019","lv":["NOIP","省选","NOI","IOI"],"use":["体系学习","专题突破"],"fx":["深耕"],"how":"免费（作者官网 PDF）","url":"https://jeffe.cs.illinois.edu/teaching/algorithms/","note":"目前最好的免费算法教材，证明写得极清楚，习题质量高且带提示。英文过关就该读这一本。","ch":5},{"no":68,"t":"C++，挑战编程——程序设计竞赛进阶训练指南","sub":"","kind":"教材","auth":"邱秋","pub":"人民邮电出版社","year":"2019","lv":["NOIP","省选"],"use":["专题突破","查漏补缺"],"fx":["实战"],"how":"纸质书 / 电子版","url":"","note":"以 C++ 实现为主线的竞赛进阶书，代码风格现代（C++11 起）。适合从「能写」过渡到「写得干净」。","ch":5},{"no":69,"t":"Competitive Programming 4（配套代码库）","sub":"","kind":"教材","auth":"Steven & Felix Halim","pub":"GitHub","year":"2020","lv":["NOIP","省选","NOI"],"use":["查漏补缺","实战训练"],"fx":["速查"],"how":"免费（开源）","url":"https://github.com/stevenhalim/cpbook-code","note":"CP4 全书代码，按章节组织、可直接编译。抄模板前先读一遍它的注释，能少踩很多坑。","ch":5},{"no":70,"t":"Mathematics for Computer Science","sub":"","kind":"教材","auth":"E. Lehman, T. Leighton, A. Meyer","pub":"MIT 6.042J","year":"2018","lv":["NOIP","省选","NOI"],"use":["体系学习"],"fx":["深耕"],"how":"免费（MIT OCW）","url":"https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/","note":"离散数学的完整讲义，证明、计数、概率、图论全覆盖。NOI 级数学短板的系统补法。","ch":5},{"no":71,"t":"Programming Pearls","sub":"","kind":"专著","auth":"Jon Bentley","pub":"Addison-Wesley","year":"1986","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["方法论"],"how":"纸质书","url":"","note":"讲「如何把一个问题想透」。位图、前缀和、二分答案的思想源头都在这本书里，薄但极硬。","ch":5},{"no":72,"t":"算法详解（Algorithms Illuminated，卷 1—4）","sub":"","kind":"教材","auth":"Tim Roughgarden","pub":"Cambridge University Press / 人民邮电出版社（中译）","year":"2017","lv":["NOIP","省选","NOI"],"use":["体系学习"],"fx":["深耕"],"how":"纸质书 / 部分章节公开","url":"https://www.algorithmsilluminated.org/","note":"四卷本：基础、图算法、贪心与 DP、NP 完全性。作者是算法课名师，讲直觉不堆公式，配 Coursera 课程。","ch":5},{"no":73,"t":"编程珠玑","sub":"第 2 版","kind":"专著","auth":"Jon Bentley","pub":"人民邮电出版社","year":"2008","lv":["NOIP","省选"],"use":["专题突破"],"fx":["方法论"],"how":"纸质书","url":"","note":"讲的不是算法而是「怎么想问题」。位图排序、二分查找的边界处理，至今仍是好教材。","ch":5},{"no":74,"t":"ACM 国际大学生程序设计竞赛系列 · 算法与实现","sub":"","kind":"教材","auth":"俞勇 主编","pub":"上海交通大学出版社","year":"2012","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"第二册讲实现：数据结构、图论、计算几何的代码级细节。适合「知道思路但写不出来」的阶段。","ch":5},{"no":75,"t":"Algorithm Design（Kleinberg–Tardos）","sub":"","kind":"教材","auth":"Jon Kleinberg, Éva Tardos","pub":"Addison-Wesley","year":"2005","lv":["省选","NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"纸质书 / 课件公开","url":"https://www.cs.princeton.edu/~wayne/kleinberg-tardos/","note":"讲「怎么想出算法」而不是「算法是什么」。贪心与网络流的正确性证明讲得最深，写论文前必读。","ch":5},{"no":76,"t":"Competitive Programming 4","sub":"红皮书","kind":"教材","auth":"Steven Halim、Felix Halim","pub":"自出版","year":"2020","lv":["省选","NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕","实战"],"how":"纸质 / 官网","url":"https://cpbook.net/","note":"收录近千道真题、配 UVA 题号，国际化训练的标准参考。上下两册，重得像砖头。","ch":5},{"no":77,"t":"Introduction to Graph Theory（West）","sub":"","kind":"教材","auth":"Douglas B. West","pub":"Prentice Hall","year":"2000","lv":["省选","NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"图论标准教材，习题极多且有难度分级。想系统补图论（匹配、连通度、着色）用它。","ch":5},{"no":78,"t":"Introduction to Probability","sub":"","kind":"教材","auth":"D. Bertsekas, J. Tsitsiklis","pub":"Athena Scientific","year":"2008","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书 / MIT 课件","url":"https://ocw.mit.edu/courses/6-041-probabilistic-systems-analysis-and-applied-probability-fall-2010/","note":"概率论入门，例子偏工程但推导完整。期望 DP、随机化算法的理论基础在这里。","ch":5},{"no":79,"t":"The Algorithm Design Manual","sub":"","kind":"教材","auth":"Steven Skiena","pub":"Springer","year":"1997","lv":["省选","NOI","IOI"],"use":["专题突破","查漏补缺"],"fx":["深耕"],"how":"纸质书 / 部分章节公开","url":"https://www.algorist.com/","note":"后半本「问题目录」按场景索引算法，是全书写法里最实用的一本。卡在「这题该用什么」时翻它。","ch":5},{"no":80,"t":"信息学竞赛中的数学","sub":"","kind":"教材","auth":"多位竞赛教练合著","pub":"各出版社","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书 / 讲义","url":"","note":"同类书较多，选择时优先看是否配有真题，纯数学教材容易与考点脱节。","ch":5},{"no":81,"t":"具体数学","sub":"计算机科学基础（第 2 版）","kind":"专著","auth":"Graham、Knuth、Patashnik","pub":"人民邮电出版社","year":"2013","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"数论与组合的补课神器。求和技巧、递推、生成函数几章直接对应竞赛考点。","ch":5},{"no":82,"t":"挑战程序设计竞赛 2","sub":"算法与数据结构","kind":"教材","auth":"渡部正树 等","pub":"人民邮电出版社","year":"2016","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"续卷偏数据结构与复杂算法，难度陡增，是省选阶段的推土机。","ch":5},{"no":83,"t":"数据结构与算法（上下册）","sub":"","kind":"教材","auth":"","pub":"清华大学出版社","year":"2026","lv":["省选","NOI"],"use":["体系学习","教练备课"],"fx":["深耕"],"how":"纸质书（上下册，定价 99 元）","url":"https://www.tup.tsinghua.edu.cn/booksCenter/book_11860701.html","note":"邓俊辉编著，2026 年 10 月第 1 版（10 月 13 日付印），ISBN 9787302729150，定价 99 元，清华大学计算机系列教材。全书 14 章分上下两册：上册 6 章为算法概论、向量、列表、栈与队列、二叉树、二叉搜索树；下册 8 章为搜索树应用、高级搜索树、词典、图基础、图进阶、优先级队列、字符串、排序。作者在清华讲授算法类课程三十年，其中「数据结构」是清华首批标杆课程，配套慕课「数据结构」与「计算几何」累计有 160 多个国家和地区的 100 余万人选修。对竞赛选手的价值不在「多学一个算法」，而在补上竞赛教材普遍跳过的那一层：为什么这样设计、摊还代价怎么算、接口与实现的取舍在哪里——向量扩容的均摊分析、二叉搜索树的旋转不变式、优先级队列的合并代价，这些正是读懂左偏树、可持久化结构与树套树时缺的那块地基。定位要说清：它不是竞赛书，没有 OI 真题，代码是 C++ 模板类而不是竞赛式的数组模拟，直接抄不能当模板背；正确用法是当「工具书 + 证明册」，在学完一章竞赛内容后回来看对应章节的设计动机与复杂度证明。上册偏基础（CSP-S 段可读），下册的高级搜索树、图进阶、字符串才是省选以上真正有用的部分。局限：两册 99 元、篇幅大，通读成本高；不含竞赛评测环境与题目数据，与 NOIP/NOI 大纲不对齐，不能替代按大纲的复习。","ch":5},{"no":84,"t":"离散数学及其应用","sub":"第 8 版","kind":"专著","auth":"Kenneth H. Rosen","pub":"机械工业出版社","year":"2019","lv":["省选","NOI"],"use":["查漏补缺"],"fx":["深耕"],"how":"纸质书","url":"","note":"图论、逻辑、计数、关系四大块与竞赛重叠度高，当工具书按需查。","ch":5},{"no":85,"t":"算法导论","sub":"CLRS 第 3 版","kind":"专著","auth":"Cormen、Leiserson、Rivest、Stein","pub":"机械工业出版社","year":"2012","lv":["省选","NOI","IOI"],"use":["查漏补缺"],"fx":["深耕"],"how":"纸质书","url":"","note":"理论圣经，但不是竞赛书。只在某个算法「知其然不知其所以然」时按章查阅，别通读。","ch":5},{"no":86,"t":"算法导论（扩展篇）（原书第 4 版）","sub":"","kind":"教材","auth":"","pub":"机械工业出版社","year":"2026","lv":["省选","NOI"],"use":["查漏补缺","体系学习"],"fx":["深耕"],"how":"纸质书（定价 99 元，331 页）","url":"http://www.cmpedu.com/books/book/5610909.htm","note":"科尔曼、雷瑟尔森、李维斯特、斯坦著，王刚、苏明译，2026 年 5 月 29 日第 1 版，ISBN 978-7-111-80012-5，定价 99 元，561 千字，331 页，计算机科学丛书。第 4 版中译本拆成两册，已入库的《核心篇》是第 1—25 章，本册是第 26—35 章：并行算法（fork-join、并行矩阵乘法、并行归并排序）、在线算法（等待电梯、维护搜索链表、确定性/随机化缓存）、矩阵运算（解线性方程组、矩阵求逆、对称正定与最小二乘）、线性规划（形式化与对偶性）、多项式与离散傅里叶变换（DFT/FFT）、数论算法（gcd、模运算、模线性方程、中国剩余定理、元素幂、RSA、素性测试）、字符串匹配（朴素、Rabin-Karp、有限自动机、KMP、后缀数组）、机器学习算法（聚类、乘法权重、梯度下降）、NP 完全性（含团、顶点覆盖、哈密顿回路、TSP、子集和六个经典归约）、近似算法（顶点覆盖、TSP、集合覆盖、随机化与线性规划、子集和）。附录 A—D 为求和、离散数学、计数与概率、矩阵。对竞赛的直接价值集中在三章：第 30 章是 NTT 的数学来源（单位根、DFT 的矩阵形式、FFT 分治结构），第 31 章把 exgcd、CRT、Miller-Rabin 的证明一次讲透，第 32 章给 KMP 与后缀数组的严格正确性论证——这些正是抄模板时最容易含糊过去的部分。第 26、27、33、35 章超出 NOI 大纲，属视野内容，不必精读。局限：全书伪代码（无 C++ 实现），无习题答案，不能当模板书用；与《核心篇》合计 238 元、篇幅近千页，通读成本高，正确用法是当「证明册」按需查证，而不是从头读到尾。","ch":5},{"no":87,"t":"算法竞赛中的数论","sub":"","kind":"教材","auth":"多位竞赛教练","pub":"各出版社 / 讲义","year":"2019","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质 / 讲义","url":"","note":"同主题书较多，选书标准只有一个：是否配真题。纯数学教材容易与考点脱节。","ch":5},{"no":88,"t":"算法艺术与信息学竞赛","sub":"","kind":"教材","auth":"刘汝佳、黄亮","pub":"清华大学出版社","year":"2004","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书 / 二手","url":"","note":"上一代竞赛生的「红宝书」。内容偏老，但建模思路与经典套路至今不过时。","ch":5},{"no":89,"t":"算法设计手册","sub":"The Algorithm Design Manual","kind":"教材","auth":"Steven S. Skiena","pub":"Springer","year":"2020","lv":["省选","NOI"],"use":["查漏补缺"],"fx":["速查","方法论"],"how":"纸质 / 电子书","url":"","note":"后半本是「问题 → 算法」的检索目录，卡题时翻它比搜网页快。","ch":5},{"no":90,"t":"组合数学","sub":"第 5 版","kind":"专著","auth":"Richard A. Brualdi","pub":"机械工业出版社","year":"2012","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"计数问题的标准教材，容斥、Polya、递推关系讲得比竞赛书系统。","ch":5},{"no":91,"t":"Graph Theory（Bondy & Murty）","sub":"","kind":"教材","auth":"J. A. Bondy, U. S. R. Murty","pub":"Springer GTM 244","year":"2008","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费（作者授权 PDF）","url":"https://www.zib.de/groetschel/teaching/WS1314/BondyMurtyGTWA.pdf","note":"研究生级图论，证明严谨。做图论方向论文（集训队论文）时的标准参考。","ch":5},{"no":92,"t":"Handbook of Data Structures and Applications（2nd Edition）","sub":"","kind":"专著","auth":"Dinesh P. Mehta, Sartaj Sahni 等","pub":"Chapman & Hall/CRC","year":"2018","lv":["NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"纸质书 / 图书馆","url":"","note":"数据结构的工具书级手册，覆盖范围远超竞赛需要。写集训队论文找「已知最优复杂度」时的权威出处。","ch":5},{"no":93,"t":"Linear Algebra Done Right","sub":"","kind":"教材","auth":"Sheldon Axler","pub":"Springer","year":"2015","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费（作者官网）","url":"https://linear.axler.net/","note":"不靠行列式讲线性代数，直接讲算子与结构。理解矩阵加速、线性基、高斯消元的本质靠它。","ch":5},{"no":94,"t":"Structure and Interpretation of Computer Programs","sub":"","kind":"教材","auth":"H. Abelson, G. Sussman","pub":"MIT Press","year":"1985","lv":["NOI","IOI"],"use":["体系学习"],"fx":["深耕"],"how":"免费（在线全文）","url":"https://mitpress.mit.edu/sites/default/files/sicp/full-text/book/book.html","note":"讲抽象与递归的本质。不直接提分，但会改变你写代码和拆问题的姿势，很多金牌选手的共同读物。","ch":5},{"no":95,"t":"概率论与数理统计","sub":"","kind":"专著","auth":"盛骤 等","pub":"高等教育出版社","year":"2019","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"应对期望、方差、条件概率类考点。只需前四章，配合竞赛题练习即可。","ch":5},{"no":96,"t":"线性代数及其应用","sub":"","kind":"专著","auth":"David C. Lay","pub":"机械工业出版社","year":"2018","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"2025 大纲在 NOI 级新增「基与线性基」，这本是补齐矩阵与线性空间直觉的最短路径。","ch":5},{"no":97,"t":"编程原本","sub":"","kind":"专著","auth":"Alexander Stepanov、Paul McJones","pub":"机械工业出版社","year":"2012","lv":["NOI"],"use":["查漏补缺"],"fx":["方法论"],"how":"纸质书","url":"","note":"从数学结构角度讲算法为何成立。读不下去很正常，读懂一章就够用很久。","ch":5},{"no":98,"t":"计算几何：算法与应用","sub":"第 3 版","kind":"专著","auth":"Mark de Berg 等","pub":"清华大学出版社","year":"2018","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"纸质书","url":"","note":"计算几何唯一系统的中文译著。竞赛只需前几章：凸包、半平面交、最近点对。","ch":5},{"no":99,"t":"ACM Transactions on Algorithms（TALG）","sub":"","kind":"专著","auth":"ACM","pub":"ACM","year":"2005","lv":["IOI"],"use":["专题突破"],"fx":["深耕"],"how":"付费（学校可订阅）","url":"https://dl.acm.org/journal/talg","note":"理论算法最高级别期刊之一。集训队论文若要引用「已知最优复杂度」，这里是权威出处。","ch":5},{"no":100,"t":"Algorithmica","sub":"","kind":"专著","auth":"Springer","pub":"Springer","year":"1986","lv":["IOI"],"use":["专题突破"],"fx":["深耕"],"how":"付费（学校可订阅）","url":"https://link.springer.com/journal/453","note":"算法领域顶级期刊之一，偏理论与应用结合。写论文找参考文献的起点。","ch":5},{"no":101,"t":"Journal of Graph Algorithms and Applications（JGAA）","sub":"","kind":"专著","auth":"Brown University","pub":"jgaa.info","year":"1997","lv":["IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费（开放获取）","url":"https://jgaa.info/","note":"图算法开放期刊，可免费下载全文。图论方向论文的高质量参考源。","ch":5},{"no":102,"t":"计算机程序设计艺术","sub":"TAOCP","kind":"专著","auth":"Donald E. Knuth","pub":"国防工业出版社","year":"2002","lv":["IOI"],"use":["查漏补缺"],"fx":["深耕"],"how":"纸质书","url":"","note":"不是给选手读的，是给「想知道所有细节的人」读的。当作查询手册，别当教材。","ch":5},{"no":103,"t":"CCF NOI 系列活动考场纪律","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn","year":"2025","lv":["通用"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/gynoi/tlgd/2025-09-01/848189.shtml","note":"哪些行为算作弊、代码雷同如何判定。每年都有选手因不了解规则被取消成绩。","ch":6},{"no":104,"t":"NOI 大纲（2025 年修订版）","sub":"","kind":"官方","auth":"CCF NOI 科学委员会","pub":"中国计算机学会","year":"2025","lv":["通用"],"use":["教练备课","查漏补缺","体系学习"],"fx":["速查","方法论"],"how":"官网免费 PDF","url":"https://www.noi.cn/upload/resources/file/2025/04/18/NOI_Syllabus_Edition_2025.pdf","note":"全书的骨架。1–10 级共数百个知识点逐条标注级别，任何资料都可以挂到这套编号上。","ch":6},{"no":105,"t":"NOI 官网","sub":"","kind":"官方","auth":"中国计算机学会","pub":"noi.cn","year":"1995","lv":["通用"],"use":["教练备课","查漏补缺"],"fx":["速查","方法论"],"how":"免费","url":"https://www.noi.cn/","note":"大纲、赛历、规则、获奖名单、题目分析报告的唯一权威来源。所有二手信息都要回到这里核对。","ch":6},{"no":106,"t":"NOI 系列活动和认证日历","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn","year":"2026","lv":["通用"],"use":["教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-02-12/861384.shtml","note":"2026 年 2 月 12 日发布的全年赛历，正文只有一句「以上活动时间安排如有调整和补充，请以具体通知为准」，全年安排以图片形式给出；结合各单项通知可还原为：CSP-J/S 第一轮 9 月 19 日、第二轮 10 月 31 日，NOIP 11 月 28 日 8:30—13:00，NOI 2027 联合省选 2027 年 3 月 6—7 日，冬令营 2 月、APIO 5 月、NOI 7 月、IOI 8 月，女生竞赛与教师培训穿插其间。对教练的用法是按表倒排训练节奏：CSP 两轮之间只有六周、第二轮结束到 NOIP 只有四周，秋季学期实际上是一段连续冲刺，暑假结束前必须把大纲主干讲完。局限：日历本身是图片，具体日期一律以单项通知为准（集训营报到、各省报名截止都另有规定），且部分活动标注「待定」，年中会调整。","ch":6},{"no":107,"t":"《中国计算机学会通讯》（CCCF）","sub":"","kind":"官方","auth":"中国计算机学会","pub":"CCF","year":"2005","lv":["通用"],"use":["教练备课"],"fx":["方法论"],"how":"会员赠阅 / 官网部分公开","url":"https://www.ccf.org.cn/","note":"CCF 会刊，常刊发 NOI 工作总结、命题思路、拔尖人才培养讨论。教练写方案时的政策依据来源。","ch":6},{"no":108,"t":"《信息学奥林匹克竞赛年鉴》","sub":"","kind":"官方","auth":"中国计算机学会","pub":"CCF","year":"2010","lv":["通用"],"use":["教练备课"],"fx":["方法论"],"how":"纸质 / 内部资料","url":"https://www.noi.cn/","note":"各省参赛与获奖数据、优秀组织经验。做学校竞赛规划时用来对标同层次学校的成绩。","ch":6},{"no":109,"t":"2024 年 NOI 活动题目分析报告（CSP-J/S 2024 第二轮 + NOIP 2024 知识构成）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2025","lv":["CSP-J","CSP-S","NOIP"],"use":["查漏补缺","教练备课"],"fx":["方法论","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2025-06-16/844463.shtml","note":"2025 年 6 月 16 日发布，含三份独立 PDF：CSP-J/S 2024 第二轮入门级、CSP-J/S 2024 第二轮提高级、NOIP 2024 的「题目知识构成分析报告」，NOI 官网在线预览可直接打开。执笔人为 NOI 科学委员会团队：入门级桂欣、胡冬明、胡昌腾、叶金毅、杨耀良、任舍予、赵启阳、韩文弢；提高级张炜其、汪星明、杨耀良、任舍予、赵启阳、韩文弢；NOIP 李建、杨耀良、任舍予、赵启阳、韩文弢。与市面上逐题题解不同，这套报告按《NOI 大纲》的知识点给每道题做归类与难度标定，因此能回答「一场比赛真正考了哪几个板块、各占多少分」这类统计问题，而这正是教练排训练计划时最缺的数据——把三届报告叠起来看，就能发现某板块（例如 DP 优化、树上问题）的复现频率，从而决定课时配比。用法建议：先读提高级一份建立框架，再用入门级校准低年级段，NOIP 一份用于衔接省选。局限：只覆盖 2024 赛季，2025 年同类报告见既有条目；报告是赛后复盘性质，不含代码与实现细节，配题解使用。","ch":6},{"no":110,"t":"2026 年 WCET & LMCC & NOI 教师发展活动日历","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2026","lv":["CSP-J","NOIP"],"use":["教练备课"],"fx":["速查"],"how":"免费（官网公告）","url":"https://www.noi.cn/jspx/2026-03-10/861585.shtml","note":"2026 年 3 月 10 日发布，一张全年教师发展活动的排期表，分两块。WCET（计算机教育领域）名师论坛六场：3 月丽江上海新纪元学校、5 月新疆、8 月西安市铁一中学（年度研讨会）、9 月北京市第八十中学、11 月澳门、12 月广西。教师培训六场：1 月上海外国语大学附属外国语学校（LMCC）、5 月北京市第八十中学与佛山市南海区石门中学、9 月浙江、11 月江苏、广东待定。对教练的实际用途有二：一是按月份规划自己的进修与参赛带队节奏，避免与本校教学冲突；二是有意承办的学校可据此提前一年接触特派员——承办校名单是公开的，说明这条路是常态化开放的。局限必须说清：只有时间、名称与承办单位，没有课程主题、学时、报名条件与名额；「待定」一栏说明排期本身会调整，实际以每次单独通知为准（例如 12 月南京站的第四期培训就不在这张表内，是后补的）。","ch":6},{"no":111,"t":"CCF CSP 认证官方说明","sub":"","kind":"官方","auth":"CCF","pub":"cspro.org","year":"2014","lv":["CSP-J","CSP-S"],"use":["教练备课","赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://cspro.org/","note":"CSP 软件能力认证（与 CSP-J/S 不同）的官方规则。若学校需要第三方能力证明，这是正规渠道。","ch":6},{"no":112,"t":"CCF CSP 认证官网","sub":"","kind":"官方","auth":"中国计算机学会","pub":"cspro.org","year":"2019","lv":["CSP-J","CSP-S"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.cspro.org/","note":"报名、准考证、成绩查询入口。别在非官方渠道报名。","ch":6},{"no":113,"t":"CCF NOI 教师培训考核管理规则","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2026","lv":["CSP-J","NOIP","NOI"],"use":["教练备课"],"fx":["速查"],"how":"免费（官网公告）","url":"https://www.noi.cn/jspx/2026-07-13/917355.shtml","note":"2026 年 7 月 13 日发布。这份公告把 NOI 教师培训与资质认定从「通知式」变成了「制度式」，给出三件对教练直接有用的事。①分级口径：培训与考核一级一档，初级对应大纲难度系数 1~5、中级 1~7、高级 1~9——换句话说，初级证书的实际覆盖面只到 CSP-S 中段，想覆盖省选就得考中级，覆盖 NOI 要考高级。②考核形式：各级 4 小时 4 题、满分 400 分，优秀（≥300）与合格（≥150）分档发证，低于 150 不发证；证书有效期三年。③权益：有效期内每年可推荐学生获得 NOIP 名额，优秀档为初级 2、中级 3、高级 5 人，合格档为 1、2、4 人。这一条最有信息量——它把「指导教师推荐」从口头承诺变成可计算的配额，带班规模较大的教练应按学生数反推该考到哪一级。公告同时明确考核命题、评测数据、评测环境与成绩复核由 NOI 科学委员会负责，并声明本公告是对《CCF 中小学计算机教师能力认定暨实施办法》的条款补充，冲突时以本公告为准。局限：只讲认定与配额，不讲培训课程内容与通过率；三年有效期意味着证书需要周期性复检，规则未说明复检是否免考，实际执行以当年通知为准。","ch":6},{"no":114,"t":"CCF 信息学奥赛入门篇","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（组编）","year":"2025","lv":["CSP-J"],"use":["入门自修","体系学习"],"fx":["方法论"],"how":"纸质书","url":"https://www.noi.cn/cbw/2025-04-07/841091.shtml","note":"朱全民主编，CCF 组编，2025 年 4 月正式出版。立足 NOI 竞赛大纲逐条对应知识点，官方定位为 4—7 年级学生的入门读物。价值在于「大纲对齐」：读它不是为了学完，而是为了知道大纲的每一级在小学段该落到什么程度，可与《CCF 全国青少年信息学奥林匹克竞赛教程》配套使用。","ch":6},{"no":115,"t":"CCF 关于 CSP-J/S 2026 第一轮晋级第二轮的规定","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-24/934543.shtml","note":"2026 年 9 月 24 日发布。明确第一轮晋级第二轮的分数线划定方式与名额比例，含各省差异化条款。每年都有选手误判「过线即晋级」，这份文件是唯一权威口径，报名前应直接读原文而非二手解读。","ch":6},{"no":116,"t":"CCF 关于 CSP-J/S 2026 第一轮认证评级分数线的公告","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-10/938437.shtml","note":"2026 年 10 月 10 日发布。入门组全国一级 69.5、二级 55.5、三级 42；提高组一级 66.5、二级 52.5、三级 39（满分 100，第一轮为笔试）。公告明确这是全国统一线，各省认证组织单位不得再按本省情况调整——这一点与 NOIP 的省线机制完全不同，是很多家长判断失误的根源。三个用法：一是赛后定位，用自己第一轮得分直接对档；二是教练做校内模拟卷时，可把「达到本省一级线」作为及格基准反推训练强度；三是纠正表述，CSP 只有一级/二级/三级，没有「一等奖」，且它与 NOIP 评奖体系无关，写简历、填报名表时不能混用。注意这是第一轮（笔试）线，与第二轮机试成绩、与省选资格门槛都不是一回事。","ch":6},{"no":117,"t":"CCF 关于 NOI 相关权益的声明","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2020","lv":["CSP-J","CSP-S","NOIP","NOI"],"use":["教练备课","查漏补缺"],"fx":["速查"],"how":"免费（官网公告）","url":"https://www.noi.cn/xw/2020-06-23/715566.shtml","note":"2020 年 6 月 23 日发布，CCF 官网首页长期置顶。这份声明的价值在于它把「谁有权代表 NOI」写成了可核对的条文，共五条：① NOI 的对外宣传平台只有三个——CCF 官网 ccf.org.cn、NOI 官网 noi.cn、微信公众号 ccfvoice，其他渠道转载 NOI 新闻须经 NOI 竞赛办公室书面同意；② CCF 从未授权任何机构承办面向青少年的 NOI 系列赛前培训，今后也不会授权任何「赛前培训班」；③「CCF NOI」与「NOIP」是 CCF 注册商标，凡以 CCF 名义举办的 NOI 相关活动必有书面授权书，拿不出授权书而自称承办方的即属侵权；④ noi.cn 上的「NOI Online 培训」视频仅支持在线观看，版权归 CCF，不得下载转载；⑤ 对冒用「NOI」「信息学官方」「NOIP 官方」等名义虚假宣传的，已交法律顾问处理。对教练与家长的直接用法：遇到机构自称「NOI 官方合作机构」「NOIP 考前培训班」，按第②③条即可判定为虚假宣传，可直接向 noi@ccf.org.cn 或 010-62562503 投诉；学校在校内组织培训不受影响，受限的是「以官方名义」与「校外有偿兼职」两类行为（后者另见《关于重申在校在职 NOI 指导教师不得校外有偿兼职授课的公告》）。局限：发布于 2020 年，文中提到的「NOI Online 培训」栏目此后已并入 noi.cn 的资料下载与活动视频栏目，条款本身仍然有效，但具体栏目名称要按现行站点理解；声明只讲权益归属，不含处罚细则与认定程序。","ch":6},{"no":118,"t":"CSP-J/S 2026 第一轮认证证书申请通知","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-16/940603.shtml","note":"2026 年 10 月 16 日发布，受理窗口 10 月 17 日—11 月 20 日，逾期本年度不再受理且不补办——这是全流程里唯一「过期作废」的硬截止，教练应在 10 月中旬就提醒全队。要点：电子证书免费、窗口内可多次下载，逾期连电子版也不再开放；纸质证书 100 元/张（含工本、人工、快递），预计 12 月 16 日后寄出；两者可同时取得，报名表、简历、综评材料用电子版即可，不必付费。资格线沿用第一轮评级：入门组一级 69.5、二级 55.5、三级 42，提高组 66.5/52.5/39，未达任一等级者系统中没有下载按钮。操作细节最容易翻车：必须先在【用户信息】里填完整邮寄地址，再去活动页提交纸质申请并缴费；仅限电脑端、仅限支付宝，手机或微信内置浏览器打开会失败且费用不退；第一轮电子证书无证书编号（页面显示「暂无」属正常）；下载弹窗要等约半分钟，中途关掉会得到残缺文件。","ch":6},{"no":119,"t":"CSP-J/S 2026 第二轮报名通知","sub":"","kind":"官方","auth":"中国计算机学会","pub":"noi.cn","year":"2026","lv":["CSP-J","CSP-S"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-29/933744.shtml","note":"2026 年 10 月 31 日认证：入门组 8:30—12:00（3.5 小时），提高组 14:30—18:30（4 小时）。第二轮由各省负责人统一报名，选手只需在规定时间内缴费确认。","ch":6},{"no":120,"t":"CSP-J/S 认证须知","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn","year":"2025","lv":["CSP-J","CSP-S"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/gynoi/tlgd/2019-09-30/710460.shtml","note":"报名条件、赛制、评测方式、违规处理。考前必读，每年都有细节调整。","ch":6},{"no":121,"t":"NOI Linux 2.0 官方发布页","sub":"","kind":"官方","auth":"NOI 科学委员会","pub":"noi.cn","year":"2021","lv":["CSP-J","CSP-S","NOIP","省选","NOI"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费（镜像约 3.4 GB）","url":"https://www.noi.cn/gynoi/jsgz/2021-07-16/732450.shtml","note":"自 2021 年 9 月 1 日起的官方标准环境，基于 Ubuntu 20.04.1 定制。页面附系统情况简表（内核、编译器、IDE 版本）与镜像下载地址，是「考场到底用什么」的唯一权威来源。","ch":6},{"no":122,"t":"USACO 官网","sub":"","kind":"官方","auth":"USACO","pub":"usaco.org","year":"1992","lv":["CSP-J","CSP-S","NOIP"],"use":["实战训练","体系学习"],"fx":["实战"],"how":"免费","url":"https://usaco.org/","note":"四级赛制（铜/银/金/白金），每年四次月赛。题目公开、题解公开，训练价值极高。","ch":6},{"no":123,"t":"关于 CCF CSP-J/S 认证等级名称规范的公告","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-J","CSP-S"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-09/930554.shtml","note":"2026 年 9 月 9 日公告，规范的是对外表述口径：CSP-J/S 是面向非专业人士的算法与编程能力评价活动，不属于竞赛评奖，不设一、二、三等奖，只按成绩由高到低评一级、二级、三级；把「一级」写成「一等奖」属对认证规则的错误解读，机构与学校对外必须统一用「一级、二级、三级」。这条看似只是措辞，实际卡两处：一是证书、简历、报名表上的写法，二是各类「省一/省二」经验贴与选拔条款的对应关系——多省省选资格写的是「NOIP 一等奖」，那属于 NOIP 评奖体系，与 CSP 的等级不是同一套。读旧资料时必须先分清文中说的是 CSP 等级还是 NOIP 奖项，否则会把准入条件看错一档。","ch":6},{"no":124,"t":"关于 NOI 系列活动中编程语言使用限制的补充说明","sub":"","kind":"官方","auth":"","pub":"CCF NOI 科学委员会（NOI 官网）","year":"2021","lv":["CSP-J","CSP-S","NOIP","NOI"],"use":["查漏补缺","赛前冲刺"],"fx":["速查"],"how":"免费（官网公告，五条正文）","url":"https://www.noi.cn/gynoi/tlgd/2021-09-11/836159.shtml","note":"2021 年 9 月 1 日由 CCF NOI 科学委员会发布，是针对《关于 NOI 系列赛编程语言使用限制的规定》编程通则的补充，适用范围覆盖 CSP-J/S 在内的全部 NOI 系列活动。五条内容：① 除题面有明确要求外，C++ 程序编译默认采用 C++14 标准；② 除题面明确要求并允许，禁止在源代码中自行指定任何编译选项——所有 pragma、attribute、内联汇编式的编译指示都属于此类；③ 允许使用以下划线开头的库函数或宏，但编程通则中明确禁止的除外；④ 已发布的技术类规则若与本说明冲突，冲突部分以本说明为准；⑤ 其余未尽事项按现有规则执行。末段是硬约束：使用明确禁止的内容者，源代码直接判零分，且不接受申诉。对选手的直接意义有两条：一是本地为了卡常惯用的 #pragma GCC optimize、__attribute__((optimize(\"O3\"))) 必须在提交前删净，很多「本地 1.2 秒、评测 0 分」的事故都出在这里；二是默认 C++14 意味着 std::gcd、结构化绑定、if constexpr 这类 C++17 特性在未注明语言版本的题上不可用，跨平台编译前先在 NOI Linux 2.0 上用 -std=c++14 过一遍。局限：正文只有五条，是补充而非全集，完整的禁用清单要去编程通则原文核对；发布于 2021 年，此后 NOI Linux 2.0 已迭代过编译器版本，具体 g++ 小版本以当年竞赛环境说明为准。","ch":6},{"no":125,"t":"关于参加 CSP-J/S 认证需符合年龄条件的公告（12 周岁门槛）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2025","lv":["CSP-J","CSP-S","NOIP"],"use":["教练备课","查漏补缺"],"fx":["速查"],"how":"免费（官网公告）","url":"https://www.noi.cn/gynoi/tlgd/2025-02-13/837978.shtml","note":"2025 年 2 月 13 日发布并即时生效。核心条款只有一句：报名参加 CSP-J/S 的被认证者，在当年 9 月 1 日（不含）须满 12 周岁，第一轮与第二轮一并适用，「参加 NOI 相关竞赛的规则同此」。也就是说，不满 12 周岁不得报名 CSP-J/S 与 NOIP 等 NOI 系列活动，判定基准是<b>当年 9 月 1 日</b>，不是报名日、也不是考试日——这一点对安排低龄学生参赛的教练最要紧：一个 11 月出生的孩子，要等到满 12 周岁之后的那个赛季才能报名，此前整年只能用非 CCF 题库自练。公告给出的理由有三层，且都值得原样转述给家长：一是小学生过早参加 CSP-J/S 对其身心健康与正常学习有负面影响，不符合认证初衷；二是部分中学把小学生的 CSP-J/S 成绩当作升学参考依据，会带来严重的功利化倾向，影响正常教学与升学秩序；三是官方明确表态「学习计算机科学有益，但需要基础与认知能力，并非越早越好」。实用含义有二：青训班的分层要按「当年 9 月 1 日是否满 12 周岁」切，而不是按年级；CCF 体系内另一条线 GESP（8 级制）没有这条年龄限制，是 12 岁以下唯一能参加的 CCF 认证，衔接路径应改为 GESP → CSP-J/S。局限：公告未写过渡期、未说明既往成绩如何处理，也未界定跨年赛季（例如 9 月 1 日前后同一场认证）的执行口径；条文极简，具体核验方式以各省特派员当年通知为准。","ch":6},{"no":126,"t":"关于重申在校在职 NOI 指导教师不得校外有偿兼职授课的公告","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2025","lv":["CSP-J","CSP-S","NOIP","NOI"],"use":["教练备课"],"fx":["速查"],"how":"免费（官网公告）","url":"https://www.noi.cn/gynoi/tlgd/2025-02-13/837982.shtml","note":"2025 年 2 月 13 日发布。全文只有三段，但把「教练合规」的边界划清了：所有参与 NOI 活动的在校在职教师必须遵守教育部相关规定，不得在校外培训机构有偿兼职授课；CCF 将强化对在校在职 NOI 教师的监督管理，对违反者按情节轻重采取警告、取消 NOI 参与资格、通报所在单位及教育主管部门等措施。触发点是官方点名的两类行为——在校外机构参与有偿培训，以及利用校内职务之便进行不当宣传牟利。对学校教练的实际约束可以拆成三条：不能以个人身份到机构挂名带班（哪怕不讲课，挂名即属「利用职务之便宣传」）；不能把校内学生成建制带到机构上课；校外机构以「某校教练」名义招生时，教师本人有澄清义务。与《CCF NOI 教师培训考核管理规则》配合看更清楚：CCF 一边用三级证书与 NOIP 推荐名额做正向激励，一边用这条公告做负向约束，等于把「校内教师」与「机构讲师」的身份边界制度化了。局限：未定义「有偿」的认定口径（课时费、股权、分成是否都算），未给出申诉与复核程序，也未说明处理结果是否公示；实践中的争议点常落在「公益讲座」与「有偿授课」之间，公告没有给判据。","ch":6},{"no":127,"t":"电子学会青少年等级考试","sub":"","kind":"官方","auth":"中国电子学会","pub":"qceit.org.cn","year":"2016","lv":["CSP-J"],"use":["入门自修"],"fx":["速查"],"how":"报名费","url":"https://www.qceit.org.cn/","note":"科普性质的等级认证，与 NOI 体系不互通。仅适合作为兴趣启蒙的阶段性检验。","ch":6},{"no":128,"t":"蓝桥杯","sub":"","kind":"官方","auth":"工信部人才交流中心","pub":"lanqiao.cn","year":"2010","lv":["CSP-J"],"use":["入门自修"],"fx":["实战"],"how":"报名费","url":"https://www.lanqiao.cn/","note":"难度低于 CSP-J，题型偏应用。可作为低龄选手的第一场比赛，但不宜当作 OI 主线。","ch":6},{"no":129,"t":"2025 年 CSP-J/S 第二轮认证题目分析报告","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2025","lv":["CSP-S","CSP-J"],"use":["教练备课","查漏补缺"],"fx":["方法论"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2025-11-12/852998.shtml","note":"2025 年 11 月 12 日发布。官方对第二轮四道题逐题给出考点分布、得分率与典型错误，是判断「本年难度是否上移」的基准材料。备课时可据此决定专题投入顺序，避免按往年经验误判重点。","ch":6},{"no":130,"t":"CCF 全国青少年信息学奥林匹克竞赛教程","sub":"","kind":"官方","auth":"CCF NOI 科学委员会","pub":"CCF","year":"2025","lv":["CSP-S","NOIP","省选"],"use":["教练备课","查漏补缺"],"fx":["方法论"],"how":"CCF 官方渠道","url":"https://www.noi.cn/","note":"配合 2025 版大纲发布，是判断「考什么、考到多深」的第一手依据。","ch":6},{"no":131,"t":"COCI","sub":"","kind":"官方","auth":"克罗地亚信息学奥赛","pub":"hsin.hr","year":"2006","lv":["CSP-S","NOIP","省选"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://hsin.hr/coci/","note":"每月一轮、六题分层，题面短、思维密度高。被中文圈大量用作训练题源。","ch":6},{"no":132,"t":"NOIP 2026 参赛名额分配方案","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-S","NOIP"],"use":["教练备课","查漏补缺"],"fx":["速查","方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-12/938438.shtml","note":"2026 年 10 月 12 日发布。A 类基本名额各省 30 个（内含 3 个女选手保障名额，不足额则作废）；B 类激励名额全国 6600 个，按普及规模 55%、上一年度 NOIP 全国前 27% 占比 27%、上一年度 NOI 金银铜牌分别折算 8/4/3 个名额的 18% 三项加权；C 类为推荐名额（钻石/金牌教师 2 名，指导教师证书入门/提高/NOI 级 1/2/3 名，省特派员 10 名）；D 类为女生专项，不超过本省 A+B+C 之和的 5%。附表列出 32 个省级单位的 A+B 名额（广东 903、浙江 661、山东 613、江苏 477、北京 435，青海 35）。用途：判断本省一等奖的实际稀缺度、估算「省队大致要排到多少名」，比单看往年分数线更有结构。","ch":6},{"no":133,"t":"2023 全国信息学奥林匹克年鉴（电子版）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（CCF 数字图书馆）","year":"2025","lv":["NOIP","省选","NOI"],"use":["教练备课","查漏补缺"],"fx":["深耕","方法论"],"how":"免费（电子版，需 CCF 账号）","url":"https://www.noi.cn/cbw/2025-09-19/848426.shtml","note":"2025 年 9 月 19 日由 CCF 发布。内容是 2023 年度的官方档案：NOI 大事记、组织机构、全年赛事成绩单，以及系列活动（CSP-J/S、NOIP、NOI、冬令营、APIO 中国区）的试题与官方解题报告。这版有个制度性变化必须记下来——公告明确“自本年度起，CCF 将不再出版纸质版 NOI 年鉴，仅以电子版形式向公众开放”，所以它是第一本只存在于 CCF 数字图书馆的年鉴（馆内编号 7688319812339712），与已收录的 2024 年鉴（2026 年 6 月电子版）正好接成连续两年。用途是复盘而非刷题：官方解题报告给出的是命题意图与得分分布，比任何民间题解都更接近出题人本意，做年度命题走向比对、判断某类考点是否在升温时，这是第一手材料；教练写学年计划、向学校说明训练重点时也常引用其中的成绩单。局限：内容止于 2023 年度，2024—2026 三年的试题要走当年的“题目及数据”栏目；电子版需注册 CCF 账号后在馆内阅读，不能直接下载 PDF 外传；单本年鉴体量大，别指望通读，按“先看解题报告、再看成绩单”的顺序取用效率最高。","ch":6},{"no":134,"t":"CCF 关于 NOIP 2026 报名的通知","sub":"","kind":"官方","auth":"中国计算机学会","pub":"noi.cn","year":"2026","lv":["NOIP"],"use":["赛前冲刺","教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-12/938849.shtml","note":"2026 年 10 月 12 日发布：11 月 28 日 8:30—13:00 举行，4 题、机试、4.5 小时；参赛资格仅限在籍在校高中生；报名截止 11 月 9 日 14:00。注意时长是 4.5 小时，不是 3.5 小时。","ch":6},{"no":135,"t":"JOI","sub":"","kind":"官方","auth":"日本信息学奥赛","pub":"joi 官网","year":"1993","lv":["NOIP","省选"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://www.ioi-jp.org/","note":"日本奥赛，题目干净、梯度平滑，春合宿题尤其适合省选阶段。","ch":6},{"no":136,"t":"NOIP 评奖规则","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn","year":"2025","lv":["NOIP"],"use":["教练备课","赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/gynoi/tlgd/2024-11-26/834964.shtml","note":"分数线怎么划、省一省二怎么定。理解规则才能制定合理的得分策略。","ch":6},{"no":137,"t":"NOIP 题目综合分析报告","sub":"","kind":"官方","auth":"CCF NOI 科学委员会","pub":"noi.cn","year":"2025","lv":["NOIP"],"use":["教练备课","查漏补缺"],"fx":["方法论"],"how":"免费","url":"https://noi.cn/xw/2026-09-20/933736.shtml","note":"官方逐题拆解知识点与难度系数。比任何民间「考情分析」都可靠，命题风向标。","ch":6},{"no":138,"t":"第六届女生竞赛报名通知（NOIP 2026 女生赛）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOIP","NOI"],"use":["查漏补缺","赛前冲刺"],"fx":["速查","方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-12/938850.shtml","note":"2026 年 10 月 12 日发布。女生竞赛与 NOIP 2026 一试同步（11 月 28 日 8:30—13:00），报名 NOIP 的女选手自动获得参赛资格，不再单独报名。奖项按参赛总人数 10%/20%/30% 划一、二、三等奖，总获奖率 60%；高中生按成绩取前 10 名（已入选省队者顺延递补，每省经此通道进 NOI 者不超过 2 名）以 B 类身份参加 NOI 2027。价值在于这是一条与省选并行的独立通道：女生若省选把握不大但 NOIP 分数稳定在前列，应把它当主路径规划；反之，错过 NOIP 报名就等于同时放弃两条线。","ch":6},{"no":139,"t":"2022—2023 年国内外信息学主要赛事分析报告","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2025","lv":["省选","NOI"],"use":["教练备课","查漏补缺"],"fx":["方法论","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2025-11-12/852999.shtml","note":"2025 年 11 月 12 日发布于 NOI 官网竞赛资料栏，谢秋锋、金靖、李曙、赵启阳、艾庆兴等 18 位一线教练与高校教师联合执笔。把 NOI 系列赛事与 IOI、APIO、JOI、USACO 等国外赛事按知识点分布、难度结构、区分度做横向对比，是官方视角下「我们的训练强度与命题取向和国外差在哪」的判断材料。教练排年度计划、挑模拟题源时，比只看单年真题分析报告更有参照价值；注意其数据截到 2023 年，结论需与近两年真题对照使用。","ch":6},{"no":140,"t":"APIO 2026 中国区活动赛事综述与分数线","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["省选","NOI"],"use":["赛前冲刺","教练备课"],"fx":["速查","方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-05-11/891305.shtml","note":"2026 年 5 月 7—11 日由 CCF 主办、北京大学附属中学承办，27 个省市自治区共 768 位师生参加，5 月 9 日测试。获奖规模：金牌 75 人（线 196 分）、银牌 117 人（线 155 分）、铜牌 200 人（线 116 分）。同期设七场讲座，讲者为杨耀良（NOI 2017 金）、谢梓涵（NOI 2023 金）、李静榕（NOI 2024 金）及 IOI 2026 国家队四人。核心价值是三条分数线：APIO 是国内选手与亚洲同届横向定位的少数硬指标，可直接用来判断「省队边缘」选手的客观位置，比只看省内排名可靠；讲座名单也可作为选题风向的参考。","ch":6},{"no":141,"t":"CCF 关于 NOI 2027 省内选拔的若干规定","sub":"","kind":"官方","auth":"中国计算机学会","pub":"noi.cn","year":"2026","lv":["省选","NOI"],"use":["教练备课","赛前冲刺"],"fx":["方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-11/930020.shtml","note":"2026 年 9 月 11 日发布，共 15 条。三个关键变化：CCF 不再组织统一省选、NOIP 2026 成绩在省选总成绩中权重不得低于 30%、省队名单须于 2027 年 4 月 7 日前报送。选省选路线前必须先读这一份。","ch":6},{"no":142,"t":"CCPC 官网","sub":"","kind":"官方","auth":"中国大学生程序设计竞赛","pub":"ccpc.io","year":"2015","lv":["省选","NOI"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://ccpc.io/","note":"国内大学生赛事，题目偏工程与思维结合，可作为 OI 之外的补充训练。","ch":6},{"no":143,"t":"ICPC 官网","sub":"","kind":"官方","auth":"ICPC Foundation","pub":"icpc.global","year":"1970","lv":["省选","NOI"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://icpc.global/","note":"大学生赛事，但题目质量高、团队赛制独特。OI 选手常借它练整场节奏。","ch":6},{"no":144,"t":"NOI 2027 名额分配测算方案","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["省选","NOI"],"use":["教练备课","查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-10-28/944054.shtml","note":"2026 年 10 月 28 日发布。给出各省 A/B 类名额的测算口径与调整系数，是判断「本省进省队大概要多少名」的官方依据。教练排年度目标、家长评估路径可行性时先看这份，再看各省实施细则。","ch":6},{"no":145,"t":"NOI 2027 联合省选：两试时间与成绩构成对照（26 省市）","sub":"","kind":"官方","auth":"","pub":"CCF 及各省竞赛委员会（NOI 官网省赛栏目）","year":"2027","lv":["省选"],"use":["赛前冲刺","查漏补缺"],"fx":["速查"],"how":"免费（各省公告，含报名表与日程附件）","url":"https://www.noi.cn/gs/xw/zq/2026-10-28/943712.shtml","note":"2026 年 10 月下旬起，各省陆续在 noi.cn 省赛栏目发布 NOI 2027 省队选拔方案，共同点是参加多省（26 个省市）联合省选、委托第三方统一命题与评测、环境统一 NOI Linux 2.0，两试都排在 2027 年 3 月 6 日与 7 日上午 8:30—13:30、每试 3 题。差异全在成绩构成上：上海为 NOIP 2026 标准分 30% + 一试 35% + 二试 35%，北京为 40 + 30 + 30，重庆为 NOIP 40% + 省选 60%，辽宁为 NOIP 30% + 省选 70%，江西按 NOIP 成绩/400×600×40% + 联合省选 60%。报名一律由学籍所在学校统一提交、不接受个人报名，截止时间各省不同（江西 2026-12-31、江苏 2027-01-08 至 31、北京 2027-01-10 至 17、辽宁 2027-01-25 至 30、上海 2027-01-30）；资格线普遍是 NOIP 2026 省一或全国三等基准线以上、非高三在籍在校，A 队 5 人（4 男 1 女）、其余按名额进 B 队。用法很直接：先算清本省的权重，再决定省选前的训练重心——权重 30/70 的省份，省选两试几乎决定命运，NOIP 只需保住资格线；权重 40/60 的省份，NOIP 每一分都值钱，不能抱着「省选再翻盘」的心态。另有两处容易忽略：多省把「NOI 2027 冬令营成绩」写进同分排序（重庆明确未参加者按 0 分计），以及「三分之一」原则对单校名额的限制。局限：这里给的是各省方案的共同骨架与若干省的权重实例，具体考点、试机、申诉流程必须回到本省公告附件核对；A/B 类名额与「三分之一」细则以 CCF 的《NOI 2027 省内选拔的若干规定》为准，省方案与 CCF 规定冲突时以后者为准。","ch":6},{"no":146,"t":"2024 全国信息学奥林匹克年鉴","sub":"","kind":"官方","auth":"","pub":"CCF 数字图书馆","year":"2026","lv":["NOI","省选"],"use":["教练备课","查漏补缺"],"fx":["深耕"],"how":"电子书","url":"https://dl.ccf.org.cn/article/detail.html?id=8057449899870208","note":"CCF 主编，2026 年 6 月以电子版发布。含 2024 年 NOI 大事记、组织机构、赛事成绩单，以及全年系列活动试题与解题报告。教练做年度复盘、对比本省选手分布、研究命题走向时的第一手材料，比零散搜集题面更完整。","ch":6},{"no":147,"t":"APIO 官网","sub":"","kind":"官方","auth":"Asia-Pacific Informatics Olympiad","pub":"apio 官网","year":"2007","lv":["NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://www.apio-official.org/","note":"亚太赛。中国区由 CCF 组织，题目难度略低于 IOI，是省队选手的第一次国际模拟。","ch":6},{"no":148,"t":"Baltic OI","sub":"","kind":"官方","auth":"Baltic Olympiad in Informatics","pub":"boi 官网","year":"1995","lv":["NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费 / oj.uz","url":"https://oj.uz/","note":"波罗的海地区奥赛，题目风格接近 IOI，难度中等偏上，适合补充题源。","ch":6},{"no":149,"t":"CCF NOI 集训营 2026 综合素质评价机制（附国家集训队行为规范）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2026","lv":["NOI","IOI"],"use":["教练备课","赛前冲刺"],"fx":["方法论"],"how":"官网公告（免费阅读）","url":"https://www.noi.cn/xw/2026-09-28/935940.shtml","note":"2026 年 9 月 26 日 CCF NOI 集训营 2026 开营会议上发布的机制说明，与《国际信息学奥林匹克中国国家集训队行为规范》《IOI 2027 中国国家队选拔规则》同日公布。要点有三：① 国家集训队选拔首次把「综合素质评价」与竞赛成绩并列，成为后续国家队选拔的依据之一，考评维度明确列在出勤、材料提交、文明交流、安全意识、公共行为、住宿秩序六项上，依据「客观、可核实的事实」打分；② 未达阈值分者失去后续国家队选拔资格，情节严重者直接取消集训队资格；③ 同时公布三阶段选拔流程与淘汰规则，并明确指导教师除专业训练外还承担行为规范与成长状态的育人责任。这份文件的实际读者不是选手而是教练与家长：它把「唯成绩」这条路在最高层级上正式堵死，意味着集训队层面的时间管理、材料提交、集体生活规范都会影响选拔结果。对省队以下的选手，它的价值是提前校准预期——把「进集训队」理解成一次有行为约束的集训，而不是一次纯考试。局限：公告只给规则框架与评分维度，未公开各项权重与阈值分数；具体打分表在执行层面，外界无法核对。","ch":6},{"no":150,"t":"CEOI","sub":"","kind":"官方","auth":"Central European Olympiad in Informatics","pub":"ceoi 官网","year":"1994","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费 / oj.uz","url":"https://oj.uz/","note":"中欧奥赛，构造与交互题质量高，是 IOI 前的高质量模拟题源。","ch":6},{"no":151,"t":"IOI 2027 中国国家队选拔规则与国家集训队行为规范","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","IOI"],"use":["教练备课","赛前冲刺"],"fx":["速查","方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-28/935940.shtml","note":"2026 年 9 月 28 日随 CCF NOI 集训营 2026 开营发布，含《国际信息学奥林匹克中国国家集训队行为规范》《IOI 2027 中国国家队选拔规则》与综合素质评分规则。核心变化是把综合素质评价正式并入国家队选拔：出勤、材料提交、文明交流、安全意识、公共行为、住宿秩序六项按可核实事实打分，未达阈值即失去后续选拔资格。走集训队路线的选手与教练必须读原文——往年只看成绩的备赛习惯，从这一届起不再成立。","ch":6},{"no":152,"t":"IOI Syllabus","sub":"国际信息学奥赛大纲","kind":"官方","auth":"IOI 国际委员会","pub":"IOI","year":"2020","lv":["NOI","IOI"],"use":["教练备课","查漏补缺"],"fx":["速查"],"how":"官网免费","url":"https://ioinformatics.org/page/syllabus/12","note":"对照国内大纲看差异：国际赛更强调建模与证明，知识点边界更宽。","ch":6},{"no":153,"t":"NOI 冬令营 2026 首次 AI 辅助编程测试（人机协同评测）","sub":"","kind":"官方","auth":"","pub":"中国计算机学会（NOI 官网通稿）","year":"2026","lv":["NOI","IOI"],"use":["教练备课","专题突破"],"fx":["方法论"],"how":"免费（官网通稿）","url":"https://www.noi.cn/xw/2026-02-13/861386.shtml","note":"2026 年 2 月 13 日 CCF 通稿披露。第 43 届全国青少年信息学奥林匹克冬令营（2026 年 2 月 6—13 日，青岛城阳一中）首次并行设立「有 AI 辅助编程」的测试：邀请 30 位选手参加，可访问指定的大模型，但题目与软硬件环境与本届常规测试完全一致，单独评奖，最终评出金牌 3 名、银牌 6 名、铜牌 10 名。官方给出的定性是「为探索未来信息学竞赛的可能形式、积累经验和数据，为未来相关决策提供数据支持」。据江苏方面对参赛选手的报道，接入的是「千问」「DeepSeek」两大系列共四个模型。同届冬令营常规测试为 56 金 137 银 147 铜，澳门代表队首次参加现场活动。这条的价值不在「多了一个奖项」，而在它第一次把「人机协同」纳入中国 OI 的正式评测口径，且刻意保持题目与常规测试一致——这说明组织方要测的是「同一套题、有 AI 与无 AI 的分数差」，而不是另出一套简单题。对教练的直接含义：今后讨论「要不要让学生用 AI 做题」时，这是目前唯一有官方数据支撑的对照实验，可以等后续公布的分差再定训练策略。局限也要写清楚：官方通稿未公布题目、评分细则、AI 使用限制（可用次数、是否限提示词、是否允许整段生成代码），也未说明该测试是否会延续到后续 NOI 系列活动；把它当成「以后比赛都能用 AI」的确定趋势为时过早。","ch":6},{"no":154,"t":"NOI 参赛资格规定","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn","year":"2025","lv":["NOI"],"use":["教练备课"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/gynoi/tlgd/","note":"A/B/C/D/E 类名额的划分与获取方式。省队选拔前必须搞清楚自己走哪条通道。","ch":6},{"no":155,"t":"NOI 试题分析与年鉴","sub":"","kind":"官方","auth":"CCF","pub":"noi.cn / 正式出版","year":"2000","lv":["NOI"],"use":["教练备课","赛前冲刺"],"fx":["方法论"],"how":"部分公开 / 纸质","url":"https://www.noi.cn/xw/","note":"官方对当年试题的逐题分析，含命题意图与得分分布。比任何民间题解都更接近出题人本意。","ch":6},{"no":156,"t":"POI","sub":"","kind":"官方","auth":"波兰信息学奥赛","pub":"oi.edu.pl","year":"1994","lv":["NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://oi.edu.pl/","note":"波兰是 OI 强国，POI 题目以思维难度著称，适合冲击高分段的选手。","ch":6},{"no":157,"t":"USACO 2025-2026 赛季赛制改革：三场线上赛 + 监考制 US Open","sub":"","kind":"官方","auth":"","pub":"USACO（美国计算机奥林匹克）","year":"2026","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["方法论"],"how":"在线页面（免费，官方首页赛季回顾）","url":"https://usaco.org/","note":"USACO 在官方首页的「2025-2026 Competition Schedule Recap」里说明本赛季结构与往年不同：改为 2026 年年初三场线上赛，之后一场监考（proctored）的邀请制 US Open 锦标赛；线上赛中表现最好的美国选手获邀参加这场线下终局，而它成为选拔 2026 集训营 finalist、以及 2026 EGOI 四名队员的主要依据。另外两条改动值得注意：一是 platinum 组在赛季开始时被统一重置回 gold（官方称此做法可能延续），二是因 2026 EGOI 早于集训营举行，EGOI 队伍提前确定，EGOI 队员与未来潜力选手仍受邀参加集训营。官方明确这是「过渡年」，组别仍保持 bronze/silver/gold/platinum 四级以便稳定，但未来可能调整为更看重线下终局成绩的年度评价。对国内选手的实际意义有三点：赛季窗口从「12 月—次年 3 月四场」压缩成「年初三场」，每次机会的权重上升，用 USACO 题单做训练时必须按新节奏排；「线上 → 受邀线下 → 定 finalist」这条链与国内「省选 → NOI → 集训队」同构，可直接拿来对比两种选拔哲学（美国把决定性环节放在一场监考赛，国内把权重摊到省选与 NOI 两试）；platinum 重置意味着跨赛季刷题时旧分不再代表当前组别。同时提醒：2025 年及以前的资料（含本目录中按「四场月赛」描述 USACO 的旧条目）描述的是旧赛制，排训练计划时以本条为准。","ch":6},{"no":158,"t":"关于自 NOI 2029 起取消 A 类选手加分政策的公告","sub":"","kind":"官方","auth":"中国计算机学会","pub":"noi.cn","year":"2026","lv":["NOI","省选"],"use":["教练备课"],"fx":["方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-09-11/930261.shtml","note":"2026 年 9 月 11 日发布。NOI 2027、2028 为过渡期仍加 5 分，2029 年起取消。政策变化会影响弱省的选拔策略，规划三年路线时必须纳入。","ch":6},{"no":159,"t":"IOI 2026 中国队 3 金 1 银与最终排名","sub":"","kind":"官方","auth":"","pub":"中国计算机学会","year":"2026","lv":["IOI","NOI"],"use":["教练备课","赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-08-16/924196.shtml","note":"第 38 届 IOI 于 2026 年 8 月 9—16 日在乌兹别克斯坦塔什干举行，97 个国家与地区 375 名选手参赛，共产生金牌 31、银牌 62、铜牌 94。中国队 3 金 1 银、团体第一：许淇文（南京外国语学校）498.27 分列第 1，赵晟昊（浙江金华第一中学）第 3，刘家炜（重庆市巴蜀中学校）第 13，何宇翔（重庆南开融侨中学校）银牌、第 38。领队赵启阳，副领队蒋婷婷；下一届在德国举办。用途：赛制为两天各 3 题、每天 5 小时、满分 600，用 498.27 这个冠军分与历年冠军分对照，可粗判当年题目难度，并据此给队内模拟定「两天六题拿多少」的目标。","ch":6},{"no":160,"t":"IOI 2027 官方网站（第 39 届，德国波茨坦 HPI，2027-09-12—19）","sub":"","kind":"官方","auth":"","pub":"IOI 2027 组织委员会 / 哈索·普拉特纳研究所（HPI）","year":"2027","lv":["IOI"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费（官网，赛前持续更新）","url":"https://ioi2027.de/","note":"第 39 届国际信息学奥林匹克定于 2027 年 9 月 12—19 日在德国波茨坦举行，承办方是哈索·普拉特纳研究所（Hasso Plattner Institute, HPI）——这是德国继 1992 年波恩之后隔 35 年再次主办 IOI。官网已上线，目前给出的是举办日期、主办机构与城市介绍、赞助与支持方名单，并明确说明「站点会随筹备推进持续更新」，后续才放日程、场地与参赛信息。同期 IOI 官方站开放了 IOI 2027 的 Call for Tasks（征题），截止 2026 年 12 月 31 日 23:59 UTC−12，明确「潜在参赛者不得投稿」，欢迎 batch、communication、output-only 三类以及 IOI 此前未出现过的新题型，并特别说明「简单的原创题最难写、也最缺」。用法分两类：选手侧只用来看赛程与赛制变更——IOI 的规则改动走 General Assembly，最终文本在 ioinformatics.org 的 Regulations，东道主官网只作日程参考；教练与命题者侧，这是提前一年观察东道主命题取向的窗口，往届东道主常在题型配比上做文章（2026 塔什干提高了交互与构造题的比重），征题公告里的题型清单往往就是风向。局限：截至 2026 年 11 月，页面仍以宣传与筹备信息为主，没有题面、没有逐日日程、没有参赛名额；中国队选拔与报名完全不走这里（在 noi.cn），别把它当报名入口。","ch":6},{"no":161,"t":"IOI 官网","sub":"","kind":"官方","auth":"International Olympiad in Informatics","pub":"ioinformatics.org","year":"1989","lv":["IOI"],"use":["赛前冲刺","教练备课"],"fx":["速查","实战"],"how":"免费","url":"https://ioinformatics.org/","note":"历年试题、成绩、规则、大纲的唯一权威来源。做国际题从这里下原版题面。","ch":6},{"no":162,"t":"IOI 年度报告与命题趋势","sub":"","kind":"官方","auth":"IOI","pub":"ioinformatics.org","year":"1989","lv":["IOI"],"use":["教练备课","赛前冲刺"],"fx":["方法论"],"how":"免费","url":"https://ioinformatics.org/","note":"历年赛题统计、参赛国分布、评分规则变更。判断「未来两年考什么」最可靠的公开材料。","ch":6},{"no":163,"t":"HydroOJ","sub":"","kind":"平台","auth":"Hydro 开源社区","pub":"hydro.ac","year":"2021","lv":["通用"],"use":["教练备课","实战训练"],"fx":["实战"],"how":"免费 / 自建","url":"https://hydro.ac/","note":"开源评测系统，学校可以自建域做校内赛。教练做训练营的最佳底座。","ch":7},{"no":164,"t":"AcWing","sub":"","kind":"平台","auth":"闫学灿（yxc）","pub":"acwing.com","year":"2018","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["体系学习","实战训练"],"fx":["实战"],"how":"免费题库 + 付费课程","url":"https://www.acwing.com/","note":"国内最系统的算法课程型题库，题面中文、配套视频、按知识点分章。零基础起步体验最好的一站。","ch":7},{"no":165,"t":"Aizu Online Judge","sub":"","kind":"平台","auth":"会津大学","pub":"judge.u-aizu.ac.jp","year":"2004","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["实战"],"how":"免费注册","url":"https://judge.u-aizu.ac.jp/","note":"自带编程入门课程与章节题，平台本身就是教材。","ch":7},{"no":166,"t":"Algorithm Visualizer","sub":"","kind":"平台","auth":"开源社区","pub":"algorithm-visualizer.org","year":"2016","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["速查"],"how":"免费","url":"https://github.com/algorithm-visualizer/algorithm-visualizer","note":"可单步执行的算法动画，含回溯、DP、排序。比 VisuAlgo 更偏「追踪变量」，适合理解递归。","ch":7},{"no":167,"t":"AtCoder","sub":"ABC / ARC / AGC","kind":"平台","auth":"AtCoder Inc.","pub":"atcoder.jp","year":"2012","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["实战训练","入门自修"],"fx":["实战"],"how":"免费注册","url":"https://atcoder.jp/","note":"题目干净、难度梯度平滑。ABC 的 A–F 六题几乎是一条完整的能力阶梯，初学者最友好。","ch":7},{"no":168,"t":"HackerRank","sub":"","kind":"平台","auth":"HackerRank","pub":"hackerrank.com","year":"2009","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["实战"],"how":"免费","url":"https://www.hackerrank.com/domains/algorithms","note":"英文入门题量大、判题友好。适合第一次读英文题面时练手，难度上限不高。","ch":7},{"no":169,"t":"LeetCode","sub":"","kind":"平台","auth":"LeetCode","pub":"leetcode.cn","year":"2015","lv":["CSP-J"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 会员","url":"https://leetcode.cn/","note":"面试题为主，难度与 OI 不同源。只建议用来熟悉语言与基础语法，不要当 OI 主训练场。","ch":7},{"no":170,"t":"OpenJudge","sub":"","kind":"平台","auth":"POJ 团队","pub":"openjudge.cn","year":"2005","lv":["CSP-J"],"use":["入门自修"],"fx":["实战"],"how":"免费注册","url":"http://openjudge.cn/","note":"可按学校/机构建小组，题目偏基础，适合班级统一布置作业。","ch":7},{"no":171,"t":"PTA 拼题 A","sub":"","kind":"平台","auth":"浙江大学 / 杭州百腾","pub":"pintia.cn","year":"2016","lv":["CSP-J","CSP-S"],"use":["体系学习"],"fx":["实战"],"how":"免费 / 部分付费","url":"https://pintia.cn/","note":"课程化题库，按教学进度组织。适合跟着学校课程走的学生。","ch":7},{"no":172,"t":"USACO","sub":"美国信息学奥赛","kind":"平台","auth":"USACO","pub":"usaco.org","year":"1992","lv":["CSP-J","CSP-S","NOIP"],"use":["体系学习","实战训练"],"fx":["实战"],"how":"免费注册","url":"https://usaco.org/","note":"Bronze→Platinum 四级，题目质量高、英文表述规范。想练英文读题就从这里开始。","ch":7},{"no":173,"t":"USFCA 数据结构可视化","sub":"","kind":"平台","auth":"David Galles（旧金山大学）","pub":"cs.usfca.edu","year":"2011","lv":["CSP-J","CSP-S","NOIP"],"use":["入门自修","查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.cs.usfca.edu/~galles/visualization/Algorithms.html","note":"红黑树、AVL、B 树、堆、图算法的交互演示。讲课时投屏效果极佳，也是自查理解的手段。","ch":7},{"no":174,"t":"Vijos","sub":"","kind":"平台","auth":"Vijos 团队","pub":"vijos.org","year":"2005","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["实战","速查"],"how":"免费注册","url":"https://vijos.org/","note":"老牌 OJ，保留大量早期经典题。活跃度下降，但历史题目仍是好材料。","ch":7},{"no":175,"t":"VisuAlgo","sub":"","kind":"平台","auth":"Steven Halim（新加坡国立大学）","pub":"visualgo.net","year":"2011","lv":["CSP-J","CSP-S","NOIP"],"use":["入门自修","查漏补缺"],"fx":["速查"],"how":"免费","url":"https://visualgo.net/","note":"算法过程可视化。线段树、平衡树、最短路、网络流都能一步步看动画，卡住时看一遍胜过读三段文字。","ch":7},{"no":176,"t":"WZOI（温州中学 OJ）","sub":"","kind":"平台","auth":"浙江省温州中学","pub":"wzoi.cc","year":"2017","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["实战"],"how":"免费（原站已不稳定）","url":"","note":"中学自建的开源 OJ，题目贴近教学实际，适合校内训练。原站近年时常无法访问，可搜「WZOI 镜像」或自行部署同款开源 OJ。","ch":7},{"no":177,"t":"一本通在线评测（ybt）","sub":"","kind":"平台","auth":"一本通编写组","pub":"ssoier.cn","year":"2015","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["实战"],"how":"免费","url":"http://ybt.ssoier.cn/","note":"《信息学奥赛一本通》配套题库，章节与教材一一对应。学校机房最常用的练习站。","ch":7},{"no":178,"t":"梦熊 OJ（Mengxiong Online Judge）","sub":"","kind":"平台","auth":"","pub":"梦熊信息学联盟","year":"2024","lv":["CSP-J","CSP-S","NOIP"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费（部分团队赛需邀请码）","url":"http://www.mxoj.net/","note":"域名 mxoj.net，另有 mengxiong.cn 指向同一套系统（页面备案号为京ICP备2024090394号，可据此判断站点自 2024 年起运营）。与洛谷、UOJ 这类“自己找题刷”的平台不同，它的组织方式是团队制：先输入邀请码加入某个团队，才能在团队内看到比赛与题单，因此公开检索到的题目有限——这也是它最容易被误判的地方。真正值得用的是它的“全真模考”能力。以 2026 年国庆场为例：2026 年 10 月 1 日 CSP-J 组 08:30—12:00（3.5 小时、4 题）、CSP-S 组 14:30—18:30（4 小时、4 题），明确要求文件读写、按 NOI 赛制提交，赛后 13:00 与 20:00 各有一场免费直播讲评；同一年度还有面向 CSP-J 与 CSP-S 的“二十连测”公开赛，逐场推进。用法建议：把它当“考场模拟器”，考前按组别掐时间整场做，做完就进讲评；不要把它当题库——题库的沉淀与题解体系远不如洛谷，题目总数在首页长期显示为建设中。另需注意：它是商业赛训机构（梦熊联盟，2017 年成立）的入口，注册要实名，部分比赛限定年级评奖，参赛前先看清规则。","ch":7},{"no":179,"t":"洛谷","sub":"Luogu","kind":"平台","auth":"上海洛谷网络科技","pub":"luogu.com.cn","year":"2013","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["实战训练","入门自修","赛前冲刺"],"fx":["实战"],"how":"免费注册","url":"https://www.luogu.com.cn/","note":"国内 OI 第一入口。题库按难度分红到黑，题单体系完整，几乎每道题都有题解与讨论。主训练场选它。","ch":7},{"no":180,"t":"洛谷主题题库","sub":"","kind":"平台","auth":"洛谷","pub":"luogu.com.cn","year":"2013","lv":["CSP-J","CSP-S","NOIP","省选","NOI"],"use":["专题突破","查漏补缺"],"fx":["实战"],"how":"免费","url":"https://www.luogu.com.cn/training/list","note":"官方与用户共建的题单体系。「省选DP」「图论500题」这类成套题单，是专题突破最快的入口。","ch":7},{"no":181,"t":"洛谷公开赛与月赛","sub":"","kind":"平台","auth":"洛谷","pub":"luogu.com.cn","year":"2013","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://www.luogu.com.cn/contest/list","note":"每月多场，含入门赛到省选难度。真实比赛节奏的训练场，比单纯刷题更接近考场。","ch":7},{"no":182,"t":"洛谷题单","sub":"Training List","kind":"平台","auth":"洛谷社区","pub":"luogu.com.cn","year":"2018","lv":["CSP-J","CSP-S","NOIP"],"use":["体系学习","实战训练"],"fx":["实战"],"how":"免费","url":"https://www.luogu.com.cn/training/list","note":"别人替你把题按专题排好了顺序。新手最该用的功能，比自己在题库里乱翻效率高一个量级。","ch":7},{"no":183,"t":"编程猫 OJ（北大—点猫人工智能教育联合实验室）","sub":"","kind":"平台","auth":"","pub":"北大—点猫科技人工智能教育联合实验室","year":"2026","lv":["CSP-J","CSP-S","NOIP","NOI"],"use":["入门自修","实战训练"],"fx":["实战"],"how":"在线平台","url":"https://ai-oj.codemao.cn","note":"2026 年 3 月北京大学信息科学技术学院与点猫科技共建「北大—点猫科技人工智能教育联合实验室」，其首批产出即编程猫 OJ（ai-oj.codemao.cn）。题库为覆盖 CSP-J/S、NOIP 至 NOI 的原创题，按「入门—普及—提高—省选—NOI」五级闯关组织，集成 AI 出题、实时判题、月赛/模拟赛与题解讨论；教练端可建队、申请学校专场、查看答题数据。与洛谷、Hydro 的差别在定位：题库规模远小于老牌 OJ，胜在赛段分层清晰与教练看板，适合校内梯队的分阶段测评与专场训练，主力刷题仍应放在洛谷与 Codeforces。风险提示：平台 2026 年新上线，题目存量与长期维护需自行观察，不要把它当作唯一训练来源。","ch":7},{"no":184,"t":"蓝桥云课","sub":"","kind":"平台","auth":"蓝桥杯组委会","pub":"lanqiao.cn","year":"2017","lv":["CSP-J","CSP-S"],"use":["入门自修","实战训练"],"fx":["实战"],"how":"免费 + 付费","url":"https://www.lanqiao.cn/","note":"蓝桥杯官方练习平台。CSP-J 阶段可作为「刷题量」的补充，但题型与 NOI 系有偏差，别当主线。","ch":7},{"no":185,"t":"计蒜客","sub":"","kind":"平台","auth":"北京矩道优达","pub":"jisuanke.com","year":"2015","lv":["CSP-J","CSP-S"],"use":["入门自修","实战训练"],"fx":["实战"],"how":"部分付费","url":"https://www.jisuanke.com/","note":"按知识点和难度筛题，配套课程。适合需要「有人带着走」的初学者。","ch":7},{"no":186,"t":"51Nod","sub":"","kind":"平台","auth":"51Nod 团队","pub":"51nod.com","year":"2014","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["实战"],"how":"免费注册","url":"https://www.51nod.com/","note":"数学题与思维题密度高，适合专门练「想不出来但一看就会」的题型。","ch":7},{"no":187,"t":"AtCoder Problems","sub":"","kind":"平台","auth":"kenkoooo","pub":"kenkoooo.com","year":"2016","lv":["CSP-S","NOIP","省选","NOI"],"use":["查漏补缺","实战训练"],"fx":["速查"],"how":"免费","url":"https://kenkoooo.com/atcoder/","note":"把 AtCoder 全部题目按难度打分并推荐。配合「已 AC 集合」能精确找出你能力边缘的题。","ch":7},{"no":188,"t":"Baekjoon Online Judge","sub":"BOJ","kind":"平台","auth":"Baekjoon","pub":"acmicpc.net","year":"2010","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://www.acmicpc.net/","note":"韩国最大 OJ，题量巨大、分类清晰，很多题有中文翻译。","ch":7},{"no":189,"t":"CSES Problem Set","sub":"","kind":"平台","auth":"Antti Laaksonen / 赫尔辛基大学","pub":"cses.fi","year":"2013","lv":["CSP-S","NOIP"],"use":["体系学习","专题突破"],"fx":["实战"],"how":"免费","url":"https://cses.fi/problemset/","note":"300 道题按专题排好，一题一技，干扰最少。与 CPH 配套，是「系统过一遍」的最佳载体。","ch":7},{"no":190,"t":"CodeChef","sub":"","kind":"平台","auth":"Directi","pub":"codechef.com","year":"2009","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://www.codechef.com/","note":"印度 OJ，长期赛制独特（十天一场），适合练长线思考。","ch":7},{"no":191,"t":"Codeforces","sub":"CF","kind":"平台","auth":"Mike Mirzayanov","pub":"codeforces.com","year":"2010","lv":["CSP-S","NOIP","省选","NOI"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费注册","url":"https://codeforces.com/","note":"全球竞赛核心。Div.2 稳定练手、Div.1 冲上限，rated 分数是国际通行的能力刻度。","ch":7},{"no":192,"t":"Codeforces 题目集（按 rating 筛选）","sub":"","kind":"平台","auth":"Codeforces","pub":"codeforces.com","year":"2010","lv":["CSP-S","NOIP","省选","NOI"],"use":["查漏补缺","实战训练"],"fx":["实战"],"how":"免费","url":"https://codeforces.com/problemset","note":"用 tags + rating 区间精确取题，例如 「dp, 1900-2100」。全世界最有效的专题训练工具。","ch":7},{"no":193,"t":"Comet OJ","sub":"","kind":"平台","auth":"Comet 团队","pub":"cometoj.com","year":"2018","lv":["CSP-S","NOIP"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费注册","url":"https://www.cometoj.com/","note":"经常办原创赛，题目风格接近 NOIP。适合打非官方模拟赛练手感。","ch":7},{"no":194,"t":"DMOJ","sub":"","kind":"平台","auth":"Don Mills","pub":"dmoj.ca","year":"2015","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://dmoj.ca/","note":"加拿大现代 OJ，聚合各大赛存档，语言支持广，界面体验好。","ch":7},{"no":195,"t":"HDU Online Judge","sub":"","kind":"平台","auth":"杭州电子科技大学","pub":"acm.hdu.edu.cn","year":"2005","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://acm.hdu.edu.cn/","note":"多校联合训练的题源，题量大。适合按专题检索老题。","ch":7},{"no":196,"t":"Lutece","sub":"","kind":"平台","auth":"电子科技大学","pub":"lutece.uestc.edu.cn","year":"2018","lv":["CSP-S"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://lutece.uestc.edu.cn/","note":"高校开源 OJ，题面中英混排，适合补充非 OI 风格的算法题。","ch":7},{"no":197,"t":"POJ","sub":"北京大学在线评测","kind":"平台","auth":"北京大学","pub":"poj.org","year":"2003","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"http://poj.org/","note":"国内最老 OJ 之一，英文题多。经典但界面古老，适合刷指定经典题号。","ch":7},{"no":198,"t":"SPOJ","sub":"","kind":"平台","auth":"Sphere Research Labs","pub":"spoj.com","year":"2004","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://www.spoj.com/","note":"海量老题，质量参差。只在需要某个经典题号时才来。","ch":7},{"no":199,"t":"UVa Online Judge","sub":"","kind":"平台","auth":"Universidad de Valladolid","pub":"onlinejudge.org","year":"1995","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://onlinejudge.org/","note":"最老的 OJ 之一，《Competitive Programming》全书题号都指向它。","ch":7},{"no":200,"t":"ZOJ","sub":"","kind":"平台","auth":"浙江大学","pub":"zoj.pintia.cn","year":"2001","lv":["CSP-S"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://zoj.pintia.cn/","note":"浙大老牌 OJ，题面英文。现在主要作为历史题库使用。","ch":7},{"no":201,"t":"e-olymp","sub":"","kind":"平台","auth":"e-olymp","pub":"eolymp.com","year":"2010","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://eolymp.com/","note":"东欧题源聚合站，收纳大量小学奥赛与区域赛题。题面英文，难度集中在普及到提高之间。","ch":7},{"no":202,"t":"牛客网","sub":"Nowcoder","kind":"平台","auth":"牛客网","pub":"nowcoder.com","year":"2014","lv":["CSP-S","NOIP"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费注册","url":"https://www.nowcoder.com/","note":"OI 赛与求职题混排。OI 部分有专项训练与模考，适合赛前找整场节奏。","ch":7},{"no":203,"t":"Codeforces Gym","sub":"","kind":"平台","auth":"Codeforces","pub":"codeforces.com","year":"2010","lv":["NOIP","省选","NOI","IOI"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://codeforces.com/gyms","note":"各类集训、省队选拔、ICPC 区域赛的原始赛题存档。想找「真赛题」来这里，不在主题库里。","ch":7},{"no":204,"t":"Judge Duck Online","sub":"","kind":"平台","auth":"松松松","pub":"duck.ac","year":"2020","lv":["NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://duck.ac/","note":"评测精度到微秒，用来验证常数优化到底有没有用。题量少但工具属性强。","ch":7},{"no":205,"t":"Kattis","sub":"","kind":"平台","auth":"KTH","pub":"open.kattis.com","year":"2010","lv":["NOIP","省选"],"use":["实战训练"],"fx":["实战"],"how":"免费注册","url":"https://open.kattis.com/","note":"ICPC 真题库，按 Elo 难度推题。想练「读完题就知道考什么」的直觉很有效。","ch":7},{"no":206,"t":"Timus","sub":"","kind":"平台","auth":"乌拉尔联邦大学","pub":"acm.timus.ru","year":"2000","lv":["NOIP","省选"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://acm.timus.ru/","note":"俄式硬核题，难度偏高。冲刺期用来压题不错。","ch":7},{"no":207,"t":"LibreOJ","sub":"LOJ","kind":"平台","auth":"Menci 等","pub":"loj.ac","year":"2017","lv":["省选","NOI"],"use":["实战训练","查漏补缺"],"fx":["实战"],"how":"免费注册","url":"https://loj.ac/","note":"测试数据与提交代码全部公开，赛后能看别人怎么写的。复盘与对拍的首选平台。","ch":7},{"no":208,"t":"Nowcoder 多校训练营","sub":"","kind":"平台","auth":"牛客网","pub":"nowcoder.com","year":"2018","lv":["省选","NOI"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"免费 / 部分付费","url":"https://ac.nowcoder.com/acm/contest/vip-index","note":"暑期多校，题目偏难偏怪，是省队选手的集训主战场。赛后题解质量参差，需自己筛。","ch":7},{"no":209,"t":"OEIS 整数数列百科","sub":"","kind":"平台","auth":"OEIS Foundation","pub":"oeis.org","year":"1964","lv":["省选","NOI","IOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://oeis.org/","note":"数论、计数题猜结论的终极工具。打出前几项就能查到封闭形式与生成函数，考场外验证思路神器。","ch":7},{"no":210,"t":"QOJ","sub":"","kind":"平台","auth":"QOJ 团队","pub":"qoj.ac","year":"2021","lv":["省选","NOI","IOI"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"免费注册","url":"https://qoj.ac/","note":"国内外 OI 与 ICPC 赛题的集中存档，可按比赛整场模拟。找真题最全的地方之一。","ch":7},{"no":211,"t":"UOJ","sub":"Universal Online Judge","kind":"平台","auth":"VFK 等","pub":"uoj.ac","year":"2014","lv":["省选","NOI"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"免费注册","url":"https://uoj.ac/","note":"原创题多、难度高，题目质量在国内属第一梯队。提高组冲省选阶段的磨刀石。","ch":7},{"no":212,"t":"Library Checker","sub":"","kind":"平台","auth":"Nyaan 等","pub":"judge.yosupo.jp","year":"2019","lv":["NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://judge.yosupo.jp/","note":"验证模板正确性与常数的标准靶场。写完一个数据结构，来这里跑一遍再放进模板库。","ch":7},{"no":213,"t":"Universal Cup","sub":"","kind":"平台","auth":"Universal Cup 组委会","pub":"ucup.ac","year":"2022","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://ucup.ac/","note":"全球强队都在打的系列赛，题目难度对齐区域赛与 IOI。想摸国际天花板就来这里。","ch":7},{"no":214,"t":"oj.uz","sub":"","kind":"平台","auth":"Olympiad 社区","pub":"oj.uz","year":"2016","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费注册","url":"https://oj.uz/","note":"IOI、APIO、 Baltic OI 等国际奥赛题的官方镜像，题面干净。国际赛真题首选。","ch":7},{"no":215,"t":"信息学竞赛中的思维方法","sub":"","kind":"论文","auth":"陈彧","pub":"国家集训队 2000","year":"2000","lv":["通用"],"use":["教练备课"],"fx":["方法论"],"how":"论文集","url":"","note":"少见的「讲怎么想」而不是「讲怎么做」的文献，适合阶段复盘时读。","ch":8},{"no":216,"t":"测试数据设计中的三要素","sub":"","kind":"论文","auth":"杨帆","pub":"国家集训队 1999","year":"1999","lv":["通用"],"use":["教练备课"],"fx":["方法论"],"how":"论文集","url":"","note":"造数据不是随便随机。准确性、全面性、美观性三条标准，出题人必读。","ch":8},{"no":217,"t":"ISSEP 2026 论文集：AI 时代的中小学信息学教育","sub":"","kind":"论文","auth":"","pub":"Springer（LNCS 第 17124 卷）","year":"2026","lv":["CSP-J","CSP-S"],"use":["教练备课"],"fx":["方法论","深耕"],"how":"SpringerLink 电子版（单章 29.95 欧元，机构订阅可读；目录与摘要免费）","url":"https://link.springer.com/book/10.1007/978-3-032-41153-2","note":"第 19 届 ISSEP（Informatics in Schools: Situation, Evolution, and Perspectives）会议论文集，2026 年 9 月 20—23 日于爱沙尼亚塔林举行，Springer 2026 年 10 月 11 日上线，编者 Piret Luik（塔尔图大学）与 Mart Laanpere（塔林大学）；印刷版 ISBN 978-3-032-41152-5、电子版 978-3-032-41153-2。共 15 篇（13 篇全文 + 1 篇短文 + 1 篇主题报告），从 34 篇投稿中录用，分三个主题：课程、政策与信息学教育的未来；信息学的教与学；计算思维与学习者多样性。对竞赛教练最有直接价值的是三篇：Hromkovič 与 Lacher 的「用基因苏格拉底法在课堂上发现 Hamming 码」（53—70 页）给出一套完整流程——不给定义、只用提问把纠错编码的约束条件逼出来，是「专题课怎么讲才能让学生自己推」的范本；Lepp、Luik、Dagienė 的「Bebras 挑战中的性别差异」（186—199 页）提供计算思维测评的实证数据，可用于社团分层选拔的说理；Chiodini 与 Hauswirth 的「Programming to Learn Language Models」（41—49 页）与「双层 AI 素养」（29—40 页）讨论把大模型当教学对象而非工具，与 NOI 2026 冬令营首次 AI 辅助编程测试的方向呼应。局限必须写清：这是教育学研究论文集，不是竞赛训练书，多数论文对象是小学到高中通识课堂，对 NOI 级选手的算法能力没有直接帮助；不开放获取，只能免费看目录与摘要，正文需机构订阅或单章购买；引用时请按 DOI 标注（10.1007/978-3-032-41153-2）。","ch":8},{"no":218,"t":"OI Wiki 学习路线（C++ 基础 → CSP-J 入门级知识清单）","sub":"","kind":"讲义","auth":"","pub":"OI Wiki 社区（CC BY-SA 4.0 + SATA）","year":"2026","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["方法论","速查"],"how":"在线页面（免费，可跳转到每个知识点的站内正文）","url":"https://oi-wiki.org/contest/roadmap/","note":"OI Wiki 竞赛板块的「学习路线」页，页脚标注最近更新 2026 年 11 月 4 日，页首明确写「本文章正在编辑讨论中」。它与同站《学习资源》页（oi-wiki.org/intro/resources/，2026-01-07 更新）分工不同：资源页回答「有哪些 OJ、书、工具、课程」，是并列清单；本页回答「先学什么、后学什么、哪一层该停」，是一份带顺序和考纲边界的知识地图。当前正文分两层：第 1 层 C++ 语言基础（Hello World、变量与运算、分支与循环、数组与结构体、函数与递归），第 2 层 CSP-J 入门级（枚举与模拟、递归与分治、字符串、排序、二分与倍增、DFS/BFS 与剪枝、线性与复杂数据结构入门、DP 入门、高精度/进制/位运算/数论/组合计数），每个知识点直接链到 OI Wiki 对应正文。两处细节对自学者最有价值：一是排序一节明确写出「NOI 大纲入门级只要求选择、冒泡、插入三种，其余因初赛可能涉及而一并列出」，把考纲要求与拓展内容分开标了；二是 DP 入门把「记忆化搜索」与「递推」并列为同一状态空间的两条实现路径，避免初学者把两者当成不同算法。用法：入门阶段每周按路线勾选，勾到某格卡住就点进站内正文；教练可直接拿它当分层课表的骨架。局限：页面仍在编辑中，目前只写到 CSP-J 入门级，CSP-S / NOIP / 省选层级尚未展开，不能当完整大纲用；只给链接与一句话说明，不含题解与代码模板，与本全书正编第 22—31 章对照使用时需自己映射；内容随社区编辑变动，引用时应记录访问日期。","ch":8},{"no":219,"t":"Legend-K 的数据结构与算法笔记","sub":"","kind":"讲义","auth":"Legend-K","pub":"GitHub / 网络流传","year":"2017","lv":["CSP-S","NOIP","省选"],"use":["查漏补缺","专题突破"],"fx":["速查"],"how":"免费（网络）","url":"","note":"中文 OI 圈流传最广的个人笔记之一，模板全、排版密。适合当速查表，不适合当第一份教材。","ch":8},{"no":220,"t":"搜索方法中的剪枝优化","sub":"","kind":"论文","auth":"齐鑫","pub":"国家集训队 1999","year":"1999","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"剪枝的六种基本策略，至今没有过时。搜索题上限就靠这个。","ch":8},{"no":221,"t":"搜索顺序的选择","sub":"","kind":"论文","auth":"王知昆","pub":"国家集训队 2002","year":"2002","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"同一份代码换个搜索顺序就从 TLE 变 AC，这篇讲清了原因。","ch":8},{"no":222,"t":"背包九讲","sub":"","kind":"讲义","auth":"dd_engi（崔添翼）","pub":"网络公开 PDF","year":"2007","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["深耕","速查"],"how":"免费 PDF","url":"","note":"中文 DP 入门的第一份经典讲义。九种背包讲完，一维滚动数组的理解就彻底了。","ch":8},{"no":223,"t":"骗分导论","sub":"","kind":"讲义","auth":"OI 社区总结","pub":"网络公开","year":"2010","lv":["CSP-S","NOIP"],"use":["赛前冲刺"],"fx":["方法论"],"how":"免费","url":"","note":"听起来不正经，但「拿部分分」是 OI 的核心技能之一。省一与省队的差距常在这里。","ch":8},{"no":224,"t":"字符串算法选讲","sub":"","kind":"讲义","auth":"多位竞赛教练","pub":"网络公开","year":"2015","lv":["NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费讲义","url":"","note":"KMP、Z 函数、哈希、Manacher 串讲。2025 大纲把 Manacher 下放到提高级，这份讲义正好对上。","ch":8},{"no":225,"t":"常数优化与卡常技巧","sub":"","kind":"讲义","auth":"OI 社区总结","pub":"网络公开","year":"2018","lv":["NOIP","省选"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"","note":"循环展开、位运算替代、内存访问顺序、快读快写。省一线常常就差这一口气。","ch":8},{"no":226,"t":"浅析非完美算法在信息学竞赛中的应用","sub":"","kind":"论文","auth":"胡伟栋","pub":"国家集训队 2005","year":"2005","lv":["NOIP","省选"],"use":["赛前冲刺"],"fx":["方法论"],"how":"论文集","url":"","note":"考场上拿部分分的正确姿势。省一与省队的分差，常常就在这里。","ch":8},{"no":227,"t":"浅谈用极大化思想解决最大子矩形问题","sub":"","kind":"论文","auth":"王知昆","pub":"国家集训队 2003","year":"2003","lv":["NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"悬线法的原始文献，单调栈类问题的必读。","ch":8},{"no":228,"t":"矩阵乘法与线性递推","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2011","lv":["NOIP","省选"],"use":["专题突破"],"fx":["速查"],"how":"论文集","url":"","note":"快速幂 + 矩阵加速的标准套路。2025 大纲在 NOI 级新增线性基，可顺带一起学。","ch":8},{"no":229,"t":"NOIpaper：国家集训队论文集（1999—2025）","sub":"","kind":"论文","auth":"","pub":"GitHub","year":"2025","lv":["省选","NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"免费","url":"https://github.com/Fesdrer/NOIpaper","note":"个人维护的 GitHub 仓库，汇齐 1999—2025 年国家集训队论文集（2010—2012 年缺），按年份分目录与 PDF。相比逐年搜散落网盘，这里一次拿全，适合按专题横向扫读同一问题在不同年份的解法演进。注意版本为社区整理，引用前核对原文页码。","ch":8},{"no":230,"t":"OI 论文集精读","sub":"国家集训队论文选","kind":"论文","auth":"历届国家集训队","pub":"CCF","year":"1999-2017","lv":["省选","NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕","方法论"],"how":"公开资料集","url":"https://github.com/cjie/Competitive-Programming-Docs","note":"中国 OI 最高水平的思考沉淀。按主题挑读，比如「线段树的应用」「后缀数组」，不要按年份读。","ch":8},{"no":231,"t":"Trinkle23897 的 OI 课件","sub":"","kind":"讲义","auth":"Trinkle23897","pub":"GitHub","year":"2018","lv":["省选","NOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"免费（开源）","url":"https://github.com/Trinkle23897/oi_slides","note":"清华选手的集训课件合集，LaTeX 源码开放。多项式、生成函数、拟阵等硬专题讲得干净。","ch":8},{"no":232,"t":"acm-cheat-sheet","sub":"","kind":"讲义","auth":"开源社区","pub":"GitHub","year":"2015","lv":["省选","NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费（开源）","url":"https://github.com/Detachment/ACM-Cheat-Sheet","note":"把常用算法压成几百行的速查表，英文。赛前打印一份贴在手边，比翻书快。","ch":8},{"no":233,"t":"huzecong 的 OI 课件","sub":"","kind":"讲义","auth":"huzecong","pub":"GitHub","year":"2018","lv":["省选","NOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"免费（开源）","url":"https://github.com/huzecong/oi-slides","note":"另一套高质量集训课件，覆盖字符串、数据结构、计数。可直接改造成自己的讲课稿。","ch":8},{"no":234,"t":"分块与莫队算法","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2014","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"区间问题的暴力美学，常数友好、实现简单，考场性价比极高。","ch":8},{"no":235,"t":"动态规划优化专题","sub":"","kind":"讲义","auth":"多位竞赛教练","pub":"网络公开","year":"2016","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费讲义","url":"","note":"单调队列、斜率优化、决策单调性三件套，配真题讲最有效。","ch":8},{"no":236,"t":"动态规划的深入讨论","sub":"","kind":"论文","auth":"李刚","pub":"国家集训队 2000","year":"2000","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"从状态、阶段、决策三要素拆解，配合例题，适合系统整理 DP 框架。","ch":8},{"no":237,"t":"动态规划算法的优化技巧","sub":"","kind":"论文","auth":"毛子青","pub":"国家集训队 2001","year":"2001","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"单调队列、斜率优化、四边形不等式的源头文献之一，讲优化先讲「为什么能优化」。","ch":8},{"no":238,"t":"图论建模专题","sub":"","kind":"讲义","auth":"多位竞赛教练","pub":"网络公开","year":"2014","lv":["省选","NOI"],"use":["专题突破"],"fx":["方法论"],"how":"免费讲义","url":"","note":"从「题目怎么变成图」讲起，比直接讲算法有用得多。","ch":8},{"no":239,"t":"强连通分量与 2-SAT","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2003","lv":["省选","NOI"],"use":["专题突破"],"fx":["速查"],"how":"论文集","url":"","note":"Tarjan 的两个经典应用放一起讲，边界条件讲得清楚。","ch":8},{"no":240,"t":"把握本质，灵活运用——动态规划的深入探讨","sub":"","kind":"论文","auth":"来煜坤","pub":"国家集训队 1999","year":"1999","lv":["省选","NOI"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"把 DP 讲成「状态设计」而不是「背方程」，中文 DP 文献里最该先读的一篇。","ch":8},{"no":241,"t":"数学模型的建立、比较和应用","sub":"","kind":"论文","auth":"邵铮","pub":"国家集训队 1999","year":"1999","lv":["省选","NOI"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"建模能力的培养路径。读完再看新题，会先问「这是哪类模型」。","ch":8},{"no":242,"t":"树型动态规划","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2006","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"树上背包、换根、树的直径与重心，配题讲比看书快。","ch":8},{"no":243,"t":"状态压缩动态规划","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2005","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"状压的经典套路集：棋盘覆盖、TSP、插头 DP 的前置。","ch":8},{"no":244,"t":"离线处理思想","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2013","lv":["省选","NOI"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"CDQ 分治、整体二分、莫队的思想来源。2025 大纲把它列为 8 级考点。","ch":8},{"no":245,"t":"线段树的应用","sub":"","kind":"论文","auth":"林涛","pub":"国家集训队 2004","year":"2004","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"线段树的经典综述：区间合并、标记下传、扫描线，一篇打通。","ch":8},{"no":246,"t":"组合游戏略述——浅谈 SG 游戏的若干拓展及变形","sub":"","kind":"论文","auth":"贾志豪","pub":"国家集训队 2009","year":"2009","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"博弈论中文文献里最完整的一篇，SG 定理的适用边界讲得很细。","ch":8},{"no":247,"t":"网络流算法的应用","sub":"","kind":"论文","auth":"金恺","pub":"国家集训队 2002","year":"2002","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"建图比算法更重要。这篇的重点是「怎么把问题变成流」。","ch":8},{"no":248,"t":"解决动态统计问题的两把利刃","sub":"","kind":"论文","auth":"薛矛","pub":"国家集训队 2004","year":"2004","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"树状数组与线段树的取舍标准，讲清了「什么时候不需要线段树」。","ch":8},{"no":249,"t":"Pólya 原理及其应用","sub":"","kind":"论文","auth":"符文杰","pub":"国家集训队 2001","year":"2001","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"置换群计数的标准入门，Burnside 引理之后必读。","ch":8},{"no":250,"t":"伸展树的基本操作与应用","sub":"","kind":"论文","auth":"杨思雨","pub":"国家集训队 2004","year":"2004","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"Splay 的经典教程，旋转与区间操作的讲法至今被沿用。","ch":8},{"no":251,"t":"充分利用问题性质——例析动态规划的「个性化」优化","sub":"","kind":"论文","auth":"项荣璟","pub":"国家集训队 2003","year":"2003","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"告诉你优化不是套模板，而是抓题目自身结构。读完会少走很多弯路。","ch":8},{"no":252,"t":"具体数学讲义","sub":"","kind":"讲义","auth":"多所高校","pub":"网络公开","year":"2015","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费讲义","url":"","note":"《具体数学》的课堂版浓缩，和式、递推、生成函数三块讲得更快。","ch":8},{"no":253,"t":"动态树及其应用","sub":"","kind":"论文","auth":"袁昕颢","pub":"国家集训队 2007","year":"2007","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"LCT 应用的系统整理：路径查询、连通性维护、动态 MST。","ch":8},{"no":254,"t":"可持久化数据结构","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2012","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"主席树、可持久化并查集、可持久化 Trie 的统一视角。","ch":8},{"no":255,"t":"后缀数组","sub":"","kind":"论文","auth":"许智磊","pub":"国家集训队 2004","year":"2004","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"SA 的中文标准教程，倍增与 DC3 都讲了，先学倍增即可。","ch":8},{"no":256,"t":"后缀数组——处理字符串的有力工具","sub":"","kind":"讲义","auth":"罗穗骞","pub":"国家集训队 2009","year":"2009","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集 / PDF","url":"","note":"后缀数组中文讲解的标杆，模板与证明都给全了。","ch":8},{"no":257,"t":"多串匹配算法及其启示","sub":"","kind":"论文","auth":"朱泽园","pub":"国家集训队 2004","year":"2004","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"AC 自动机的经典引路文，从 KMP 到 Trie 图是一条自然的线。","ch":8},{"no":258,"t":"容斥原理与反演","sub":"","kind":"论文","auth":"多位集训队选手","pub":"国家集训队历年","year":"2015","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"莫比乌斯反演的直觉来源，先把容斥的「符号感」练出来。","ch":8},{"no":259,"t":"左偏树的特点及其应用","sub":"","kind":"论文","auth":"黄源河","pub":"国家集训队 2005","year":"2005","lv":["NOI"],"use":["专题突破"],"fx":["速查"],"how":"论文集","url":"","note":"可并堆的入门文献，代码短、结论清楚，直接抄结构也行。","ch":8},{"no":260,"t":"平面图在信息学中的应用","sub":"","kind":"论文","auth":"刘才良","pub":"国家集训队 2003","year":"2003","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"平面图转对偶图求最小割，思路漂亮且考过多次。","ch":8},{"no":261,"t":"提交答案题与交互题","sub":"","kind":"讲义","auth":"多位集训队选手","pub":"网络公开","year":"2016","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["方法论"],"how":"免费讲义","url":"","note":"这两类题在 NOI 与 IOI 中占比不小，但普通题单几乎不覆盖，必须单独准备。","ch":8},{"no":262,"t":"数值分析在竞赛中的简单应用","sub":"","kind":"论文","auth":"侯启明","pub":"国家集训队 2003","year":"2003","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"三分、模拟退火、爬山的前置知识，非完美算法的理论依据。","ch":8},{"no":263,"t":"数据结构的联合——块状链表","sub":"","kind":"论文","auth":"蒋炎岩","pub":"国家集训队 2005","year":"2005","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"分块思想的中文源头文献之一，sqrt 分解的所有变体几乎都能从这里长出来。","ch":8},{"no":264,"t":"最小割模型在信息学竞赛中的应用","sub":"","kind":"论文","auth":"胡伯涛","pub":"国家集训队 2007","year":"2007","lv":["NOI"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"最小割建模的经典总结，最大权闭合子图、二者取一等模型都在这里。","ch":8},{"no":265,"t":"构造题策略","sub":"","kind":"讲义","auth":"多位集训队选手","pub":"网络公开","year":"2017","lv":["NOI"],"use":["专题突破"],"fx":["方法论"],"how":"免费讲义","url":"","note":"构造题没有通法，但有常见套路：归纳、对称、奇偶分类、增量调整。","ch":8},{"no":266,"t":"母函数的性质及应用","sub":"","kind":"论文","auth":"毛杰明","pub":"国家集训队 2009","year":"2009","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"从多项式乘法到生成函数，2025 大纲 9 级考点，建议配合 NTT 一起学。","ch":8},{"no":267,"t":"猜数问题的研究","sub":"","kind":"论文","auth":"张宁","pub":"国家集训队 2003","year":"2003","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"交互题与信息论结合的范例，理解「每次询问能获得多少信息」。","ch":8},{"no":268,"t":"答案只有一个——浅谈问答式交互问题","sub":"","kind":"论文","auth":"高正宇","pub":"国家集训队 2003","year":"2003","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"交互题中文文献里最系统的一篇，IOI 风格必备。","ch":8},{"no":269,"t":"维护森林连通性——动态树","sub":"","kind":"论文","auth":"陈首元","pub":"国家集训队 2006","year":"2006","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"论文集","url":"","note":"LCT 的中文入门文献之一。难度高，先确保 Splay 熟练。","ch":8},{"no":270,"t":"计算几何讲义","sub":"","kind":"讲义","auth":"谢迪","pub":"网络公开","year":"2012","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费 PDF","url":"","note":"凸包、半平面交、旋转卡壳的中文经典讲义，代码可直接复用。","ch":8},{"no":271,"t":"论随机化算法的原理与设计","sub":"","kind":"论文","auth":"周咏基","pub":"国家集训队 1999","year":"1999","lv":["NOI"],"use":["专题突破"],"fx":["方法论"],"how":"论文集","url":"","note":"随机化不是碰运气，而是把错误率控制在可接受范围。思维方式比代码重要。","ch":8},{"no":272,"t":"CCF NOI 2026 笔试题库","sub":"","kind":"真题","auth":"","pub":"中国计算机学会（NOI 竞赛办公室）","year":"2026","lv":["CSP-J","CSP-S","NOI"],"use":["查漏补缺","赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.noi.cn/xw/2026-06-16/903684.shtml","note":"2026 年 6 月 16 日由 NOI 竞赛办公室发布，正文即一份《NOI 2026 基础知识题库》PDF 附件，可直接下载。NOI 正赛第一天为笔试，CSP 第一轮也是纯客观题，两处考的是同一类「计算机基础 + 算法常识 + 竞赛规则」。这份题库的不可替代性在于口径：市面上初赛模拟卷多为机构自编，知识点边界与官方大纲常有偏差，而它是命题方自己给出的样题范围，可用来给「刷了多少套模拟卷」这件事定标。用法建议：先按套限时做一遍定位错项，再回到大纲对应条目补，不要当题海刷——题库体量有限，反复做只会记住答案。","ch":9},{"no":273,"t":"CSP-J/S 2025 题目及数据（入门组 4 题 + 提高组 4 题）","sub":"","kind":"真题","auth":"","pub":"CCF NOI 官网 · 历年资料","year":"2025","lv":["CSP-J","CSP-S"],"use":["实战训练","查漏补缺"],"fx":["实战","速查"],"how":"免费下载（CC BY-NC 授权）","url":"https://www.noi.cn/zxzy/lnzl/jszl/2025-12-15/854079.shtml","note":"CSP-J/S 2025 第二轮（2025 年 11 月 1 日）的官方题面与全量数据，2025 年 12 月 15 日公开。入门组四题：number（拼数）、seat（座位）、xor（异或和）、polygon（多边形）；提高组四题：club（社团招新）、road（道路修复）、replace（谐音替换）、employ（员工招聘）。两组各自一个题面 PDF、四份数据压缩包，入门组与提高组同一天上下午各一场，正好可以拼成一次完整的「一天两场」模拟。这套数据的实际用处在于「按测试点定位失分」：CSP 的测试点通常按特殊性质分档（小数据、特殊图、无特殊性质），把八个数据包按档跑一遍，就能看出自己丢的是暴力分、特殊性质分还是正解分——这三类失分对应的补法完全不同（补代码熟练度 / 补题型敏感度 / 补算法）。入门组第四题与提高组第三、四题是分水岭，建议单独做「部分分最大化」训练：先写稳 40—60 分的暴力与特判，再考虑正解，这本身就是 CSP 赛制下最划算的策略。局限：与所有 CSP 年份一样，官方不配套题解；入门组题面强调「按题意模拟」，纸面看似简单但实现细节多，纯看题解容易低估其代码量。","ch":9},{"no":274,"t":"CSP-J/S 2026 第二轮认证测试数据（入门组 + 提高组）","sub":"","kind":"真题","auth":"","pub":"中国计算机学会","year":"2026","lv":["CSP-J","CSP-S"],"use":["实战训练","查漏补缺"],"fx":["实战"],"how":"免费","url":"https://www.noi.cn/xw/2026-11-05/945674.shtml","note":"2026 年 11 月 5 日随《关于 CSP-J/S 2026 第二轮成绩和申诉的通知》发布，附件为入门组（J）与提高组（S）两套完整测试数据 zip，可直接下载。三个用法：赛后复现失分点（本地重测能区分是算法错、常数超时还是边界漏判）、教练做同一题不同解法的常数对比、把当年真题改造成校内模拟赛。配套时间窗要记住：申诉 11 月 5 日 16:00—11 月 8 日 13:00，缴费截止 11 月 8 日 18:00，申诉须经指导教师提交且每题只有一次机会，11 月 13 日后可查结果；申诉不受理「与标准环境有出入」「感觉判错」这类无自测数据的请求，规范做法是附上逐测试点的用时、内存与比对结论。数据本身不含题面，题面需另从当轮试题页获取。","ch":9},{"no":275,"t":"CSP-J/S 历年认证题","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn / 洛谷","year":"2019-至今","lv":["CSP-J","CSP-S"],"use":["赛前冲刺"],"fx":["实战"],"how":"官网 / 题库","url":"https://www.luogu.com.cn/","note":"第一轮为笔试，第二轮为上机。两轮都要练，第一轮淘汰率不低。","ch":9},{"no":276,"t":"CSP-J/S 第一轮真题","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn","year":"2019","lv":["CSP-J","CSP-S"],"use":["赛前冲刺","查漏补缺"],"fx":["实战"],"how":"免费 / 本站真题库","url":"https://www.noi.cn/xw/","note":"笔试（阅读程序、完善程序）是很多人翻车的地方。近五年卷子必须整套掐时间做，错题按知识点归类。","ch":9},{"no":277,"t":"JOI 2026/2027 一次预选（第 26 回日本信息学奥赛第一轮）题目·解说·解答例","sub":"","kind":"真题","auth":"","pub":"情報オリンピック日本委員会（JOI 官网）","year":"2026","lv":["CSP-J","CSP-S"],"use":["实战训练","查漏补缺"],"fx":["实战"],"how":"免费（官网下载，含评分数据）","url":"https://www2.ioi-jp.org/joi/2026/2027-yo1/","note":"第 26 回日本信息学奥林匹克（JOI 2026/2027）一次预选的两回比赛已分别于 2026 年 9 月 12 日、10 月 25 日结束，官网在 9 月 23 日、10 月 28 日先后放出全部材料：6 道题的问题文、逐题解说、C++ 与 Python 两份解答例，以及评分用输入数据与正解文件的 ZIP 包，第一回另附完整统计。赛制值得国内选手注意：一次预选共 6 题、每题 100 分、每题含若干小課題（子任务）并按子任务给部分分，限时 80 分钟（14:00—15:20）；前 3 题是「基本题」，难度对标上一年度一次预选的前 3 题，考的是能否把含循环的基本程序写对；后 3 题是「应用题」，难度对标上一年度一次预选第 4 题与二次预选前 2 题，考的是能否设计出高效算法。第一回六题依次为「ノート（笔记本）」「最小除外値」「スポーツ大会」「倍数ペア」「JOI ブロック」「お菓子配り」，参赛 1621 人，六题平均分为 86.1 / 67.6 / 36.9 / 39.0 / 22.6 / 9.5，满 600 分者 137 人，B 级基准线 300 分（授「敢闘賞」）；第二回六题为「かるた」「けんけんぱ」「ジェットコースター」「ペア」「文字列を探せ」「ペア 2」。用法的关键在分数曲线：后三题平均分断崖式下降（第 6 题只有 9.5 分），说明区分度全压在部分分上——这恰好是国内 CSP-J/S 第二轮的得分结构，拿它练「先写暴力拿子任务分、再逐档优化」比刷完整题更对症；一场 80 分钟 6 题也接近初赛与复赛混合的节奏，适合做赛前限时套题。局限：题面与解说全为日文（解答例代码可直接读），小課題的约束必须逐条读懂才敢下笔；覆盖面与 NOI 大纲对不上（无高级数据结构、无复杂图论），只适合 CSP-J/S 段，不能当省选训练。","ch":9},{"no":278,"t":"USACO 历年试题","sub":"","kind":"真题","auth":"USACO","pub":"usaco.org","year":"1992-至今","lv":["CSP-J","CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"官网免费","url":"https://usaco.org/","note":"四级分层清晰，题目英文表述规范，是练读题与基础算法的高性价比题库。","ch":9},{"no":279,"t":"《CCF 信息学奥赛入门篇》练习指导","sub":"","kind":"题解","auth":"","pub":"机械工业出版社（中国计算机学会组编）","year":"2025","lv":["CSP-J"],"use":["查漏补缺","实战训练"],"fx":["实战"],"how":"纸质书","url":"http://www.wsgph.com/bookshow.asp?id=3097887","note":"廖晓刚、何哲华编，2025 年 12 月第 1 版，ISBN 978-7-111-79342-7，定价 59 元，约 180 页。逐题解析《CCF 信息学奥赛入门篇》的全部练习，七章对应主教材：编程基础、数据的存储与读入、选择执行、反复执行、批量存储（数组与字符串）、模块化程序设计，末章专讲 NOI 系列竞赛相关规定（文件读写、评测与纪律）。必须与主教材配套：单独读它只是题解集，缺语法铺垫；只读主教材不做题，读入格式、边界处理、多组数据这些坑踩不全。适合 CSP-J 第一轮结束后、第二轮前两个月做查漏，也可作为入门班课后作业的答案册。","ch":9},{"no":280,"t":"信息学奥赛 3：历年真题解析与拉分解题思维训练","sub":"","kind":"题解","auth":"","pub":"北京大学出版社","year":"2026","lv":["CSP-J"],"use":["查漏补缺","赛前冲刺"],"fx":["实战","方法论"],"how":"纸质书","url":"https://www.books.com.tw/products/CN18145540","note":"王健伟著，2026 年 8 月第 1 版，ISBN 978-7-301-37272-2，508 页，定价 129 元，为该系列三册中的第三册。把 2015—2024 年 CSP-J 初赛与复赛真题按年份分章，逐题给解析，并对解析里出现的新概念就地补充；主线是所谓「拉分题」——每套卷中区分一等与二等的 1—2 题，先拆解题意与数据范围，再落到可编译代码。适合已过语法、目标 CSP-J 一等的学生做真题闭环，也可供教练挑例题。局限：真题只到 2024 年，2025 年后的新题型需另配当年题面。","ch":9},{"no":281,"t":"信息学奥赛 CSP 通关之路：CSP-J/S 第一轮原创全真模拟试卷集（2026）","sub":"","kind":"真题","auth":"","pub":"人民邮电出版社","year":"2026","lv":["CSP-J","CSP-S"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=5081795","note":"王津、夏宗强等编著，2026 年 7 月第 1 版，ISBN 9787115700209，16 开 158 页、23 万字，定价 59.80 元。结构极简：普及组 CSP-J 2026 初赛模拟卷 10 套 + 提高组 CSP-S 10 套，共 20 套原创卷，逐套按第一轮真题的题型与分值配比（单项选择、程序阅读、程序填空）编制，成套独立、不混编。纸质书只印试题，逐题详细解析放在线上（扫码或图灵社区下载），另设读者群同步各省报名与政策。据出版方说明，2026 版针对近三年 CCF 初赛的变化补充了 Linux 命令、指针、高精度、倍增 LCA、组合计数这几个新出现的考点，并强化了 DP、数论、图论的高频难点。正确的用法是整卷计时：一次两小时、按考场规则做完整套，再对解析并把错因归类到知识点，回到教材补；拆成单题刷会失去它唯一的长处——初赛考的是速度与准确率，不是单题难度。局限有三：原创卷终究不是真题，命题团队的口径与 CCF 科学委员会未必一致；解析在线上，断网或改版后有失效风险；158 页摊 20 套卷，平均每套不足 8 页，题量比真实卷面略薄，适合当节奏训练而非题海。","ch":9},{"no":282,"t":"信息学奥赛 CSP-J 初赛通关手册：10 年真题 + 10 套模拟精练精讲","sub":"","kind":"真题","auth":"","pub":"人民邮电出版社","year":"2025","lv":["CSP-J"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://book.cppinfo.cn/Encyclopedias/home/index?id=4817121","note":"左凤鸣主编，2025 年 1 月第 1 版（2025 年 10 月重印），ISBN 9787115654670，16 开 236 页，定价 69.80 元，中图法 TP311.1-44。四部分：一是配套题库系统说明（佐助题库的初赛检测系统，可在线判分）；二是 10 套真题——2014—2018 年 NOIP 普及组初赛按 CSP 新题型改编，接 2019—2023 年 CSP-J1 原卷；三是 10 套 CSP-J 初赛模拟；四是参考答案，逐题解析为电子版，凭书内二维码或在线资源获取。与同期《信息学奥赛初赛全解》《CCF CSP 第一轮认证一本通（第 2 版）》的分工很清楚：那两本按知识点组织，本书按整卷组织，且 10 年真题的时间跨度是三者中最长的，适合做年份纵向对比——同一考点在不同年份落在选择题、阅读程序还是完善程序，只有把整卷按年排开才看得出来。做法建议：真题从 2019 年往前做，越早的卷子改编幅度越大、参考价值递减；模拟卷留到考前两周整卷计时，一次两小时按考场规则走。局限：解析在线上，改版或断网有失效风险；题目止于 2023 年，2024—2026 三届需另配；答案册只给答案不给过程，自学时要配一本知识点书对照。","ch":9},{"no":283,"t":"信息学奥赛一本通","sub":"训练指导教程","kind":"题解","auth":"董永建 等","pub":"科学技术文献出版社","year":"2014","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["实战"],"how":"纸质书","url":"","note":"与一本通同步的题解册，题量足，适合按章刷。","ch":9},{"no":284,"t":"洛谷主题题单","sub":"","kind":"真题","auth":"洛谷社区","pub":"luogu.com.cn","year":"2018-至今","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["体系学习","实战训练"],"fx":["实战"],"how":"免费","url":"https://www.luogu.com.cn/training/list","note":"社区维护的专题题单，比官方题库更好用，因为顺序是有人验证过的。","ch":9},{"no":285,"t":"算法竞赛入门经典——习题与解答","sub":"","kind":"题解","auth":"刘汝佳","pub":"清华大学出版社","year":"2013","lv":["CSP-J","CSP-S"],"use":["查漏补缺"],"fx":["实战"],"how":"纸质书","url":"","note":"紫书课后题的标准答案与思路，自学时最缺的就是这个。","ch":9},{"no":286,"t":"算法竞赛宝典","sub":"基础算法与数据结构","kind":"题解","auth":"张新华","pub":"清华大学出版社","year":"2012","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["实战"],"how":"纸质书","url":"","note":"题量大、分类细，适合作为「刷题清单」使用，讲解略简。","ch":9},{"no":287,"t":"背包问题专题","sub":"","kind":"题解","auth":"OI Wiki / 洛谷题单","pub":"oi-wiki.org","year":"2018","lv":["CSP-J","CSP-S","NOIP"],"use":["专题突破","入门自修"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/knapsack/","note":"01/完全/多重/分组/树上背包的完整体系。背包是 DP 的第一道门槛，配合「背包九讲」一起看效果最好。","ch":9},{"no":288,"t":"CCF CSP 例题解析与实战技巧：算法应用","sub":"","kind":"题解","auth":"","pub":"机械工业出版社（中国计算机学会组编）","year":"2026","lv":["CSP-S","NOIP"],"use":["专题突破","实战训练"],"fx":["实战"],"how":"纸质书","url":"https://ebooks.cmpbook.com/ccgy/detail?id=30252","note":"中国计算机学会组编，2026 年 8 月 28 日第 1 版，ISBN 978-7-111-81626-3，定价 59 元。专攻 CCF CSP 认证的第四题（最难一题），六章对应六类考点：标准模板库、数学基础、搜索、图论、动态规划、线段树，并解析 2013—2025 年部分真题。体例是本书最值钱的地方——同一道题先给暴力做法与得分，再逐步推到正解与满分，把「怎么从 40 分想到 100 分」的过程摊开写，而不是只贴最终代码。注意辨析：这里的 CSP 指 CCF 面向高校与从业者的软件能力认证，不是 CSP-J/S；但第四题难度与 CSP-S、NOIP 的后两题同段，思路迁移完全成立。适合已能稳定拿到 CSP-S 前两题、卡在后两题部分分的学生。","ch":9},{"no":289,"t":"Programming Challenges","sub":"","kind":"题解","auth":"Steven S. Skiena、Miguel A. Revilla","pub":"Springer","year":"2003","lv":["CSP-S","NOIP"],"use":["实战训练"],"fx":["实战"],"how":"纸质 / 电子书","url":"","note":"与 UVa 题库对应的竞赛题解集，英文写作规范，适合练读题。","ch":9},{"no":290,"t":"信息学奥赛一本通 · 高手训练","sub":"","kind":"题解","auth":"黄新军、董永建","pub":"科学技术文献出版社","year":"2021","lv":["CSP-S","NOIP","省选"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"纸质书","url":"","note":"以题带练的分册，题目按难度成组。适合提高组真题刷完之后、需要「加练」的那一段。","ch":9},{"no":291,"t":"区间与序列 DP 专题","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/interval/","note":"区间 DP 的状态设计与断点枚举。石子合并、括号匹配、矩阵链是必做三件套。","ch":9},{"no":292,"t":"单调栈与单调队列","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/ds/monotonous-queue/","note":"滑动窗口、最大子矩形、悬线法。代码极短但边界易错，必须手写十遍以上。","ch":9},{"no":293,"t":"字符串哈希与 KMP","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/string/kmp/","note":"哈希要会双模 + 随机底数防卡；KMP 的 next 数组要能默写。字符串题的入场券。","ch":9},{"no":294,"t":"树形 DP 专题","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/tree/","note":"换根、树上背包、树上依赖。树形 DP 是最稳定的得分点，必须练到「看见树就想状态」。","ch":9},{"no":295,"t":"树状数组","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["速查"],"how":"免费","url":"https://oi-wiki.org/ds/fenwick/","note":"代码最短的区间数据结构，支持单点改区间查与区间改单点查。二维、权值树状数组也要会。","ch":9},{"no":296,"t":"算法思维：竞赛真题精选精讲（第 2 版）","sub":"","kind":"题解","auth":"","pub":"人民邮电出版社","year":"2026","lv":["CSP-S","NOIP","省选"],"use":["体系学习","专题突破"],"fx":["方法论","深耕"],"how":"纸质书","url":"https://book.douban.com/isbn/9787115683649/","note":"2026 年 1 月第 2 版，ISBN 9787115683649，386 页。选 IOI、NOIP、USACO、CCC、CCO、ICPC、DWITE 等赛事的 28 道题，每题统一按「问题描述—输入—输出—解决方案」四段展开，十章覆盖哈希表、树与递归、记忆化与动态规划、图与广度优先搜索、加权图最短路、二分搜索、堆与线段树、并查集、随机化算法。示例代码用 C 写，但刻意回避语言特性，C++、Java、Python 都能直接迁移——对初中起步、语言习惯还没定型的选手友好。与国内多数题解书最大的差别在「解决方案」这一段：先推「为什么这样建模、暴力卡在哪、换哪个不变量才能降复杂度」，再落到代码，因此更适合在学完模板之后练「拿到题先想什么」，而不是当模板手册查。局限要说清楚：28 道题撑不起完整知识体系，图论只到 BFS 与最短路，网络流、树剖、数论进阶一概没有；C 代码需要读者自己改写成考场写法（快读、STL 容器、long long），照抄会不适应；章节按「数据结构」而非「考点难度」组织，想按省选考点检索时不如专题书顺手。","ch":9},{"no":297,"t":"算法竞赛入门经典——训练指南","sub":"白书","kind":"题解","auth":"刘汝佳、陈锋","pub":"清华大学出版社","year":"2012","lv":["CSP-S","NOIP"],"use":["专题突破","实战训练"],"fx":["实战"],"how":"纸质书","url":"","note":"紫书的配套题集，按专题成组给题。适合「学完一块马上打透一块」。","ch":9},{"no":298,"t":"JOI 2025/2026 二次预选（第 25 回日本信息学奥赛第二轮）题目·解说·数据","sub":"","kind":"真题","auth":"","pub":"日本信息学奥林匹克委员会（IOI-JP）","year":"2025","lv":["NOIP","省选"],"use":["赛前冲刺","实战训练"],"fx":["实战","方法论"],"how":"在线页面（免费下载题面 HTML、解说 PDF、C++/Python 解答例与 199MB 数据 ZIP）","url":"https://www2.ioi-jp.org/joi/2025/2026-yo2/index.html","note":"2025 年 12 月 7 日 13:00—16:00 线上举行，6 题各 100 分共 600 分，题面、逐题解说 PDF、C++ 与 Python 解答例、评分用输入输出数据（ZIP 199MB）全部公开，另有 AtCoder 比赛页（joi2026-yo2）。官方统计给得很全，正好可以用来判断难度梯度：有资格者 1379 人，A 级线 390 分、147 人过线（高校二年级以下 129 人、三年级 18 人），JOI 部门进 132 人、JOIG 部门线 146 分进 32 人、特别部门 390 分进 28 人；总分分布为 600 分 20 人、500—599 分 43 人、400—499 分 77 人、300—399 分 141 人、200—299 分 134 人、100—199 分 277 人、1—99 分 549 人、0 分 138 人。逐题平均分是 57.8 / 41.7 / 31.7 / 13.4 / 7.7 / 3.2，第 5、6 题满分人数只有 74 与 20——这是一份「前四题按 NOIP 难度递进、后两题直逼省选压轴」的标准梯度卷。命题者为米田宽峻与米田优峻（第 1 题）、米山瑛士（第 2、3 题）、平木康杰（第 4 题）、蜂矢伦久与米山瑛士（第 5 题）、蜂矢伦久（第 6 题），米田优峻即《算法竞赛黄金法则》作者，其命题风格（长题面、强子任务）与书中例题一致。用法：6 题 3 小时、按子任务给分的赛制与国内二轮认证接近，可直接当模拟赛；官方解说 PDF 给出满分做法与部分分策略，比只给代码的题解更适合讲评。与已收《JOI 2026/2027 一次预选》互补——一次预选 80 分钟考语法与基础算法，二次预选才是真正的算法竞赛难度，两页连起来正好覆盖日本选拔的两级。局限：题面为日文（可配合洛谷 P14795—P14800 的中文翻译），解说 PDF 亦为日文；数据 ZIP 近 200MB，校内分发需先裁剪。","ch":9},{"no":299,"t":"NOIP 2025 题目及数据（糖果店 / 清仓甩卖 / 树的价值 / 序列询问）","sub":"","kind":"真题","auth":"","pub":"CCF NOI 官网 · 历年资料","year":"2025","lv":["NOIP","省选"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费下载（CC BY-NC 授权）","url":"https://www.noi.cn/zxzy/lnzl/jszl/2025-12-15/854083.shtml","note":"2025 年 11 月 29 日举行的 NOIP 2025 的官方题面与全量测试数据，2025 年 12 月 15 日与其他年度资料一同在 NOI 官网「历年资料」栏目公开。联赛只有一天四题：candy（糖果店）、sale（清仓甩卖）、tree（树的价值）、query（序列询问），题面合并在一个 PDF 里，每题另有独立的数据 zip 包，结构比 OJ 上的搬运版干净得多——子任务划分与官方分值、输入输出文件名、编译选项都写在题面首页，可以直接按 NOI Linux 2.0 的评测方式在本地复现分数。用法上，NOIP 真题的价值有两层：一是它是省选资格的直接门槛（按 CCF 关于 NOI 2027 省内选拔的规定，NOIP 成绩在省选总成绩中的权重不得低于 30%），二是四题的难度梯度非常稳定——前两题是「稳分题」，第三题常是区分度所在，第四题是省队线，按这个梯度做限时训练，比零散刷题更能校准「一道题该给我多少分」的自我判断。建议的练法：先按 3.5 小时整套限时做，再只对第三、四题做「不写代码的口头解法」训练——这两题失分的主因往往不是不会，而是没在赛时想到正解方向。局限：官网只给题面与数据，不含官方题解；中文讲解要另找（洛谷题号、各省教练的赛后分析），且不同来源的子任务分值与官方偶有出入，对分数时以本页数据包为准。","ch":9},{"no":300,"t":"NOIP 历年真题（2011 起）","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn / 洛谷","year":"2011","lv":["NOIP"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://www.luogu.com.cn/problem/list","note":"提高组与普及组各一套/年。NOIP 是「最像考题的题」，做完十年卷子对题型分布的直觉就建立了。","ch":9},{"no":301,"t":"NOIP 历年试题","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn / 洛谷","year":"1995-至今","lv":["NOIP"],"use":["赛前冲刺"],"fx":["实战"],"how":"官网 / 题库","url":"https://www.luogu.com.cn/","note":"提高组真题是最贴近省一线难度的材料，建议按年份整套限时做。","ch":9},{"no":302,"t":"二分图匹配（匈牙利 / Hopcroft–Karp / KM）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/graph/bi-graph/","note":"二分图最大匹配、最小点覆盖、最大独立集、最小路径覆盖四个定理必须能互相推导出来。","ch":9},{"no":303,"t":"博弈论与 SG 函数","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/math/game-theory/","note":"Nim、Anti-Nim、阶梯博弈、SG 定理。读贾志豪《组合游戏略述——浅谈SG游戏的若干拓展及变形》。","ch":9},{"no":304,"t":"数位 DP 专题","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/number/","note":"按位确定 + 记忆化。套路性极强，属于「学会就白送分」的专题，性价比最高的一类。","ch":9},{"no":305,"t":"状压 DP 专题","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/state/","note":"子集枚举、轮廓线、插头 DP 的入口。核心是把「集合」编码成整数，再谈转移优化。","ch":9},{"no":306,"t":"矩阵与线性递推","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选"],"use":["专题突破"],"fx":["速查"],"how":"免费","url":"https://oi-wiki.org/math/linear-algebra/matrix/","note":"矩阵快速幂 + 常系数齐次递推的 BM 优化。看到「1e18 项递推」就该条件反射想到它。","ch":9},{"no":307,"t":"线段树与懒标记","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/ds/seg/","note":"区间操作的通用武器。标记下传的顺序（先乘后加）是唯一的坑，写清楚注释就不出错。","ch":9},{"no":308,"t":"2-SAT 与差分约束","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["速查"],"how":"免费","url":"https://oi-wiki.org/graph/2-sat/","note":"两类「把逻辑/不等式转成图」的模型。2-SAT 用 Tarjan 判可行并输出方案，模板固定。","ch":9},{"no":309,"t":"AC 自动机","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/string/ac-automaton/","note":"Trie + fail 树。多模式串匹配的标准解，配合 fail 树上 dfs 序 + 树状数组能解决大部分变种。","ch":9},{"no":310,"t":"ACM 国际大学生程序设计竞赛系列 · 题目与解读","sub":"","kind":"题解","auth":"俞勇 主编","pub":"上海交通大学出版社","year":"2013","lv":["省选","NOI"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"纸质书","url":"","note":"第三册是题集，按专题给题并附解读。题量大、难度梯度平缓，适合当省选阶段的补充题库。","ch":9},{"no":311,"t":"AHOI 安徽省选","sub":"","kind":"真题","auth":"安徽省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 AHOI","url":"https://www.luogu.com.cn/problem/list","note":"难度中等偏上，数据结构和图论题较多。省选初期用来积累「完整做出三题」的信心很合适。","ch":9},{"no":312,"t":"APIO 2026 中国区活动题目及数据","sub":"","kind":"真题","auth":"","pub":"中国计算机学会","year":"2026","lv":["省选","NOI"],"use":["实战训练"],"fx":["实战"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2026-05-10/890784.shtml","note":"2026 年 5 月 10 日发布，含 APIO 2026 中国区试题、数据与讲评资料。APIO 以交互题、构造题比重高著称，与国内赛制差异明显，是训练「非传统题型」最经济的官方来源。","ch":9},{"no":313,"t":"BJOI 北京队选拔","sub":"","kind":"真题","auth":"北京市队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费 / 洛谷题库搜 BJOI","url":"https://www.luogu.com.cn/problem/list","note":"难度偏高、创新题多。北京队名额少，卷子历来不手软，是省选后期的拔高题源。","ch":9},{"no":314,"t":"DP 优化专题（单调队列/斜率/决策单调性）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/opt/","note":"把 O(n²) 打到 O(n log n) 或 O(n)。省选与 NOI 的分水岭，也是集训队论文出现频率最高的主题。","ch":9},{"no":315,"t":"FJOI 福建省选","sub":"","kind":"真题","auth":"福建省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 FJOI","url":"https://www.luogu.com.cn/problem/list","note":"题面长、信息量大，考查「从长题面里抽模型」的能力。近年与联合省选并轨，早期卷子仍有价值。","ch":9},{"no":316,"t":"GDOI 广东省选","sub":"","kind":"真题","auth":"广东省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 GDOI","url":"https://www.luogu.com.cn/problem/list","note":"本省选手的必刷卷。广东题偏应用，与 NOIP 提高组衔接较顺，适合作为省选入门的第一批真题。","ch":9},{"no":317,"t":"HAOI 河南省选","sub":"","kind":"真题","auth":"河南省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 HAOI","url":"https://www.luogu.com.cn/problem/list","note":"题风朴实，少有偏题，适合作为限时套卷的「热身卷」。","ch":9},{"no":318,"t":"HEOI 河北省选","sub":"","kind":"真题","auth":"河北省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 HEOI","url":"https://www.luogu.com.cn/problem/list","note":"部分年份与河南联考。数据结构题实现量偏大，练「代码耐力」的好材料。","ch":9},{"no":319,"t":"HNOI 湖南省选","sub":"","kind":"真题","auth":"湖南省队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 HNOI","url":"https://www.luogu.com.cn/problem/list","note":"思维题比例高，常出现需要「转化模型」的题。湖南是竞赛强省，题目质量整体在线。","ch":9},{"no":320,"t":"JSOI 江苏省选","sub":"","kind":"真题","auth":"江苏省队选拔","pub":"洛谷题库","year":"2005","lv":["省选"],"use":["实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库搜 JSOI","url":"https://www.luogu.com.cn/problem/list","note":"风格稳健，难度分布均匀，很少出偏怪题。适合作为省选第一轮系统训练的题源。","ch":9},{"no":321,"t":"Manacher 与回文自动机","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["速查"],"how":"免费","url":"https://oi-wiki.org/string/manacher/","note":"2025 大纲把 Manacher 从 NOI 级下放到提高级，必须提前学。PAM 用来统计回文出现次数。","ch":9},{"no":322,"t":"SCOI 四川省选","sub":"","kind":"真题","auth":"四川省队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"免费 / 洛谷题库搜 SCOI","url":"https://www.luogu.com.cn/problem/list","note":"DP 与计数题见长，部分年份难度接近 NOI。想练「推式子」就该从 SCOI 挑。","ch":9},{"no":323,"t":"SDOI 山东省选","sub":"","kind":"真题","auth":"山东省队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"免费 / 洛谷题库搜 SDOI","url":"https://www.luogu.com.cn/problem/list","note":"题量大、套路全、数据结构比重高。是「按专题刷省选题」时最好的骨架题源。","ch":9},{"no":324,"t":"SHOI 上海队选拔","sub":"","kind":"真题","auth":"上海市队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["赛前冲刺","专题突破"],"fx":["实战"],"how":"免费 / 洛谷题库搜 SHOI","url":"https://www.luogu.com.cn/problem/list","note":"以构造、交互、数学味著称。做 SHOI 常能补上「只会套路不会想」的短板。","ch":9},{"no":325,"t":"ZJOI 浙江省选","sub":"","kind":"真题","auth":"浙江省队选拔","pub":"洛谷题库","year":"2005","lv":["省选","NOI"],"use":["赛前冲刺","专题突破"],"fx":["实战"],"how":"免费 / 洛谷题库搜 ZJOI","url":"https://www.luogu.com.cn/problem/list","note":"公认难度天花板之一，出题风格偏重思维与实现细节。ZJOI 能稳定做出两题，省队基本稳。","ch":9},{"no":326,"t":"十二省联考","sub":"","kind":"真题","auth":"多省联合命题","pub":"洛谷题库","year":"2019","lv":["省选","NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费 / 洛谷题库搜十二省联考","url":"https://www.luogu.com.cn/problem/list","note":"2019、2020 两届，规模最大的一次省际联考。题目质量高、区分度好，是省选模拟的黄金卷。","ch":9},{"no":327,"t":"可持久化数据结构","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/ds/persistent-seg/","note":"主席树、可持久化并查集、可持久化 Trie。核心思想只有一句「只复制被修改的结点」。","ch":9},{"no":328,"t":"后缀数组与后缀自动机","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/string/sa/","note":"SA 求 height 数组、SAM 求本质不同子串。先读罗穗骞《后缀数组——处理字符串的有力工具》再动手。","ch":9},{"no":329,"t":"国家集训队论文配套题","sub":"","kind":"真题","auth":"历年集训队","pub":"论文集","year":"1999-2017","lv":["省选","NOI"],"use":["专题突破"],"fx":["实战"],"how":"论文集","url":"","note":"论文里的例题往往就是当年最难的原题，读完论文顺手做掉。","ch":9},{"no":330,"t":"多项式与 NTT","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/math/poly/ntt/","note":"卷积、求逆、开根、exp、ln 全套。模板长，务必封装成结构体并测过随机数据。","ch":9},{"no":331,"t":"平衡树（Treap / Splay / FHQ）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/ds/treap/","note":"有序集合的全功能实现。先写无旋 Treap（FHQ），再学 Splay 的区间操作，最后看替罪羊树。","ch":9},{"no":332,"t":"插头 DP（连通性状态压缩）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/dp/plug/","note":"棋盘上的回路/路径计数专用。模板固定，但状态编号（最小表示法）必须自己写熟一遍。","ch":9},{"no":333,"t":"树链剖分（HLD）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/graph/hld/","note":"把树上路径问题转成序列问题。与线段树组合后能解决一大类「路径修改 + 路径查询」。","ch":9},{"no":334,"t":"网络流（最大流 / 最小割 / 费用流）","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/graph/flow/","note":"建模远比算法难。先刷「网络流 24 题」建立模型直觉，再读胡伯涛《最小割模型在信息学竞赛中的应用》。","ch":9},{"no":335,"t":"联合省选（CCF 统一命题）","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn","year":"2020","lv":["省选"],"use":["赛前冲刺","实战训练"],"fx":["实战"],"how":"免费 / 洛谷题库","url":"https://www.luogu.com.cn/problem/list","note":"2020 年起省选由 CCF 统一命题，分 A/B 卷。这是目前省选训练的第一题源，两年内的卷子必须整套限时做。","ch":9},{"no":336,"t":"莫比乌斯反演与杜教筛","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/math/number-theory/mobius/","note":"数论题的必经之路。先把 ∑μ(d) 的套路推熟，再看杜教筛的 O(n^{2/3}) 复杂度分析。","ch":9},{"no":337,"t":"虚树","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/graph/virtual-tree/","note":"2025 大纲由 10 级降到 8 级，重要度上升。多次询问少量关键点的树形 DP 必用。","ch":9},{"no":338,"t":"计算几何基础与凸包","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/geometry/","note":"叉积、旋转卡壳、半平面交、最小圆覆盖。精度是最大敌人，能用整数就不用浮点。","ch":9},{"no":339,"t":"APIO 历年试题","sub":"","kind":"真题","auth":"APIO","pub":"apio 官网 / oj.uz","year":"2007-至今","lv":["NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"官网 / oj.uz","url":"https://oj.uz/","note":"亚太赛，难度介于 NOI 与 IOI 之间，是中国选手的重要练兵场。","ch":9},{"no":340,"t":"EGOI 2026 试题与逐题统计（第 6 届欧洲女子信息学奥林匹克）","sub":"","kind":"真题","auth":"","pub":"EGOI 2026 组织委员会 / EGOI 统计站","year":"2026","lv":["NOI","IOI"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"免费（题面与测试数据在线，附逐题平均分与满分人数）","url":"https://stats.egoi.org/tasks/","note":"2026 年 5 月 12—18 日在意大利切塞纳蒂科（Cesenatico）举行，两天各 4 题、每题 100 分、满分 800；59 个欧洲及非欧洲国家 250 名选手线下参赛，另有 9 国 33 人线上同步。八题与赛场数据（平均分 / 满分人数）：Day 1 为 ferriswheel 87.02 / 203、ovenmasters 40.75 / 36、biscuits 25.78 / 2、census 9.29 / 0；Day 2 为 wateringplants 82.85 / 174、cakes 60.59 / 76、foxfamilies 33.81 / 11、seatingplan 9.11 / 0。统计站把每题的分数分布、子任务满分率、各国选手逐题得分全部公开，这在 OI 类赛事里少见——可以据此判断「这题我卡住是常态还是异常」。用法：平均 80 以上的两题（ferriswheel、wateringplants）当读题与实现速度的热身；20—40 区间的四题（ovenmasters、biscuits、foxfamilies、cakes）适合专题突破，它们的考点集中在构造、贪心与树上计数；满分 0 人的 census 与 seatingplan 留作限时挑战，做不出属正常。整体难度介于 NOI 与 IOI 之间，题型分布更接近 IOI（构造题与子任务给分的比例明显高于国内赛）。局限：全英文题面，无中文翻译；部分题目为交互或构造，需按题面编译交互库；与 NOI 大纲不完全对齐，CSP/NOIP 段不适用。第 7 届（EGOI 2027）将在波兰华沙举行。","ch":9},{"no":341,"t":"IOI 2025 官方赛题包（ioi/task-archive 2025，6 题全量数据）","sub":"","kind":"真题","auth":"","pub":"IOI 官方（GitHub ioi/task-archive 仓库）","year":"2025","lv":["NOI","IOI"],"use":["赛前冲刺","实战训练"],"fx":["实战","深耕"],"how":"免费（开放仓库，可 clone 全量数据）","url":"https://github.com/ioi/task-archive/tree/master/2025","note":"第 37 届国际信息学奥林匹克（IOI 2025，2025 年夏在玻利维亚举行）的官方赛题包，托管在 IOI 官方 GitHub 仓库 task-archive 的 2025 目录下。Day1 三题：souvenirs、triples、worldmap；Day2 三题：festival、migrations、obstacles。每题一个子目录，结构统一：statement.pdf（英文题面）、problem.json（子任务划分与分值）、tests/（测试数据）、subtasks/、checker/（testlib 评测器）、graders/（交互与通信题的评测接口）、solutions/（官方标程）、attachments/（附加文件）。该目录最后一次提交在 2026 年 8 月 14 日，说明题解与数据已补齐，不是赛时的残缺版本。用法：这是少数能在本地 1:1 复现国际赛评测的资料——在 NOI Linux 2.0 上用 testlib 编译 checker、按 problem.json 分子任务跑分，可以精确得到「我拿了几分、丢在哪个子任务」，比在 OJ 上只看到一个总分有用得多；交互/通信题要把 graders 里的接口编进自己的程序，这一步是很多人卡住的地方。与 2026 年塔什干的赛题包（ioi2026.uz）同一体系，两年连着做能看出 IOI 近两年的题型配比变化（构造与交互比重上升）。局限：全英文，仓库不含中文题解与翻译；洛谷、oj.uz 有对应题但题号与子任务分值与官方不完全一致，对分数时以本仓库为准；单题数据包体积不小，clone 时建议用 --depth 1 或按目录稀疏检出。","ch":9},{"no":342,"t":"IOI 2026 中国国家集训队集中培训与精英培训题目及数据","sub":"","kind":"真题","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","IOI"],"use":["专题突破","实战训练"],"fx":["实战","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2026-01-22/859428.shtml","note":"2026 年 1 月 22 日发布。第 38 届 IOI 中国国家集训队集中培训与精英培训（2025 年 12 月 1—5 日，北京大学）三天共 9 题：异形工厂（shapez）、字符串问题（string）、三选二（three）、深红（art）、小丑大师的荣耀（balatro）、奇迹（miracle）、无题（nameless）、复读机（repeater）、解开尘封的序列（sequence），题面 PDF 与测试数据以 CC BY-NC 授权开放下载。难度对标国家队选拔、整体高于 NOI，是省队以上选手少见的「非公开赛制」训练材料；建议按「3 题 5 小时、先写满部分分」的方式使用，而不是当普通题库刷。","ch":9},{"no":343,"t":"IOI 2026 试题与题解（第 38 届国际信息学奥林匹克，塔什干）","sub":"","kind":"真题","auth":"","pub":"IOI 2026 组织委员会 / IOI 官方题库","year":"2026","lv":["NOI","IOI"],"use":["实战训练","专题突破"],"fx":["实战"],"how":"免费（CC-BY 4.0，含题面、附件与测试数据）","url":"https://ioi2026.uz/tasks","note":"2026 年 8 月 9—16 日在乌兹别克斯坦塔什干举行的第 38 届 IOI，赛后官网把全部题目按 CC-BY 4.0 开放：正赛两天各 3 题、每题 5 小时 —— Day 1 为 Ball Machine（Andy Wu，澳大利亚）、Monuments（米田雅崇、米田博孝，日本）、Tiling Game（Juheon Song，韩国）；Day 2 为 Classroom Game（Samuel Trajtenberg、Boris Hall，英国）、Magic City（米田兄弟，日本）、Partition（YoungBin Park，韩国）。另有 4 道练习赛题（A + B Queries、Duplicated Binary Strings、Boring Game、Magic Trick）用于熟悉交互与评测环境。每道题给三样东西：官方英文题面 PDF、附件包（样例与交互库/头文件），以及托管在 GitHub ioi/task-archive 的完整测试数据与补充材料——这一条最关键，意味着可以本地搭建评测、按子任务逐档验证部分分，而不是只能读到题面。用法上它属于「上限参照」而非训练主线：IOI 题的思维密度远高于 NOI，直接开做容易卡死，正确用法是赛前专题突破时挑一两道，先读题面自己想 40 分钟、写下子任务划分，再看测试数据规模验证复杂度判断，最后对照各国选手的赛场实现（stats.ioinformatics.org 有逐题得分分布）看差距在哪一档。局限：全英文，题面长且细节多（交互题与构造题占比高），没有官方中文翻译；难度与 NOI 大纲不对齐，CSP/NOIP 段完全不适用；附件里的交互库需要按题面说明编译，Windows 下容易卡在编译脚本上，建议在 NOI Linux 2.0 环境里做。","ch":9},{"no":344,"t":"Min_25 筛与洲阁筛","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/math/number-theory/min-25/","note":"亚线性求积性函数前缀和。属于「记住了就能用、推不出来」的类型，建议直接背模板 + 理解两轮递归。","ch":9},{"no":345,"t":"NOI 2026 题目及数据","sub":"","kind":"真题","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2026-07-27/918389.shtml","note":"2026 年 7 月 27 日随赛后资料发布，含 NOI 2026 全部试题目面、测试数据与题解。NOI 级真题的测试数据尤其难得，可用于自建评测、验证部分分策略；建议在省选后按「限时 5 小时、全真环境」使用。","ch":9},{"no":346,"t":"NOI 冬令营 2026 题目及数据","sub":"","kind":"真题","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","省选"],"use":["实战训练","赛前冲刺"],"fx":["实战"],"how":"免费","url":"https://www.noi.cn/zxzy/lnzl/jszl/2026-02-12/861342.shtml","note":"2026 年 2 月 12 日发布。冬令营试题历来是当年命题风格的风向标，难度介于省选与 NOI 之间，且常有新题型首次出现。适合省选前一个月做一次限时模拟，用于校准「难题能拿多少部分分」。","ch":9},{"no":347,"t":"NOI 历年真题","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn","year":"1984","lv":["NOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"免费 / 洛谷题库","url":"https://www.noi.cn/xw/","note":"两天六题制，难度陡增。建议在省队集训后期成套做，且必须按 5 小时/场严格计时。","ch":9},{"no":348,"t":"NOI 历年试题","sub":"","kind":"真题","auth":"CCF","pub":"noi.cn","year":"1984-至今","lv":["NOI"],"use":["赛前冲刺","教练备课"],"fx":["实战"],"how":"官网 / 题库","url":"https://www.noi.cn/","note":"正赛原题。做近十年即可，更早的题风格差异大。","ch":9},{"no":349,"t":"生成函数与组合计数","sub":"","kind":"题解","auth":"OI Wiki","pub":"oi-wiki.org","year":"2018","lv":["NOI","IOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://oi-wiki.org/math/poly/egf/","note":"OGF/EGF、卡特兰、斯特林、拆分数。计数题从「硬推」升级到「套模型」的分界线。","ch":9},{"no":350,"t":"IOI 历年试题","sub":"","kind":"真题","auth":"IOI","pub":"ioinformatics.org","year":"1989-至今","lv":["IOI"],"use":["赛前冲刺"],"fx":["实战"],"how":"官网 / oj.uz","url":"https://ioinformatics.org/","note":"国际赛原题，交互与构造题比例高。冲国家队必刷。","ch":9},{"no":351,"t":"OI Wiki 专题页","sub":"","kind":"课程","auth":"OI Wiki 社区","pub":"oi-wiki.org","year":"2018","lv":["通用"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://oi-wiki.org/","note":"严格说不是课程，但每个专题页都有「例题 + 代码 + 复杂度」，当微课程用完全够。","ch":10},{"no":352,"t":"AcWing 算法基础课","sub":"","kind":"课程","auth":"闫学灿（yxc）","pub":"acwing.com","year":"2018","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["深耕"],"how":"付费","url":"https://www.acwing.com/activity/content/11/","note":"从排序、二分、高精度讲到图论、DP，每节配 5–10 道题。零基础一年内的主线课，公认性价比最高。","ch":10},{"no":353,"t":"USACO Guide","sub":"","kind":"课程","auth":"USACO Guide 社区","pub":"usaco.guide","year":"2020","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["体系学习","查漏补缺"],"fx":["深耕","方法论"],"how":"免费","url":"https://usaco.guide/","note":"把知识点、讲解、配套题、难度分级串成一条路径。英文过关的话，这是最好的免费课程体系。","ch":10},{"no":354,"t":"USACO Training Gateway","sub":"","kind":"课程","auth":"USACO","pub":"train.usaco.org","year":"1998","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["实战"],"how":"免费","url":"https://train.usaco.org/","note":"老牌章节式训练系统，按章解锁。节奏慢但地基扎实，适合耐得住性子的初学者。","ch":10},{"no":355,"t":"中国大学 MOOC","sub":"","kind":"课程","auth":"高等教育出版社","pub":"icourse163.org","year":"2014","lv":["CSP-J","CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"免费（部分认证收费）","url":"https://www.icourse163.org/","note":"国内高校的数据结构、算法、离散数学课程。想补「科班底子」又不想读英文时，从这里挑一门跟完。","ch":10},{"no":356,"t":"代码随想录","sub":"","kind":"课程","auth":"程序员 Carl","pub":"programmercarl.com","year":"2020","lv":["CSP-J","CSP-S"],"use":["入门自修","体系学习"],"fx":["实战"],"how":"免费（开源）","url":"https://programmercarl.com/","note":"以题带学的系统路线图，每题都有动画与多语言实现。入门期最容易坚持下来的一套材料。","ch":10},{"no":357,"t":"洛谷网校","sub":"","kind":"课程","auth":"洛谷","pub":"luogu.com.cn","year":"2019","lv":["CSP-J","CSP-S","NOIP"],"use":["入门自修","赛前冲刺"],"fx":["实战"],"how":"部分付费","url":"https://www.luogu.com.cn/","note":"中文体系化课程，与题库打通。自学能力弱的选手可以借它建立节奏。","ch":10},{"no":358,"t":"董晓算法（B 站）","sub":"","kind":"课程","auth":"董晓","pub":"B 站","year":"2019","lv":["CSP-J","CSP-S","NOIP"],"use":["入门自修","查漏补缺"],"fx":["速查"],"how":"免费","url":"https://space.bilibili.com/385421622","note":"单知识点短讲，画图细致、语速慢。哪里不会点哪里，是最适合「补洞」的中文视频资源。","ch":10},{"no":359,"t":"2026 年第四期 NOI 教师培训（南京站，中级/初级）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会（NOI 官网）","year":"2026","lv":["CSP-S","NOIP","省选"],"use":["教练备课"],"fx":["方法论"],"how":"线下（初级可线上），需报名","url":"https://www.noi.cn/jspx/2026-10-20/941705.shtml","note":"2026 年 10 月 20 日发布，南京外国语学校承办，2026 年 12 月 7—13 日举办（7 日下午报到）；中级仅限现场，初级可选现场或线上。这份通知的价值不在「报名」，而在它把八位一线教练的讲课专题摊开成了一张「大纲知识点 → 教学切入角度」的映射表：艾庆兴（西安铁一中）《从整除同余到计数原理》、张超（南京外国语学校）《树与图的建模与经典问题》、王晓鹏（广州大学附中）《从暴力到最优的思维跃迁》、诸一行（浙江余姚中学）《动态规划的状态设计与教学》、周祖松（重庆育才中学）《数据的容器与秩序》、肖然（北大附中）《CSP-J 考点规律与解题思路》、梁冠健（佛山石门中学）《二分与倍增的对数级智慧》、宋新波（北京海淀稻香湖学校）《化繁为简的算法思想》。看得出选题逻辑：数论—图论—搜索思维—DP—数据结构—初赛规律—二分倍增—算法思想，正好是省选段最难的八块，且每块都落在「怎么讲」而不是「讲什么」上。对教练的直接用法：拿这八个标题给自己排一学期专题课，或对照检查本校教案缺哪一块。局限：通知只给专题名与讲师单位，不给讲义、课件与录像，培训内容本身不公开；线下名额与报名条件见通知原文，且与教师资质等级挂钩。","ch":10},{"no":360,"t":"AcWing 算法提高课","sub":"","kind":"课程","auth":"闫学灿（yxc）","pub":"acwing.com","year":"2019","lv":["CSP-S","NOIP","省选"],"use":["专题突破","体系学习"],"fx":["深耕"],"how":"付费","url":"https://www.acwing.com/activity/content/16/","note":"提高组到省选的核心专题：树形 DP、状压、单调队列、斜率优化、AC 自动机、网络流。跟完基础课再上。","ch":10},{"no":361,"t":"Berkeley CS61B（数据结构）","sub":"","kind":"课程","auth":"UC Berkeley","pub":"datastructur.es","year":"2014","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"免费（全套公开）","url":"https://sp21.datastructur.es/","note":"项目驱动的数据结构课，从零实现并查集、KD 树、 Trie。做完项目对「数据结构为什么这样设计」有体感。","ch":10},{"no":362,"t":"CS 97SI（斯坦福竞赛编程）","sub":"","kind":"课程","auth":"Stanford","pub":"stanford.edu","year":"2012","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"免费讲义","url":"https://web.stanford.edu/class/cs97si/","note":"专为竞赛设计的短课程，讲义精简，一天能刷完一个专题。","ch":10},{"no":363,"t":"Codeforces EDU","sub":"","kind":"课程","auth":"Codeforces","pub":"codeforces.com/edu","year":"2019","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["实战"],"how":"免费","url":"https://codeforces.com/edu/courses","note":"每个专题配讲解 + 阶梯题单，学完立刻判题。性价比最高的免费课程之一。","ch":10},{"no":364,"t":"Codeforces EDU（算法教程）","sub":"","kind":"课程","auth":"Codeforces","pub":"codeforces.com","year":"2017","lv":["CSP-S","NOIP","省选"],"use":["专题突破"],"fx":["实战"],"how":"免费","url":"https://codeforces.com/edu/courses","note":"每个专题一节短课 + 若干阶梯题，带即时判题。后缀数组、线段树、DSU 等专题的「最短路径」。","ch":10},{"no":365,"t":"Princeton Algorithms（Coursera）","sub":"","kind":"课程","auth":"R. Sedgewick, K. Wayne","pub":"Coursera","year":"2012","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"免费旁听","url":"https://www.coursera.org/learn/algorithms-part1","note":"配套《Algorithms, 4th》。有自动判题与面试题，讲得慢但极扎实，适合打底子。","ch":10},{"no":366,"t":"UCF COP 4516 Contest Problem Solving（中佛罗里达大学竞赛解题课）","sub":"","kind":"课程","auth":"","pub":"University of Central Florida","year":"2025","lv":["CSP-S","NOIP","省选"],"use":["体系学习","教练备课","专题突破"],"fx":["方法论","实战"],"how":"免费","url":"https://www.cs.ucf.edu/~dmarino/progcontests/cop4516/spr2025/","note":"Arup Guha 主讲的一学期竞赛解题课，2025 春季完整课表、讲义、样例代码、题单与赛题存档全部公开。15 周专题顺序：暴力→贪心→树→Trie→图（DFS/BFS）→图（MST/最短路）→数学（扩欧、前缀和、最大子段）→网络流（Ford-Fulkerson/Edmonds-Karp/Dinic）→DP 两讲（LCS/背包/LIS、编辑距离/矩阵连乘）→二维几何（含凸包）→二分应用→树状数组，每周配「Written Notes」一页纸讲义、Java/C++/Python 三语样例代码、练习题与个人赛/团队赛题目存档（附题解要点）。对教练的价值在可直接复用：讲义是 1 小时专题课的现成骨架，三语代码便于对照语言细节，contest archive 是成套团队赛。局限：ICPC 导向，图论与网络流比重高于 NOI 大纲，而线段树、平衡树、树套树等国内高频数据结构几乎不涉及，不能替代《算法竞赛进阶指南》；部分练习需 Kattis/UVA 账号提交。","ch":10},{"no":367,"t":"中国大学 MOOC《算法设计与分析》（北大）","sub":"","kind":"课程","auth":"北京大学","pub":"icourse163.org","year":"2015","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"免费","url":"https://www.icourse163.org/","note":"中文授课、体系完整，覆盖分治、DP、贪心、图算法、NP 完全性。适合作为学校课程的补充。","ch":10},{"no":368,"t":"学堂在线","sub":"","kind":"课程","auth":"清华大学","pub":"xuetangx.com","year":"2013","lv":["CSP-S","NOIP","省选"],"use":["体系学习"],"fx":["深耕"],"how":"免费（部分认证收费）","url":"https://www.xuetangx.com/","note":"清华系课程平台，邓俊辉《数据结构》正式版就在这里。配套习题与判题，比看视频更有效。","ch":10},{"no":369,"t":"数据结构（清华）","sub":"","kind":"课程","auth":"邓俊辉","pub":"学堂在线 / 中国大学 MOOC","year":"2013","lv":["CSP-S","NOIP"],"use":["体系学习"],"fx":["深耕"],"how":"免费","url":"https://www.xuetangx.com/","note":"中文数据结构课的天花板。配套教材与习题解析，红线画得极清楚。","ch":10},{"no":370,"t":"灵茶山艾府（B 站 / 题解）","sub":"","kind":"课程","auth":"灵茶山艾府","pub":"B 站 / 洛谷","year":"2020","lv":["CSP-S","NOIP","省选"],"use":["专题突破","查漏补缺"],"fx":["深耕"],"how":"免费","url":"https://space.bilibili.com/206214","note":"周赛题解与专题精讲，思路清晰、代码干净。DP 与图论系列尤其值得跟着做。","ch":10},{"no":371,"t":"AtCoder Library Practice","sub":"","kind":"课程","auth":"AtCoder","pub":"atcoder.jp","year":"2020","lv":["NOIP","省选"],"use":["查漏补缺"],"fx":["实战"],"how":"免费","url":"https://atcoder.jp/contests/practice2","note":"把常用数据结构与算法做成模板库，配套验证题。写完自己模板后来这里对答案。","ch":10},{"no":372,"t":"MIT OCW 6.006（算法导论）","sub":"","kind":"课程","auth":"MIT","pub":"ocw.mit.edu","year":"2011","lv":["NOIP","省选","NOI"],"use":["体系学习"],"fx":["深耕"],"how":"免费（视频 + 讲义 + 作业）","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-fall-2011/","note":"完整公开课，讲得比 CLRS 好懂。配套 problem set 有解答，适合边看边练。","ch":10},{"no":373,"t":"NOI 2025 冬令营授课与交流活动现场视频（14 场）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会（NOI 官网视频专栏）","year":"2025","lv":["NOIP","省选","NOI"],"use":["教练备课","专题突破"],"fx":["方法论","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/hdsp/2025-04-23/841659.shtml","note":"2025 年 4 月 23 日上线。第 42 届全国青少年信息学奥林匹克冬令营于 2025 年 1 月 17—24 日在绍兴举行（绍兴一中教育集团承办），第一、第二课堂共 14 场讲座全部录像。第一课堂偏理论与前沿：中科院计算所孙晓明「随机性与算法设计」、北大王迪「从模拟退火到概率编程」、清华郑勤锴「大模型时代的代码生成新范式」、清华毛嘉怡「稀疏图上更快的单源最短路算法」，以及 IOI 2024 国家队周康阳「浅谈非确定性算法」、沈吉滪「图论与连通性问题选讲」、郭羽冲「思维型题目选讲」、黄洛天「数据结构问题选讲」。第二课堂六场是纯考点课，主讲均为常年带出集训队选手的 NOI 名师：熊超「经典分治算法之美」、谷多玉「数据结构—线段树」、黄新军「网络流算法及其应用」、王晓鹏「线段树及其应用」、林鸿「容斥原理」、张新钢「浅谈贪心算法在信息学奥赛中的呈现」。对教练而言第二课堂可直接当课件骨架——线段树两讲（谷多玉讲结构与合并、王晓鹏讲应用）恰好覆盖 27.4 的「维护什么」与「怎么合并」两条主线，容斥与贪心两讲对应 29.3、24.6。第一课堂里毛嘉怡的稀疏图最短路（Dijkstra 在稀疏图上的优化与基数堆）是 28.2 的进阶补充，市面上教材很少写。局限：视频同样在 CCF 数字图书馆（合集 7456187809908736），页面只有清单没有时间轴；「大模型时代的代码生成」「概率编程」偏科研视野，备赛直接收益有限。","ch":10},{"no":374,"t":"算法设计与分析（MIT 6.006）","sub":"","kind":"课程","auth":"MIT OCW","pub":"ocw.mit.edu","year":"2011","lv":["NOIP","省选"],"use":["体系学习"],"fx":["深耕","方法论"],"how":"免费公开课","url":"https://ocw.mit.edu/","note":"讲复杂度与算法正确性最严谨的入门课。英文授课，配讲义，适合补理论。","ch":10},{"no":375,"t":"APIO 2025 讲者授课现场视频（5 场）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会（NOI 官网视频专栏）","year":"2025","lv":["省选","NOI","IOI"],"use":["专题突破","赛前冲刺"],"fx":["方法论","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/hdsp/2025-06-09/844100.shtml","note":"2025 年 6 月 9 日上线。APIO 2025 中国区活动于 5 月 15—19 日在无锡举办（江苏省锡山高级中学承办），五场授课全部录像，讲者为 NOI 2022 金牌选手罗思远与代表中国出征 IOI 2025 的刘恒熙、刘海峰、陈昕阳、范斯喆。五讲题目：电阻网络和随机游走（罗思远）、博弈理论入门（刘恒熙）、图论问题的若干解题方法（刘海峰）、集合幂级数在子图计数问题上的应用（陈昕阳）、构造类问题的若干解题方法（范斯喆）。这份选题的针对性很强：「电阻网络 + 随机游走」是树上/图上期望的通用建模工具，能把「等概率游走求期望步数」这类题从列方程硬解变成解线性方程组或直接用有效电阻性质；「集合幂级数做子图计数」是 29.10 生成函数一节里集合幂级数（subset convolution）在计数题上的落地，属省选到 NOI 的硬考点；博弈与构造两讲则分别补 29.6 与 24 章之间的空白。与 2026 年那一辑（#323）互为前后届，两辑合看可以观察同一批讲者两年的选题迁移。局限：视频托管在 CCF 数字图书馆专栏（本页给合集入口 dl.ccf.org.cn/albumList/getMeetingDetail7541198265288704），逐场无时间轴；选手视角讲题偏「思路从哪来」，证明与实现细节仍需回教材补齐。","ch":10},{"no":376,"t":"APIO 2026 中国区活动讲座现场视频（7 场）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会（NOI 官网视频专栏）","year":"2026","lv":["省选","NOI","IOI"],"use":["专题突破","赛前冲刺","教练备课"],"fx":["方法论","深耕"],"how":"免费","url":"https://www.noi.cn/zxzy/hdsp/2026-06-09/902042.shtml","note":"2026 年 6 月 9 日上线。APIO 2026 中国区活动于 5 月 7—11 日在北京举办（CCF 主办、北大附中承办），期间七场讲座全程录像，讲者为杨耀良（NOI 2017 金）、谢梓涵（北大，NOI 2023 金）、李静榕（清华，NOI 2024 金）与 IOI 2026 中国队四人许淇文、刘家炜、赵晟昊、何宇翔。七讲题目分别为：量化分析与流式因子计算基础；ICPC 构造题与 Ad-Hoc 题选讲；区间最值操作线段树介绍与复杂度证明；格路计数方法；莫队与范围修改查询问题；演绎推理类逻辑博弈；图论选讲——生成树的应用。这份目录本身就是一张省选到 NOI 级的知识地图：区间最值操作与复杂度证明（Segment Tree Beats 一脉）、格路计数（反射原理与行列式）、莫队配合范围修改、生成树的应用，四项都正好落在正编第 27—31 章的薄弱处，可与 27.4、31.6、29.3 对照看。两点局限：视频托管在 CCF 数字图书馆，需从本页链接跳转，部分条目要登录；讲者以选手视角切入，证明与实现细节不如 OI Wiki 系统，适合作为「知道该往哪深挖」的索引，不能替代教材。","ch":10},{"no":377,"t":"AcWing 算法进阶课","sub":"","kind":"课程","auth":"闫学灿（yxc）","pub":"acwing.com","year":"2020","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"付费","url":"https://www.acwing.com/activity/content/31/","note":"省选后期内容：平衡树、树套树、点分治、多项式、生成函数。难度陡，需先有 300 题以上积累。","ch":10},{"no":378,"t":"CS 3233（NUS 竞赛编程）","sub":"","kind":"课程","auth":"Steven Halim","pub":"NUS","year":"2010","lv":["省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费讲义","url":"https://www.comp.nus.edu.sg/~stevenha/","note":"《Competitive Programming》作者的课程，与红皮书配套，体系完整。","ch":10},{"no":379,"t":"CCF NOI 冬令营 2026 第一课堂（CCF 数字图书馆）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","省选"],"use":["专题突破","教练备课"],"fx":["深耕","方法论"],"how":"公开链接","url":"https://dl.ccf.org.cn/video/videoDetail.html?id=7948566377547776","note":"NOI 冬令营 2026 第一课堂与集训队选手论文交流的完整录像，2026 年 3 月上线 CCF 数字图书馆。含「几种数学理论在 OI 中的应用」「交互、通信选讲」「欧拉数问题」「如何写出没有 Bug 的程序——形式化证明」「大模型技术概览」等专题，讲者为国家集训队队员与授课教师，深度明显高于公开课。","ch":10},{"no":380,"t":"CCF NOI 集训营 2026 报到通知（附日程）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","IOI"],"use":["赛前冲刺","教练备课"],"fx":["方法论"],"how":"免费","url":"https://www.noi.cn/xw/2026-11-06/946602.shtml","note":"2026 年 11 月 6 日发布。2026 全国青少年信息学奥林匹克国家队集训营于 12 月 7—11 日在北京举行，同期举办 IOI 2027 精英培训；活动地点北京航空航天大学（海淀区学院路 37 号），住宿与报到在北京唯实国际文化交流中心（学院路 39 号），报到时间为 12 月 7 日 9:00—14:20，当天下午即安排试机，住宿费由 CCF 承担。附「NOI 集训营 2026 日程」PDF 可直接下载。对不在营内的读者，价值在日程本身：它把国家队一周的训练节奏（每天几个专题、几场模拟、几轮讲评）完整暴露出来，教练照此排校内冬训的强度最省事；也标定了 12 月上旬这个窗口——NOIP（11 月 28 日）结束后两周即进入集训营，省队选手的冬训应从 12 月初就启动，而不是等到寒假。","ch":10},{"no":381,"t":"CCF 关于举办 IOI 2027 精英培训的通知","sub":"","kind":"课程","auth":"","pub":"中国计算机学会","year":"2026","lv":["NOI","IOI"],"use":["赛前冲刺","教练备课"],"fx":["方法论"],"how":"免费","url":"https://noi.cn/xw/2026-08-17/924463.shtml","note":"2026 年 8 月 17 日发布：与 CCF NOI 集训营 2026 同期举办 IOI 2027 精英培训，培训期 2026 年 9—12 月，12 月在北京集中培训。报名门槛是「参加过 NOI 2026 全国赛」，CCF 按 NOI 2026 成绩遴选，须以学校为单位由一名指导教师统一报送（报名已于 2026 年 9 月 1 日 15:00 截止）。它的价值在于这是省队之外唯一能与国家集训队同步训练的通道：日常训练、作业、集中培训全同步，但不参与 IOI 2027 国家队选拔，结业发证书。对教练而言，它是判断「金牌线以下、省队以上」这一档选手上升路径的官方依据；对选手而言，它把 NOI 结束到次年省选之间的空窗期接上了高强度训练。","ch":10},{"no":382,"t":"CMU 15-295 Competition Programming and Problem Solving","sub":"","kind":"课程","auth":"","pub":"卡内基梅隆大学（Danny Sleator）","year":"2026","lv":["NOI","IOI"],"use":["专题突破","实战训练"],"fx":["实战","方法论"],"how":"公开链接","url":"https://contest.cs.cmu.edu/295/","note":"由伸展树（Splay）与链路剖分的提出者 Danny Sleator 开设，2026 秋季学期仍在更新（f26 页面最后修改于 2026 年 10 月 29 日）。组织方式是「每周一个主题：30 分钟讲授 + 2 小时在 Codeforces 上打 3—5 题的课程赛」，讲义、C++ 代码、题解与讲座录像全部公开，主题按图搜索、最短路、最小生成树、网络流等经典块推进，另有 2015 年至今的全部历史学期页面。价值不在内容深度而在节奏设计——讲完立刻限时实战，可直接照搬为校队周训模板；题目本身都在 Codeforces 上可复现，无需翻墙找题面。","ch":10},{"no":383,"t":"CMU 15-451（算法设计与分析）","sub":"","kind":"课程","auth":"Carnegie Mellon University","pub":"cs.cmu.edu","year":"2015","lv":["NOI","IOI"],"use":["专题突破","教练备课"],"fx":["深耕"],"how":"免费（讲义与作业）","url":"https://www.cs.cmu.edu/~15451-f23/","note":"概率分析、随机化、近似算法、摊还分析。想写高质量集训队论文，这里的工具最全。","ch":10},{"no":384,"t":"NOI 冬令营 2026 讲座与交流活动现场视频（14 场）","sub":"","kind":"课程","auth":"","pub":"中国计算机学会（NOI 官网视频专栏）","year":"2026","lv":["NOI","IOI"],"use":["教练备课","专题突破"],"fx":["方法论"],"how":"免费","url":"https://www.noi.cn/zxzy/hdsp/2026-03-25/902063.shtml","note":"2026 年 3 月 25 日上线。第 43 届全国青少年信息学奥林匹克冬令营于 2026 年 2 月 6—13 日在青岛举行（青岛城阳一中承办），第一、第二课堂合计 14 场讲座全部录像。第一课堂偏前沿与经验：中国人民大学赵鑫教授、清华大学王宏宁博士、北京大学熊英飞博士、Google 苏黎世钟诚，以及 IOI 2025 国家队刘恒熙、范斯喆、陈昕阳、刘海峰；第二课堂由六位 NOI 名师领衔——北京 101 中学董华星、杭州二中李建、人大附中梁霄、华南师大附中梁泽贤、深圳耀华实验刘溯、山大附中杨培君，内容是大纲知识点的系统梳理与赛题分析。同场还有国家集训队论文交流，队员报告集中在算法优化、数据结构创新与问题建模三条线。对教练的价值集中在第二课堂：这六位常年带出集训队选手，讲法即「怎么把知识点讲给学生听」，和只给结论的教材互补。局限：视频同样在 CCF 数字图书馆专栏内，页面只给合集入口，不提供逐场时间轴；第一课堂的四个高校报告面向科研视野，对备赛的直接帮助有限，不必按顺序全看。","ch":10},{"no":385,"t":"Stanford CS161（算法设计与分析）","sub":"","kind":"课程","auth":"Stanford University","pub":"web.stanford.edu","year":"2018","lv":["NOI","IOI"],"use":["体系学习","专题突破"],"fx":["深耕"],"how":"免费（课件与作业）","url":"https://web.stanford.edu/class/cs161/","note":"分治、贪心、DP、网络流、NP 完全性的严谨课程。作业难度接近 NOI，讲证明的方法值得学。","ch":10},{"no":386,"t":"蒋炎岩（JYY）课程站","sub":"","kind":"课程","auth":"蒋炎岩（南京大学）","pub":"jyywiki.cn","year":"2019","lv":["NOI","IOI"],"use":["体系学习","教练备课"],"fx":["深耕"],"how":"免费","url":"https://jyywiki.cn/","note":"操作系统与程序设计课程的全套讲义、视频、实验。讲「程序在机器上到底怎么跑」，对常数优化有降维效果。","ch":10},{"no":387,"t":"IOI 官方 YouTube 频道","sub":"","kind":"课程","auth":"IOI","pub":"YouTube","year":"2018","lv":["IOI"],"use":["赛前冲刺"],"fx":["速查"],"how":"免费","url":"https://www.youtube.com/@IOI_official","note":"开幕式、颁奖、部分讲评与技术报告录像。了解国际赛氛围与命题取向的第一手材料。","ch":10},{"no":388,"t":"Arbiter","sub":"","kind":"工具","auth":"国内 OI 社区","pub":"开源","year":"2009","lv":["通用"],"use":["教练备课"],"fx":["速查"],"how":"免费","url":"","note":"与 Lemon 同期的评测系统，支持自定义评测脚本。","ch":11},{"no":389,"t":"Cena","sub":"","kind":"工具","auth":"国内 OI 社区","pub":"开源","year":"2007","lv":["通用"],"use":["教练备课"],"fx":["速查"],"how":"免费","url":"","note":"更早的评测系统，现在多见于老旧机房。了解即可。","ch":11},{"no":390,"t":"DOMjudge","sub":"","kind":"工具","auth":"DOMjudge 团队","pub":"domjudge.org","year":"2004","lv":["通用"],"use":["教练备课"],"fx":["速查"],"how":"免费开源","url":"https://www.domjudge.org/","note":"ICPC 官方评测系统，办校内赛最正规的选择。","ch":11},{"no":391,"t":"Lemon","sub":"","kind":"工具","auth":"国内 OI 社区","pub":"开源","year":"2010","lv":["通用"],"use":["教练备课"],"fx":["速查"],"how":"免费","url":"","note":"老牌评测机，界面朴素但稳定，很多学校仍在使用。","ch":11},{"no":392,"t":"CP Editor","sub":"","kind":"工具","auth":"CP Editor 社区","pub":"cpeditor.org","year":"2019","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["速查"],"how":"免费开源","url":"https://cpeditor.org/","note":"专为刷题设计：一键编译运行、自动抓样例、直接提交到多个 OJ。","ch":11},{"no":393,"t":"Code::Blocks","sub":"","kind":"工具","auth":"Code::Blocks 团队","pub":"codeblocks.org","year":"2005","lv":["CSP-J","CSP-S"],"use":["入门自修"],"fx":["速查"],"how":"免费","url":"https://www.codeblocks.org/","note":"轻量、跨平台，配置简单。比 Dev-C++ 稳定，适合替代。","ch":11},{"no":394,"t":"Dev-C++","sub":"","kind":"工具","auth":"Bloodshed / Orwell","pub":"orwelldevcpp","year":"2015","lv":["CSP-J"],"use":["入门自修"],"fx":["速查"],"how":"免费","url":"https://github.com/Embarcadero/Dev-Cpp","note":"国内中学机房标配。功能够用，调试弱，只建议入门期使用。","ch":11},{"no":395,"t":"LOJ — LeLe Online Judge（开源可自部署的 ACM/OI 双赛制评测系统）","sub":"","kind":"工具","auth":"","pub":"GitHub 开源项目 aiwandiannaodelele/LOJ（AGPL v3.0）","year":"2026","lv":["CSP-J","CSP-S","NOIP"],"use":["实战训练","教练备课"],"fx":["实战"],"how":"开源免费（Docker 一键部署，或 PM2 / Node.js 直接运行）","url":"https://github.com/aiwandiannaodelele/LOJ","note":"维护者于 2026 年 6 月 13 日在项目 Discussions #4 发布欢迎公告并列出特性，是本轮检索到的新评测工具。技术栈为 Next.js 16 + Prisma 7 + NextAuth v5 + Monaco 编辑器 + BlockNote 富文本；功能含题目系统（多测试点、自测样例）、ACM / OI 双赛制比赛（实时排名、公告、密码保护、独立题目副本）、训练题单、题目上下文感知的 AI 编程助教、可插拔评测引擎（OneCompiler 默认，可换 Judge0 / Runoob）、本地或 S3 兼容存储、以及限流/权限校验/IP 伪造与 SSRF 防护。部署给出 deploy.sh 一键脚本：Docker 默认 PostgreSQL、PM2 或裸 Node 默认 SQLite，也可上 Vercel / Netlify / Cloudflare Pages（配 Turso、Supabase 或 D1），首次访问 /init 建管理员。对学校的实际用途是自建校内 OJ：教练可独立出卷、按专题挂题单、组织模拟赛并导出排名，不必依赖公网平台的账号与题库开放程度；源码开放也便于本地加自己的题面格式或对接校内账号。特别提示名称冲突：它与本目录已收的 LibreOJ（loj.ac，2017 年起，Menci 维护，基于 Lyrio）完全无关，只是缩写相同，查资料时别混。局限：项目 2026 年才公开，稳定性、题库规模与社区支持远不及洛谷、HydroOJ、QOJ；默认评测引擎是把代码提交给第三方在线编译服务，而非本地隔离沙箱，正式认证（尤其 NOI 系列）绝不可用，仅适合练习与校内自测；AI 助教需自备模型密钥；AGPL v3.0 要求对外提供服务时公开修改后的源码。","ch":11},{"no":396,"t":"Oracle VM VirtualBox","sub":"","kind":"工具","auth":"Oracle","pub":"virtualbox.org","year":"2007","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"免费（开源）","url":"https://www.virtualbox.org/","note":"在家搭「考场同款」环境的首选宿主。建虚拟机时内存至少分 2 GB、磁盘 20 GB 以上，否则 NOI Linux 起不来。","ch":11},{"no":397,"t":"VMware Workstation Player","sub":"","kind":"工具","auth":"VMware（Broadcom）","pub":"vmware.com","year":"1999","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"个人免费","url":"https://www.vmware.com/products/workstation-player.html","note":"虚拟机体验比 VirtualBox 顺，图形性能更好。部分赛区考场用的就是它，提前熟悉操作可以少花十分钟。","ch":11},{"no":398,"t":"洛谷 IDE","sub":"","kind":"工具","auth":"洛谷","pub":"luogu.com.cn","year":"2019","lv":["CSP-J","CSP-S"],"use":["实战训练"],"fx":["速查"],"how":"免费（需登录）","url":"https://www.luogu.com.cn/ide","note":"浏览器里直接编译运行，机房没装编译器时的应急方案。不支持调试，只能看输出。","ch":11},{"no":399,"t":"Compiler Explorer (godbolt)","sub":"","kind":"工具","auth":"Matt Godbolt","pub":"godbolt.org","year":"2012","lv":["CSP-S","NOIP","省选","NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://godbolt.org/","note":"在线看汇编。查「为什么这行慢」、验证编译器是否向量化、确认 UB 被优化成什么，都靠它。","ch":11},{"no":400,"t":"Desmos 图形计算器","sub":"","kind":"工具","auth":"Desmos","pub":"desmos.com","year":"2011","lv":["CSP-S","NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.desmos.com/calculator","note":"画函数、解方程、拟合数据。推 DP 式子时把转移画出来，常能一眼看出单调性或凸性。","ch":11},{"no":401,"t":"GeoGebra","sub":"","kind":"工具","auth":"GeoGebra","pub":"geogebra.org","year":"2002","lv":["CSP-S","NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.geogebra.org/","note":"动态几何。计算几何题里判断「这两个圆到底怎么交」、验证旋转卡壳的边界情况，比手画准得多。","ch":11},{"no":402,"t":"NOI Linux 2.0","sub":"","kind":"工具","auth":"CCF","pub":"noi.cn","year":"2022","lv":["CSP-S","NOIP","NOI"],"use":["赛前冲刺"],"fx":["速查"],"how":"官网免费下载","url":"https://www.noi.cn/","note":"官方比赛环境。考前必须在同款环境里跑一遍代码，否则本地 AC 考场可能编译失败。","ch":11},{"no":403,"t":"Visual Studio Code","sub":"","kind":"工具","auth":"Microsoft","pub":"code.visualstudio.com","year":"2015","lv":["CSP-S","NOIP","省选","NOI"],"use":["体系学习","实战训练"],"fx":["速查"],"how":"免费","url":"https://code.visualstudio.com/","note":"配 C/C++ 插件 + 自定义 tasks.json 即可做单文件编译调试。日常开发与刷题主力。","ch":11},{"no":404,"t":"对拍脚本","sub":"stress test","kind":"工具","auth":"OI 通用做法","pub":"自建","year":"—","lv":["CSP-S","NOIP","省选"],"use":["实战训练","查漏补缺"],"fx":["方法论"],"how":"自己写","url":"","note":"暴力 + 随机数据 + 自动比对。把「为什么错」从猜测变成实验，是提分最快的习惯。","ch":11},{"no":405,"t":"GDB","sub":"","kind":"工具","auth":"GNU","pub":"gnu.org","year":"1986","lv":["NOIP","省选","NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.gnu.org/software/gdb/","note":"考场环境里唯一可靠的调试器。至少要会 break、run、next、print、bt。","ch":11},{"no":406,"t":"CF Polygon（出题系统）","sub":"","kind":"工具","auth":"Codeforces","pub":"polygon.codeforces.com","year":"2013","lv":["省选","NOI"],"use":["教练备课"],"fx":["深耕"],"how":"免费（需权限）","url":"https://polygon.codeforces.com/","note":"工业级出题流水线：生成器、对拍、validator、题面打包一条龙。校赛、省赛命题的标准工具。","ch":11},{"no":407,"t":"CLion","sub":"","kind":"工具","auth":"JetBrains","pub":"jetbrains.com","year":"2015","lv":["省选","NOI"],"use":["实战训练"],"fx":["速查"],"how":"付费 / 学生免费","url":"https://www.jetbrains.com/clion/","note":"调试体验最好的 C++ IDE。学生可申请免费授权，对大工程调试很有帮助。","ch":11},{"no":408,"t":"Wolfram Alpha","sub":"","kind":"工具","auth":"Wolfram Research","pub":"wolframalpha.com","year":"2009","lv":["省选","NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费 + 付费","url":"https://www.wolframalpha.com/","note":"符号积分、求和、递推求解。手推生成函数推不动时，让它先给出答案再反推过程。","ch":11},{"no":409,"t":"testlib.h","sub":"","kind":"工具","auth":"Mike Mirzayanov","pub":"GitHub","year":"2010","lv":["省选","NOI"],"use":["教练备课"],"fx":["深耕"],"how":"免费（开源）","url":"https://github.com/MikeMirzayanov/testlib","note":"出题用的 checker / validator 框架，几乎所有现代 OJ 都兼容。写好 checker 才谈得上「判题公平」。","ch":11},{"no":410,"t":"Valgrind","sub":"","kind":"工具","auth":"Valgrind 社区","pub":"valgrind.org","year":"2002","lv":["NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://valgrind.org/","note":"查越界与内存泄漏。RE 成谜时用它，比肉眼找快得多。","ch":11},{"no":411,"t":"perf","sub":"","kind":"工具","auth":"Linux 内核","pub":"kernel.org","year":"2009","lv":["NOI"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"","note":"定位常数瓶颈。TLE 但复杂度正确时，用它看热点函数。","ch":11},{"no":412,"t":"OI Wiki","sub":"","kind":"社区","auth":"OI Wiki 社区","pub":"oi-wiki.org","year":"2018","lv":["通用"],"use":["查漏补缺","专题突破"],"fx":["速查","深耕"],"how":"免费开源","url":"https://oi-wiki.org/","note":"中文竞赛知识的总索引。按知识点查、给代码、给复杂度、给例题，全书的知识地图以它为参照。","ch":12},{"no":413,"t":"Stack Overflow","sub":"","kind":"社区","auth":"Stack Exchange","pub":"stackoverflow.com","year":"2008","lv":["通用"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://stackoverflow.com/","note":"C++ 语法、STL 行为、编译器报错的解答库。「为什么 vector 迭代器失效」这类问题一搜就有。","ch":12},{"no":414,"t":"GeeksforGeeks","sub":"","kind":"社区","auth":"GeeksforGeeks","pub":"geeksforgeeks.org","year":"2009","lv":["CSP-J","CSP-S"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.geeksforgeeks.org/","note":"算法模板与解释的百科。质量不稳，适合查「这个数据结构长什么样」，不适合当教材通读。","ch":12},{"no":415,"t":"OI Wiki 英文镜像 / 社区分支","sub":"","kind":"社区","auth":"OI Wiki 社区","pub":"GitHub","year":"2018","lv":["CSP-J","CSP-S","NOIP","省选","NOI"],"use":["查漏补缺","教练备课"],"fx":["速查"],"how":"免费（开源）","url":"https://github.com/OI-wiki/OI-wiki","note":"全书 Markdown 源码。可以离线打包、可以自己改，也可以直接给学生发 PDF 版。","ch":12},{"no":416,"t":"洛谷讨论区","sub":"","kind":"社区","auth":"洛谷用户","pub":"luogu.com.cn","year":"2013","lv":["CSP-J","CSP-S","NOIP","省选"],"use":["查漏补缺"],"fx":["速查"],"how":"免费","url":"https://www.luogu.com.cn/discuss","note":"中文 OI 圈信息集散地：比赛公告、题目求助、经验帖。噪音大，但偶有真干货。","ch":12},{"no":417,"t":"Codeforces Blog（题解与教程）","sub":"","kind":"社区","auth":"Codeforces 社区","pub":"codeforces.com","year":"2010","lv":["CSP-S","NOIP","省选","NOI"],"use":["查漏补缺","专题突破"],"fx":["深耕"],"how":"免费","url":"https://codeforces.com/blog","note":"每场比赛官方 Editorial 都发在这里，另有大量高质量算法教程。英文，但术语固定，读十篇就顺了。","ch":12},{"no":418,"t":"演算法筆記","sub":"","kind":"社区","auth":"台湾师范大学","pub":"web.ntnu.edu.tw","year":"2010","lv":["CSP-S","NOIP"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"https://web.ntnu.edu.tw/~algo/","note":"繁体中文，图例极其丰富。看图示理解算法流程，比看代码快。","ch":12},{"no":419,"t":"Matrix67 博客","sub":"","kind":"社区","auth":"顾森","pub":"matrix67.com","year":"2005","lv":["NOIP","省选","NOI"],"use":["专题突破"],"fx":["深耕"],"how":"免费","url":"http://www.matrix67.com/blog/","note":"中文数学科普与算法随笔的经典。讲清了很多教材跳过的「为什么」，读起来像故事，思维密度却很高。","ch":12},{"no":420,"t":"cp-algorithms","sub":"e-maxx 英文版","kind":"社区","auth":"cp-algorithms 社区","pub":"cp-algorithms.com","year":"2015","lv":["NOIP","省选","NOI"],"use":["查漏补缺","专题突破"],"fx":["速查","深耕"],"how":"免费开源","url":"https://cp-algorithms.com/","note":"算法实现与证明的英文百科。卡在某个算法细节时，这里比博客可靠。","ch":12},{"no":421,"t":"hzwer 的博客","sub":"","kind":"社区","auth":"黄哲威（hzwer）","pub":"hzwer.com","year":"2013","lv":["NOIP","省选","NOI"],"use":["专题突破","查漏补缺"],"fx":["深耕"],"how":"免费","url":"https://hzwer.com/","note":"BZOJ 时代的题解重镇，分块、莫队、树套树的入门讲解至今仍是中文圈最好懂的一批。","ch":12},{"no":422,"t":"Computer Science StackExchange","sub":"","kind":"社区","auth":"Stack Exchange","pub":"cs.stackexchange.com","year":"2010","lv":["省选","NOI"],"use":["查漏补缺"],"fx":["深耕"],"how":"免费","url":"https://cs.stackexchange.com/","note":"理论问题（复杂度、可计算性、近似算法）的问答区。写论文找相关工作时特别有用。","ch":12},{"no":423,"t":"Mathematics StackExchange","sub":"","kind":"社区","auth":"Stack Exchange","pub":"math.stackexchange.com","year":"2010","lv":["省选","NOI","IOI"],"use":["查漏补缺"],"fx":["深耕"],"how":"免费","url":"https://math.stackexchange.com/","note":"组合计数、数论、概率的推导细节。看不懂论文里的「显然」时，这里常有完整展开。","ch":12},{"no":424,"t":"《Olympiads in Informatics》第 20 卷（IOI 学术期刊，2026）","sub":"","kind":"期刊","auth":"","pub":"维尔纽斯大学数学与信息学研究所 / IOI","year":"2026","lv":["NOI","IOI"],"use":["教练备课","专题突破"],"fx":["深耕"],"how":"免费（开放获取，可下载整卷或单篇）","url":"https://ioinformatics.org/page/ioi-journal","note":"OLYMPIADS IN INFORMATICS 由 IOI 社区与立陶宛维尔纽斯大学于 2007 年创办，每年夏季出一卷，与国际信息学奥林匹克同期举行的学术会议配套，第 20 卷已于 2026 年 6 月 19 日上线（主编 Valentina Dagienė，Scopus、Cabell、InfoBase 收录，完全开放获取，整卷与单篇 PDF 均可免费下载）。三段式栏目：研究论文（计算方法、算法与程序设计教学、自动评测系统、面向资优生的课程设计、训练环境与软件）、各国经验报告、书评与动态。对竞赛圈的实际价值在于它是「命题与评测」这条线唯一经同行评议的刊物：子任务给分制的实证效果、交互题与 output-only 题的技术实现、自动评测系统的沙箱与时限设定、各国集训体系的组织方式，都能在这里找到一手材料，比二手博客与公众号可靠得多；写校本课程、做题型趋势分析、给学校论证「为什么要上评测系统」时，这是最容易被采信的引用源。用法：先读各国经验报告（篇幅短、直接讲做法与踩过的坑），再按主题挑研究论文；每卷十余篇，一卷一下午能扫完。局限：全英文、年一卷、不含题解与代码，与 NOI 大纲不对齐；对选手本人的直接帮助有限，属教练与研究者向的资料。","ch":12},{"no":425,"t":"许淇文 IOI 2026 参赛总结","sub":"","kind":"社区","auth":"","pub":"NOI 官网「交流分享」栏目","year":"2026","lv":["NOI","IOI"],"use":["赛前冲刺"],"fx":["方法论","实战"],"how":"免费","url":"https://www.noi.cn/jlfx/2026-08-28/927310.shtml","note":"2026 年 8 月 28 日发布。IOI 2026 全球第一（498.27 分，中国队 3 金 1 银）的选手自述，重点不在题解而在赛场之外的判断：一是提前一天到赛地倒时差、备应急食品这类细节，二是把「他国选手命制的模拟赛」当作校准难度预期的标尺（文中提到韩国选手 Jaewon Son 的两道题，日本队长两题合计仅得 12 分），三是与多国选手交流训练方式。适合冲刺阶段用来对照自己的备赛节奏，不是模板材料。","ch":12}]};
